window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s12-205","number":205,"surah":12,"verses":[102],"references":[{"surah":12,"verses":[102]}],"verseLabel":"يوسف: 102","question":"ما دلالة الانتقال إلى خطاب النبي ﷺ بقوله ﴿ذلك من أنباء الغيب نوحيه إليك﴾؟","answer":"بعد اكتمال القصة استخرج دليل الوحي: لم يشهد النبي مؤامرة الإخوة، ومع ذلك جاءه خبرها المحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص479–484، تحت «علة الفصل في «ذلك من أنباء»؛ نكتة استعمال الإشارة للبعيد؛ فائدة ذكر النبأ دون الخبر؛ فن المذهب الكلامي»","url":""}]},{"id":"s12-206","number":206,"surah":12,"verses":[102],"references":[{"surah":12,"verses":[102]}],"verseLabel":"يوسف: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿وهم يمكرون﴾ بعد ﴿أجمعوا أمرهم﴾؟","answer":"﴿أجمعوا أمرهم﴾ يدل على عزمهم واتفاقهم على تدبيرهم، وجملة ﴿وهم يمكرون﴾ حال تصف ما صاحب ذلك من احتيال وإخفاء. والمضارع يستحضر صورة مكرهم كأنها مشاهدة، مع التصريح بأن النبي ﷺ لم يكن حاضرًا لديهم؛ فمعرفته بالتفاصيل من الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص483–486، تحت «بلاغة استعمال «أجمعوا» دون جمعوا؛ نكتة التعبير عن صنيعهم بالأمر؛ موقع جملة «وهم يمكرون»؛ نكتة التعبير بالمضارع «يمكرون»»","url":""}]},{"id":"s12-207","number":207,"surah":12,"verses":[103],"references":[{"surah":12,"verses":[103]}],"verseLabel":"يوسف: 103","question":"ما دلالة الواو في «وما أكثر الناس»، وما وجه البلاغة في التعريض، وما فائدة الاعتراض، وما النكتة البلاغية في حذف متعلق «حرصت»؟","answer":"يواسي النبي بأن وضوح القصة وحرصه لا يجبران القلوب؛ البلاغ عليه والهداية بيد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص487–489، تحت «دلالة الواو في «وما أكثر الناس»؛ بلاغة التعريض؛ فائدة الاعتراض؛ نكتة حذف متعلق «حرصت»»","url":""}]},{"id":"s12-208","number":208,"surah":12,"verses":[104],"references":[{"surah":12,"verses":[104]}],"verseLabel":"يوسف: 104","question":"ما النكتة البلاغية في استعمال ما في النفي وفائدته في قوله تعالى: ﴿وما تسألهم عليه من أجر﴾؟","answer":"ينفي أن تكون دعوة النبي طلبًا لأي منفعة مالية، وتؤكد «من» مع تنكير الأجر شمول النفي للقليل والكثير.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص493، تحت «نكتة استعمال ما في النفي وفائدته»","url":""}]},{"id":"s12-276","number":276,"surah":12,"verses":[104],"references":[{"surah":12,"verses":[104]}],"verseLabel":"يوسف: 104","question":"ما موقع قوله: ﴿إن هو إلا ذكر للعالمين﴾ بعد نفي طلب الأجر؟","answer":"يبين حقيقة القرآن وغايته: تذكير وهداية عامة للعالمين، لا وسيلة لتحصيل عوض ممن يدعوهم النبي.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص495، تحت «الموقع البياني لقوله «إن هو إلا ذكر للعالمين»»","url":""}]},{"id":"s12-277","number":277,"surah":12,"verses":[13],"references":[{"surah":12,"verses":[13]}],"verseLabel":"يوسف: 13","question":"ما دلالة التعريف في قول يعقوب: ﴿وأخاف أن يأكله الذئب﴾؟","answer":"«أل» هنا جنسية تشير إلى واحد مما عُرفت حقيقته في الذهن من غير قصد إلى التعيين، فهو لا يقصد ذئبًا بعينه، بل واحدًا من أفراد الجنس مما استقرّ في الذهن معرفته.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج1، ص109.","url":""}]},{"id":"s12-278","number":278,"surah":12,"verses":[30],"references":[{"surah":12,"verses":[30]}],"verseLabel":"يوسف: 30","question":"ما سر تذكير الفعل في قوله: ﴿وقال نسوة في المدينة﴾، وتأنيثه في الحجرات: ﴿قالت الأعراب﴾؟","answer":"جرى التعبير على قاعدة العربية في الإتيان بالمؤنث للدلالة على الكثرة بخلاف المذكر، فتذكير الفعل مع «النسوة» يدل على أنهن قلة، وتأنيثه مع «الأعراب» يدل على كثرتهم.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص180.","url":""}]},{"id":"s12-279","number":279,"surah":12,"verses":[90],"references":[{"surah":12,"verses":[90]}],"verseLabel":"يوسف: 90","question":"ما دلالة قول يوسف لإخوته: ﴿أنا يوسف وهذا أخي﴾، مع أنهم يعرفون أخاهم؟","answer":"أراد أن يخبرهم أنه أخوه وهو يعرفه حقًا كما عرفهم وهم له منكرون، فلم يخدعوه بشخص آخر يزعمون أنه أخوه، كما خدعوا أباهم حين جاؤوا بالبكاء وبالقميص والدم الكذب.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص67–68.","url":""}]},{"id":"s12-280","number":280,"surah":12,"verses":[96],"references":[{"surah":12,"verses":[96]}],"verseLabel":"يوسف: 96","question":"ما سر زيادة «أن» بعد «لمّا» في قوله: ﴿فلمّا أن جاء البشير ألقاه على وجهه﴾؟","answer":"زيدت لمناسبة حالة الانتظار والترقب التي كان فيها يعقوب، فقد كان شديد اللهفة على رؤية ولده يستطيل كل لحظة، ففصل بين «لمّا» ومجيء البشير إشارةً إلى الشعور باستطالة الوقت. ونظيره ﴿ولما أن جاءت رسلنا لوطًا﴾ في العنكبوت.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص109.","url":""}]},{"id":"s12-281","number":281,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"ما سر ذكر الإخراج من السجن دون البئر في قوله: ﴿وقد أحسن بي إذ أخرجني من السجن﴾؟","answer":"أُخرج من البئر إلى الرقّ والعبودية ثم إلى السجن بتهمة مخلّة بالشرف، فلا منّة في ذلك، أما إخراجه من السجن فكان إلى الإحسان إليه وجعله عزيز مصر، فاختلف الأمران.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص68–69.","url":""}]},{"id":"s12-282","number":282,"surah":12,"verses":[109],"references":[{"surah":12,"verses":[109]}],"verseLabel":"يوسف: 109","question":"ما دلالة العطف بالفاء في قوله: ﴿أفلم يسيروا في الأرض﴾؟","answer":"إذا كان ما بعدها مبنيًا على ما قبلها عُطف بالفاء. وقد قال قبلها: ﴿أفأمنوا أن تأتيهم غاشية من عذاب الله﴾، فالمعنى: ألا يسيرون فينظرون عاقبة من جاءتهم الغواشي من قبلهم؟ فالسياق داعٍ إلى التأمل والاتعاظ المترتب على ما سبق، فاستدعى الفاء.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص125.","url":""}]},{"id":"s12-283","number":283,"surah":12,"verses":[2],"references":[{"surah":12,"verses":[2]}],"verseLabel":"يوسف: 2","question":"ما سر التعبير بالإنزال في قوله: ﴿إنا أنزلناه قرآنًا عربيًا﴾، وبالجعل في الزخرف: ﴿إنا جعلناه قرآنًا عربيًا﴾؟","answer":"ذُكر بعدها في يوسف ما يتعلق بالإنزال: ﴿نحن نقص عليك أحسن القصص بما أوحينا إليك﴾، والسورة جواب لمن سأل عن القصة، فناسب ذكر الإنزال. أما الزخرف فالكلام على ما في أم الكتاب ﴿لدينا لعليّ حكيم﴾، وقد تردّد فيها لفظ الجعل إحدى عشرة مرة، في حين ورد الإنزال في يوسف ثلاث مرات وفي الزخرف مرة واحدة.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص97–98.","url":""}]},{"id":"s12-284","number":284,"surah":12,"verses":[4],"references":[{"surah":12,"verses":[4]}],"verseLabel":"يوسف: 4","question":"ما سر التعبير عن الإخوة بالكواكب دون النجوم، وتقديمها على الشمس والقمر في قوله: ﴿إني رأيت أحد عشر كوكبًا والشمس والقمر﴾؟","answer":"الكواكب توابع بخلاف النجوم، والإخوة توابع لوالديهم. وقُدّمت لأن المقام مقام تعظيم ليوسف، والإخوة أولى بتعظيم أخيهم والسجود له، وهو أهون من سجود الأبوين، ثم إنهم كانوا أسبق تعظيمًا له إذ عرفوه قبل أن يعلم به الأبوان.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص66.","url":""}]},{"id":"s12-285","number":285,"surah":12,"verses":[8],"references":[{"surah":12,"verses":[8]}],"verseLabel":"يوسف: 8","question":"ما دلالة اللام في قول الإخوة: ﴿لَيوسفُ وأخوه أحبّ إلى أبينا منا﴾؟","answer":"الأصل في هذه اللام أن يُؤتى بها في مواطن الردّ والإنكار والجواب، بخلاف «إنّ» التي هي لعموم التوكيد. والإخوة هنا منكرون على أبيهم تفضيله يوسف وأخاه عليهم، فجاءت اللام تعبيرًا عن هذا الإنكار.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج1، ص321.","url":""}]},{"id":"s12-286","number":286,"surah":12,"verses":[18],"references":[{"surah":12,"verses":[18]}],"verseLabel":"يوسف: 18","question":"ما دلالة القميص في قصة يوسف، من قوله: ﴿وجاؤوا على قميصه بدم كذب﴾؟","answer":"استُعمل القميص ثلاث مرات: بيّنةً مزوّرة على هلاكه هنا، ثم بيّنةً صحيحة على براءته حين قُدّ من دُبُر، ثم بيّنةً صحيحة على أنه حيّ وبشرى لأبيه وسببًا لردّ بصره. فكان بدايةً لحزن يعقوب ونهايةً له، ورافق ثلاث مراحل من حياة يوسف.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص70–71.","url":""}]},{"id":"s12-287","number":287,"surah":12,"verses":[58],"references":[{"surah":12,"verses":[58]}],"verseLabel":"يوسف: 58","question":"ما دلالة الجمع بـ«الإخوة» دون «الإخوان» في قوله: ﴿وجاء إخوة يوسف﴾؟","answer":"«الإخوة» جمع قلة و«الإخوان» جمع كثرة، وأكثر ما تُستعمل «الإخوة» في أخوّة النسب. وقد وردت في القرآن كلها بمعنى النسب، إلا في ﴿إنما المؤمنون إخوة﴾، لأنهم بمنزلة الإخوة من النسب، وإخوة يوسف إخوته من أبيه.","sources":[{"label":"فاضل السامرائي، معاني الأبنية في العربية، ص120.","url":""}]},{"id":"s12-288","number":288,"surah":12,"verses":[65],"references":[{"surah":12,"verses":[65]}],"verseLabel":"يوسف: 65","question":"ما سر إثبات الياء في قوله: ﴿يا أبانا ما نبغي﴾، وحذفها في الكهف: ﴿ذلك ما كنا نبغِ﴾؟","answer":"الطعام في يوسف هو ما يبغون حقًا وهو سبب رحلتهم، فذُكر الفعل كاملًا. أما نسيان الحوت في الكهف فليس بغية موسى على الحقيقة، بل علامة على موضع بغيته، فحُذف من الفعل إشارة إلى عدم إرادة الحدث على وجه التمام.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص21.","url":""}]},{"id":"s12-289","number":289,"surah":12,"verses":[85],"references":[{"surah":12,"verses":[85]}],"verseLabel":"يوسف: 85","question":"ما سر حذف «لا» من جواب القسم في قوله: ﴿تالله تفتأ تذكر يوسف﴾؟","answer":"لم تُحذف «لا» من جواب القسم في القرآن إلا هنا، لأن المقسَم عليه غير متحقق؛ فالإخوة لا يعلمون أن أباهم سيظل يذكره حتى يفسد أو يهلك، فهذا من الغيب وقد قالوه ظنًا، فلم يؤكدوا الجواب كما أُكّد في المواضع الأخرى.","sources":[{"label":"فاضل السامرائي، الجملة العربية والمعنى، ص253–254.","url":""}]},{"id":"s12-290","number":290,"surah":12,"verses":[86],"references":[{"surah":12,"verses":[86]}],"verseLabel":"يوسف: 86","question":"ما سر عطف الحزن على البثّ في قوله: ﴿إنما أشكو بثّي وحزني إلى الله﴾؟","answer":"جعلها بعضهم من عطف المترادفين، لكن الشيء لا يُعطف على نفسه، وما جاء من ذلك فلزيادة فائدة في الثاني ليست في الأول، فالحزن هنا يزيد معنى على البثّ. وهذه القاعدة منقولة عن «بدائع الفوائد» لابن القيم.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج3، ص230.","url":""}]},{"id":"s12-291","number":291,"surah":12,"verses":[91],"references":[{"surah":12,"verses":[91]}],"verseLabel":"يوسف: 91","question":"ما دلالة القسم بالتاء في قولهم: ﴿تالله لقد آثرك الله علينا﴾ و﴿تالله إنك لفي ضلالك القديم﴾ [95]؟","answer":"في التاء معنى التعجب والتفخيم: فهم متعجبون مما بلغه أخوهم من علوّ المنزلة وما جرّته فعلتهم عليه من الخير على غير ما توقعوا، ومتعجبون من بقاء أبيهم على حاله مع طول العهد. والتاء لم ترد في القرآن إلا مع لفظ الجلالة.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص162.","url":""}]},{"id":"s12-292","number":292,"surah":12,"verses":[91],"references":[{"surah":12,"verses":[91]}],"verseLabel":"يوسف: 91","question":"ما سر التعبير بـ«إن» المخففة في اعتذارهم ليوسف: ﴿وإن كنا لخاطئين﴾، وبالمشددة في اعتذارهم لأبيهم: ﴿إنا كنا خاطئين﴾ [97]؟","answer":"لما رأوا ما حلّ بأبيهم من الوهن واللوعة وذهاب عينيه أكّدوا الاعتذار، بخلاف يوسف الذي أكرمه الله ومكّن له، فكأن فعلتهم عادت عليه بالخير. ويؤيده السياق: فيوسف دعا لهم بالمغفرة من غير سؤال، أما أبوهم فوعدهم بالاستغفار بعد أن طلبوه.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص162–163.","url":""}]},{"id":"s12-293","number":293,"surah":12,"verses":[104],"references":[{"surah":12,"verses":[104]}],"verseLabel":"يوسف: 104","question":"ما سر قوله: ﴿وما تسألهم عليه من أجر إن هو إلا ذكر للعالمين﴾، وفي الأنعام: ﴿لا أسألكم عليه أجرًا إن هو إلا ذكرى للعالمين﴾؟","answer":"«الذكر» أعم من «الذكرى»، فهو التذكير والحفظ والشرف، فناسبه «مِن» الاستغراقية. وناسب الحفظُ والشرفُ قصةَ يوسف الذي حفظه الله من كل كيد وصار له الشرف. والسياق في يوسف أوسع في أمر الرسالة، و﴿من أجر﴾ أطول من ﴿أجرًا﴾، فناسبت السعةُ السعةَ.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص46–47.","url":""}]},{"id":"s12-294","number":294,"surah":12,"verses":[109],"references":[{"surah":12,"verses":[109]}],"verseLabel":"يوسف: 109","question":"ما سر إضافة «قبل» إلى الضمير في قوله: ﴿أفلم يسيروا في الأرض فينظروا كيف كان عاقبة الذين من قبلهم﴾، وقطعها في الروم: ﴿من قبلُ﴾؟","answer":"آية يوسف تقرير لهم بأمر قد فعلوه، فهم قد ساروا ونظروا في أسفارهم المعهودة. أما آية الروم فأمر بالسير والنظر على العموم، لا فيما اعتادوه فحسب، فحُذف المضاف إليه للتعميم: فالسير أعمّ والنظر أعمّ والزمن أعمّ.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص69.","url":""}]},{"id":"s13-1","number":1,"surah":13,"verses":[1],"references":[{"surah":13,"verses":[1]}],"verseLabel":"الرعد: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿تِلْكَ آيَاتُ الْكِتَابِ﴾ باسم الإشارة للبعيد؟","answer":"للتعظيم ورفع المنزلة؛ فالآيات الحاضرة في التلاوة بعيدة الرتبة لا بعيدة المكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص588، تحت «بلاغة الاستعارة في الإشارة بأداة البعيد»","url":""}]},{"id":"s13-2","number":2,"surah":13,"verses":[1],"references":[{"surah":13,"verses":[1]}],"verseLabel":"الرعد: 1","question":"ما دلالة إضافة الآيات إلى الكتاب في ﴿تلك آيات الكتاب﴾؟","answer":"تربط الإضافة الآيات بالكتاب الذي تنتظم فيه، ومن توجيهاتها أن معناها «آيات من كتاب الله». وتذكر الموسوعة أن في كل آية من خصائص البيان والإعجاز ما يدل على كمال الكتاب كله؛ فذكر الآيات يوجه النظر إلى أجزائه، وإضافتها إلى الكتاب تصلها بكله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص589، تحت «معنى الإضافة ونكتتها»","url":""}]},{"id":"s13-3","number":3,"surah":13,"verses":[1],"references":[{"surah":13,"verses":[1]}],"verseLabel":"الرعد: 1","question":"ما النكتة البلاغية في الإخبار بصيغة القصر في قوله تعالى: ﴿وَالَّذِي أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ الْحَقُّ﴾؟","answer":"بعد التنويه بآيات الكتاب، صرحت الجملة بأن المنزل على النبي من ربه هو الحق. وتعريف طرفي الإسناد يقوي اختصاصه بالحق في مقام الرد على المكذبين، وذكر مصدره الإلهي يجمع تعظيم الرسالة وتشريف من أنزلت إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص592، تحت «نكتة الإخبار بصيغة القصر»","url":""}]},{"id":"s13-4","number":4,"surah":13,"verses":[1],"references":[{"surah":13,"verses":[1]}],"verseLabel":"الرعد: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ رَبِّكَ﴾ لا من الله؟","answer":"إضافة الرب إلى النبي تشعر بالرعاية والتثبيت: الذي تولى تربيته هو الذي أنزل إليه الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص594، تحت «نكتة إيثار عنوان الربوبية على لفظ الجلالة»","url":""}]},{"id":"s13-6","number":6,"surah":13,"verses":[1],"references":[{"surah":13,"verses":[1]}],"verseLabel":"الرعد: 1","question":"ما دلالة التعبير بالمضارع في قوله تعالى: ﴿لا يؤمنون﴾؟","answer":"يصور المضارع استمرار عنادهم وتجدد امتناعهم من الإيمان بالحق الذي جاءهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص597، تحت «نكتة التعبير بالمضارع»","url":""}]},{"id":"s13-126","number":126,"surah":13,"verses":[1],"references":[{"surah":13,"verses":[1]}],"verseLabel":"الرعد: 1","question":"ما غرض حذف متعلق ﴿يؤمنون﴾؟","answer":"يجعل الحذف النفي شاملًا لوجوه الإيمان المذكورة في السياق: بالقرآن، وبمن أنزل عليه، وبمصدره الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص597، تحت «غرض حذف متعلق «يؤمنون»»","url":""}]},{"id":"s13-7","number":7,"surah":13,"verses":[2],"references":[{"surah":13,"verses":[2]}],"verseLabel":"الرعد: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿رَفَعَ السَّمَاوَاتِ﴾، دون أن يقال: خلق السماوات؟","answer":"لفظ الرفع يستحضر هيئة السماوات العالية وما فيها من دلالة على القدرة، فلا يقتصر على الإخبار بأصل خلقها. ثم يأتي ﴿بغير عمد ترونها﴾ ليزيد المشهد عجبًا؛ وتعرض الموسوعة توجيه نفي العمد أصلًا، وتوجيه نفي العمد المرئية، والمقصود في الحالين إبراز كمال القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص603–604، تحت «دلالة التعبير بمفردة «رفع» دون خلق؛ دلالة النفي وتوجيهه بين الحقيقة والمجاز»","url":""}]},{"id":"s13-8","number":8,"surah":13,"verses":[2],"references":[{"surah":13,"verses":[2]}],"verseLabel":"الرعد: 2","question":"ما دلالة جمع ﴿السماوات﴾ مع ذكر الأرض مفردة؟","answer":"تربط الموسوعة جمع السماوات بتعددها وتنوع الآيات في جهة العلو. وعند مناقشة جمع السماوات وإفراد الأرض تذكر توجيهات بلاغية متعددة، منها زيادة الاعتناء بالسماوات لشرفها وعظم ما فيها من الآيات. فهذا وجه من وجوه التعبير، ولا ينحصر تعليله في تصور الأرض قرارًا واحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص471، 603–604، تحت «نكتة جمع «السماوات»، وإفراد «الأرض»؛ نكتة جمع السماوات دون إفرادها»","url":""}]},{"id":"s13-9","number":9,"surah":13,"verses":[2],"references":[{"surah":13,"verses":[2]}],"verseLabel":"الرعد: 2","question":"لماذا عُبّر بـ﴿الأجل﴾ دون الوقت في قوله تعالى: ﴿لأجل مسمى﴾؟","answer":"الأجل مدة مقدرة لها نهاية، بخلاف الوقت الذي قد يذكر لمطلق الزمان؛ فدل على أن جريان الشمس والقمر منتهٍ إلى حد.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص609، تحت «نكتة ذكر الأجل دون الوقت»","url":""}]},{"id":"s13-127","number":127,"surah":13,"verses":[2],"references":[{"surah":13,"verses":[2]}],"verseLabel":"الرعد: 2","question":"ما فائدة وصف الأجل بأنه ﴿مسمى﴾؟","answer":"يؤكد أن نهايته معلومة مقدرة عند الله لا تتقدم ولا تتأخر ولا تمضي بلا غاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص609، تحت «فائدة ذكر الصفة»","url":""}]},{"id":"s13-10","number":10,"surah":13,"verses":[2],"references":[{"surah":13,"verses":[2]}],"verseLabel":"الرعد: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿لِقَاءِ رَبِّكُمْ تُوقِنُونَ﴾ لا تؤمنون؟","answer":"لأن المطلوب هنا علم ثابت يطرد الشك في البعث، فالإيقان أخص من مطلق الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص613، تحت «سر التعبير بالإيقان دون الإيمان»","url":""}]},{"id":"s13-11","number":11,"surah":13,"verses":[3],"references":[{"surah":13,"verses":[3]}],"verseLabel":"الرعد: 3","question":"ما دلالة استعمال مفردة «مد»؟","answer":"المد بسط الأرض وتهيئتها للانتفاع؛ فالتعبير يوجه النظر إلى امتدادها الذي يسير عليه الإنسان ويستقر فيه وينتفع به. وهو في السياق مظهر للنعمة والقدرة، بعد ذكر آيات السماوات.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص616، 618–619، تحت «دلالة استعمال مفردة «مد»»","url":""}]},{"id":"s13-12","number":12,"surah":13,"verses":[3],"references":[{"surah":13,"verses":[3]}],"verseLabel":"الرعد: 3","question":"ما دلالة تنكير ﴿رواسي وأنهارًا﴾ في مشهد الأرض؟","answer":"يفيد التنكير هنا التكثير والتعظيم: جبالًا عظيمة وأنهارًا كثيرة تجري بالماء الذي تنتفع به الزروع والأشجار. فالمشهد يعدد مظاهر القدرة والإنعام في الأرض، ويهيئ القارئ للتفكر في آثارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص622، تحت «غرض التنكير»","url":""}]},{"id":"s13-13","number":13,"surah":13,"verses":[3],"references":[{"surah":13,"verses":[3]}],"verseLabel":"الرعد: 3","question":"ما دلالة ختام الآية بـ﴿لقوم يتفكرون﴾؟","answer":"المشاهد المذكورة من مد الأرض والرواسي والثمار وتعاقب الليل تستدعي إعمال النظر في دلالتها على الخالق. وصيغة ﴿يتفكرون﴾ تدعو إلى تفكر متجدد، ينتقل بصاحبه من مشاهدة المصنوعات إلى إدراك حكمة صانعها وقدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص632، تحت «نكتة ذكر التفكر دون التدبر أو التعقل»","url":""}]},{"id":"s13-14","number":14,"surah":13,"verses":[3,4],"references":[{"surah":13,"verses":[3,4]}],"verseLabel":"الرعد: 3-4","question":"ما سرّ التعبير في قوله تعالى في الآية 3: ﴿يتفكرون﴾، وفي الآية 4: ﴿يعقلون﴾؟","answer":"تذكر الموسوعة أن التفكر في المشاهد الكونية يهيئ لإدراك دلالتها، ثم يأتي التعقل ثمرة لذلك النظر. كما أن اختلاف الثمر مع تجاور الأرض واتحاد الماء يجعل الحجة ظاهرة للعقل؛ فناسب تقديم التفكر ثم ختام المشهد التالي بالتعقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص644، تحت «توجيه تشابه فواصل الآيات بذكر التعقل بعد التفكر»","url":""}]},{"id":"s13-15","number":15,"surah":13,"verses":[4],"references":[{"surah":13,"verses":[4]}],"verseLabel":"الرعد: 4","question":"ما دلالة جمع ﴿لآيات﴾ بعد ذكر اختلاف الأرض والثمار مع اتحاد الماء؟","answer":"لأن المشهد يضم دلائل متعددة: تجاور القطع مع اختلاف خصائصها، وتنوع الجنات والنخيل، وتفاوت الثمر مع الماء الواحد. فكل واحد من هذه الوجوه آية، واجتماعها يقوي الدلالة على القدرة والتدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص634، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s13-16","number":16,"surah":13,"verses":[4],"references":[{"surah":13,"verses":[4]}],"verseLabel":"الرعد: 4","question":"ما فائدة ذكر نوعي النخيل في قوله تعالى: ﴿صِنْوَانٌ وَغَيْرُ صِنْوَانٍ﴾؟","answer":"الصنوان نخلات يجمعها أصل واحد، وغير الصنوان ما تفرقت أصوله. وذكر الحالين يزيد تنوع المشهد، ثم يجيء اتحاد الماء مع تفاوت الثمر ليبين أن تشابه بعض أسباب النمو لا يمنع اختلاف الناتج، فيدعو ذلك إلى التفكر في قدرة المدبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص639، تحت «فائدة ذكر نوعي النخيل»","url":""}]},{"id":"s13-17","number":17,"surah":13,"verses":[4],"references":[{"surah":13,"verses":[4]}],"verseLabel":"الرعد: 4","question":"ما دلالة إسناد ﴿ونفضل بعضها على بعض في الأكل﴾ إلى ضمير العظمة؟","answer":"في قراءة النون يلتفت السياق من الغيبة إلى التكلم، وينسب تفاوت الثمار في الطعم والجودة إلى الله صراحة. وقد ذُكر تجاور الأرض واتحاد الماء، فكان التصريح بفاعل التفضيل موضع العبرة؛ ليتوجه العقل من الاختلاف المشاهد إلى تقدير الخالق.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص641–643، تحت «توجيه القراءات القرآنية في «ونفضل»؛ نكتة إسناد التفضيل إلى الله دون سائر المتقدم»","url":""}]},{"id":"s13-18","number":18,"surah":13,"verses":[5],"references":[{"surah":13,"verses":[5]}],"verseLabel":"الرعد: 5","question":"ما وجه قولهم: ﴿أَئِذَا كُنَّا تُرَابًا أَئِنَّا لَفِي خَلْقٍ جَدِيدٍ﴾؟","answer":"في القراءة بالاستفهام في الموضعين يتكرر الإنكار للمبالغة في استبعاد البعث بعد صيرورتهم ترابًا؛ فموضع استبعادهم هو اجتماع هذين الحالين. وتذكر الموسوعة اختلاف القراءات بين الاستفهام والخبر في الموضعين، مع اتفاقها على تصوير إنكارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص650، تحت «غرض الاستفهام ومعناه»","url":""}]},{"id":"s13-19","number":19,"surah":13,"verses":[5],"references":[{"surah":13,"verses":[5]}],"verseLabel":"الرعد: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿خَلْقٍ جَدِيدٍ﴾، دون أن يقال: أنُبعث؟","answer":"يحكي اللفظ استبعادهم أن يعودوا أحياء بعد تحولهم إلى تراب؛ فالمراد بالخلق الجديد إعادة الخلق، لا إيجاد أشخاص آخرين. وقد سبق عرض دلائل الخلق الأول، فصار إنكارهم الإعادة مع إقرارهم بتلك القدرة موضع التعجيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص652، تحت «دلالة التعبير بالخلق الجديد»","url":""}]},{"id":"s13-20","number":20,"surah":13,"verses":[5],"references":[{"surah":13,"verses":[5]}],"verseLabel":"الرعد: 5","question":"ما سرّ التعبير بالكفر في ﴿أولئك الذين كفروا بربهم﴾؟","answer":"السياق في جحود القدرة على البعث بعد ظهور دلائل الخلق الأول؛ فلفظ الكفر يلائم ستر تلك الدلائل وإنكار ما تدل عليه. فهو يصف موقفهم من حجة ظاهرة، لا مجرد ذكر اتخاذ الشريك.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص652–653، تحت «سر التعبير بالكفر دون الشرك»","url":""}]},{"id":"s13-21","number":21,"surah":13,"verses":[6],"references":[{"surah":13,"verses":[6]}],"verseLabel":"الرعد: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيَسْتَعْجِلُونَكَ﴾ بخطاب النبي؟","answer":"يوجه الضمير طلبهم إلى النبي مع أن إنزال العذاب بيد الله؛ فقد كانوا يستعجلونه بما ينذرهم به، استهزاءً بوعيده أو طعنًا في صدق رسالته. فيصور الخطاب تعنتهم في مواجهته، بينما وظيفته تبليغ الإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص662–664، تحت «نكتة ضمير المخاطب في «ويستعجلونك»»","url":""}]},{"id":"s13-22","number":22,"surah":13,"verses":[6],"references":[{"surah":13,"verses":[6]}],"verseLabel":"الرعد: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿ذُو مَغْفِرَةٍ﴾، دون أن يقال: ذو رحمة؟","answer":"المغفرة تلائم ذكر الظلم واستعجال العقوبة؛ ومن توجيهاتها هنا إمهالهم وتأخير العذاب ليرجعوا، كما تحتمل المغفرة لمن تاب. و﴿ذو مغفرة﴾ تفيد رسوخ هذه الصفة وسعتها؛ فالتعبير يفتح باب الرجاء مع التحذير من العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص670–673، تحت «سر إضافة «لذو» إلى «مغفرة»؛ نكتة استعمال صفة المغفرة في الآية»","url":""}]},{"id":"s13-23","number":23,"surah":13,"verses":[6],"references":[{"surah":13,"verses":[6]}],"verseLabel":"الرعد: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿عَلَى ظُلْمِهِمْ﴾ لا مع ظلمهم؟","answer":"تذكر الموسوعة أن ﴿على﴾ تؤدي معنى المصاحبة هنا، مع إبقاء إيحاء الاستعلاء: فرحمة الله ومغفرته فوق ما يستحقه الظلم من العقوبة. وفي تفسير المغفرة بالإمهال، يكون المعنى أنه يؤخر العقوبة مع تلبسهم بالظلم لعلهم يرجعون؛ فلا يعني ذلك إسقاط الوعيد عن المصرين مطلقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص672–673، تحت «معنى حرف الاستعلاء ودلالته في «على ظلمهم»»","url":""}]},{"id":"s13-24","number":24,"surah":13,"verses":[6],"references":[{"surah":13,"verses":[6]}],"verseLabel":"الرعد: 6","question":"ما فائدة الاحتراس بقوله تعالى: ﴿شديد العقاب﴾ بعد ذكر المغفرة؟","answer":"يمنع أن يُفهم الإمهال والمغفرة إهمالًا دائمًا أو عجزًا عن المؤاخذة، فيجمع المقام بين الرجاء والخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص675، تحت «فن الاحتراس في الآية الكريمة»","url":""}]},{"id":"s13-128","number":128,"surah":13,"verses":[6],"references":[{"surah":13,"verses":[6]}],"verseLabel":"الرعد: 6","question":"لماذا استعمل لفظ ﴿العقاب﴾ في قوله تعالى: ﴿شديد العقاب﴾؟","answer":"يلائم العقاب الجزاء الذي يعقب الذنب ويأتي بعده، فينذر المصر على معصيته بعاقبتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص677، تحت «سر استعمال مفردة «العقاب»»","url":""}]},{"id":"s13-25","number":25,"surah":13,"verses":[7],"references":[{"surah":13,"verses":[7]}],"verseLabel":"الرعد: 7","question":"ما سرّ اختيارهم لفظ ﴿أُنْزِلَ﴾ دون «جاءت»؟","answer":"اختيار الإنزال يصور طلبهم آية من عند الله تكون حسية وعلى وفق اقتراحهم. وقد عدلوا عن الاعتداد بما أنزل فعلًا من الآيات، وفي هذا اللفظ تعنت ظاهر؛ إذ لا يطلبون مطلق الدليل بعد قيامه، بل آية مخصوصة يختارونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص683–684، تحت «نكتة استعمال الإنزال دون المجيء»","url":""}]},{"id":"s13-26","number":26,"surah":13,"verses":[7],"references":[{"surah":13,"verses":[7]}],"verseLabel":"الرعد: 7","question":"ما سرّ تقديم ﴿عَلَيْهِ﴾ في قولهم؟","answer":"قدم ﴿عليه﴾ للاهتمام بمن تنزل عليه الآية؛ فاعتراضهم متعلق باختصاص محمد ﷺ بالرسالة. وتربط الموسوعة هذا التقديم بما في نفوسهم من حسد ومكابرة، إذ يريدون آيةً تقنعهم بأن هذا الاختصاص حق.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص684، تحت «سر التقديم في قوله «لولا أنزل عليه آية»»","url":""}]},{"id":"s13-27","number":27,"surah":13,"verses":[7],"references":[{"surah":13,"verses":[7]}],"verseLabel":"الرعد: 7","question":"ما دلالة القصر في ﴿إنما أنت منذر﴾؟","answer":"القصر إضافي يرد اقتراحاتهم: وظيفته إبلاغ الإنذار، أما إنشاء الآيات فإلى الله. فلا يعني أنه لا يبشر ولا يهدي بالدلالة؛ وإنما يحدد ما يلائم مقام الرد، ثم يجيء ﴿ولكل قوم هاد﴾ ليصل الإنذار بالهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص686–688، تحت «بلاغة القصر في «إنما أنت منذر»؛ نكتة قصر الموصوف على صفة الإنذار؛ فن الاحتباك»","url":""}]},{"id":"s13-28","number":28,"surah":13,"verses":[7],"references":[{"surah":13,"verses":[7]}],"verseLabel":"الرعد: 7","question":"لماذا عبّر بقوله: ﴿ولكل قوم﴾ لا «لكل أمة»؟","answer":"يلائم لفظ القوم سياق مخاطبة جماعة النبي ﷺ ومفارقتهم له في الاستجابة إلى دعوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص687، تحت «دلالة إيثار التعبير بلفظ قوم»","url":""}]},{"id":"s13-129","number":129,"surah":13,"verses":[7],"references":[{"surah":13,"verses":[7]}],"verseLabel":"الرعد: 7","question":"لماذا عبّر بـ﴿هاد﴾ بدل منذر؟","answer":"الهداية أوسع من مجرد الإنذار؛ فهي تشمل الدعوة إلى الحق والإنذار والبشارة والإرشاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص688، تحت «سر إيثار لفظ هاد»","url":""}]},{"id":"s13-29","number":29,"surah":13,"verses":[8],"references":[{"surah":13,"verses":[8]}],"verseLabel":"الرعد: 8","question":"ما دلالة الابتداء باسم الجلالة في ﴿الله يعلم﴾؟","answer":"التصريح باسم الله يثبت أن هذا العلم المحيط من شأنه وحده، وتقديم الاسم على الفعل يقوي الحكم؛ إذ يعود عليه ضمير الفعل أيضًا. ثم يأتي تفصيل دقائق الحمل ليجسد سعة هذا العلم فيما يخفى على الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص692–693، تحت «براعة الابتداء والتقديم في «الله يعلم»»","url":""}]},{"id":"s13-30","number":30,"surah":13,"verses":[8],"references":[{"surah":13,"verses":[8]}],"verseLabel":"الرعد: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا تَحْمِلُ كُلُّ أُنْثَى﴾ بالمضارع؟","answer":"المضارع يستحضر الحمل في مراحله المتجددة، ويدل على تعلق علم الله بما تحمل كل أنثى حالًا واستقبالًا. فالعلم محيط بتفاصيل الحمل وأطواره، ولا يختص بحمل مضى أو بجنس دون جنس.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص693–696، تحت «دلالة التعبير بالمضارع في «تحمل»؛ غرض استعمال أداة العموم»","url":""}]},{"id":"s13-31","number":31,"surah":13,"verses":[8],"references":[{"surah":13,"verses":[8]}],"verseLabel":"الرعد: 8","question":"ما دلالة ترتيب ﴿ما تحمل كل أنثى وما تغيض الأرحام وما تزداد﴾؟","answer":"بدأ بذكر الحمل، ثم ذكر النقص والزيادة المتقابلين، ليشمل البيان أحواله المختلفة. وتوضح الموسوعة أن الغيض عدم أو نقص، والزيادة إثبات لما زاد، فناسب تقديم النقص ثم الزيادة في هذا النسق؛ وليس المعنى أن كل حمل لا بد أن يمر بنقص ثم زيادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص697–700، تحت «بلاغة مقابلة «تغيض» بـ«تزداد»؛ بلاغة ترتيب المعطوفات في الآية الكريمة»","url":""}]},{"id":"s13-32","number":32,"surah":13,"verses":[8],"references":[{"surah":13,"verses":[8]}],"verseLabel":"الرعد: 8","question":"ما سرّ تقديم ﴿عِنْدَهُ﴾ في قوله تعالى: ﴿وَكُلُّ شَيْءٍ عِنْدَهُ بِمِقْدَارٍ﴾؟","answer":"يفيد التخصيص والتوكيد: فالله هو العالم بمقادير الأشياء والمدبّر لها بحكمة، فلا يخرج شيء عن علمه وتقديره.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص701–702، تحت «نكتة تقديم «عنده» على المسند «بمقدار»»","url":""}]},{"id":"s13-33","number":33,"surah":13,"verses":[9],"references":[{"surah":13,"verses":[9]}],"verseLabel":"الرعد: 9","question":"ما دلالة حذف الياء من ﴿الْمُتَعَالِ﴾ في توجيه الموسوعة البلاغي؟","answer":"تربط الموسوعة الحذف بالدلالة على كمال العلو، حتى يجتمع اللفظ والمعنى في تنزيه الله عن كل نقص؛ وتذكر معه مراعاة الفواصل الساكنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص705، تحت «توجيه حذف الياء من قوله: «المتعال»»","url":""}]},{"id":"s13-34","number":34,"surah":13,"verses":[10],"references":[{"surah":13,"verses":[10]}],"verseLabel":"الرعد: 10","question":"ما سرّ التعبير بقوله تعالى: ﴿أَسَرَّ الْقَوْلَ﴾ لا أخفاه؟","answer":"لأن الإسرار أدلّ على الكتمان، فهو أنسب للقول؛ أما الخفاء فيناسب أيضًا استتار الأعيان عن البصر. فاختيار الإسرار يبرز إحاطة علم الله بالقول مهما بالغ صاحبه في كتمانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص710–711، تحت «نكتة التعبير بلفظ «أسرّ»»","url":""}]},{"id":"s13-35","number":35,"surah":13,"verses":[10],"references":[{"surah":13,"verses":[10]}],"verseLabel":"الرعد: 10","question":"ما سرّ الاكتفاء بذكر القول في ﴿مَنْ أَسَرَّ الْقَوْلَ وَمَنْ جَهَرَ بِهِ﴾؟","answer":"لأن القول داخل في العمل، وهو عمل اللسان وقد يكون حديثًا في النفس من عمل القلب؛ فذكره يدل على العلم بالفعل أيضًا. ثم ذُكرت أحوال الحركة والاستخفاء في ﴿مُسْتَخْفٍ بِاللَّيْلِ وَسَارِبٌ بِالنَّهَارِ﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص713–714، تحت «بلاغة الاكتفاء بذكر القول دون الفعل»","url":""}]},{"id":"s13-36","number":36,"surah":13,"verses":[10],"references":[{"surah":13,"verses":[10]}],"verseLabel":"الرعد: 10","question":"ما سرّ التعبير بقوله تعالى: ﴿جَهَرَ بِهِ﴾؟","answer":"الجهر إعلان وإظهار يكون إدراكه بالسمع، ولذلك ناسب القول وقابل الإسرار به؛ ولا يلزم أن يسبقه خفاء بالفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص714، تحت «نكتة التعبير بلفظ «جهر»»","url":""}]},{"id":"s13-37","number":37,"surah":13,"verses":[10],"references":[{"surah":13,"verses":[10]}],"verseLabel":"الرعد: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿مُسْتَخْفٍ﴾ و﴿سَارِبٌ﴾؟","answer":"جمع بين طالب الخفاء في الليل والظاهر المنطلق في النهار؛ فالعلم محيط بأقصى حالتي الاستتار والظهور.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص717، تحت «سرّ التعبير بـ«سارب» و«مستخف»»","url":""}]},{"id":"s13-38","number":38,"surah":13,"verses":[10],"references":[{"surah":13,"verses":[10]}],"verseLabel":"الرعد: 10","question":"ما سرّ تكرار ﴿مَنْ﴾ في ﴿مَنْ أَسَرَّ الْقَوْلَ وَمَنْ جَهَرَ بِهِ﴾، وعدم تكرارها قبل ﴿سَارِبٌ بِالنَّهَارِ﴾؟","answer":"عدم تكرارها قبل «سارب» يوجز العبارة ويفسح لاحتمال حالتي شخص واحد، أو شخصين: أحدهما مستخفّ والآخر ظاهر، والجميع سواء في علم الله. أما تكرارها مع الإسرار والجهر فيلائم المقابلة بين مسرّ القول والجاهر به؛ فالقول الواحد لا يكون سرًّا وجهرًا في الوقت نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص718–719، تحت «سرّ الاكتفاء بلا إضافة (من هو)»","url":""}]},{"id":"s13-39","number":39,"surah":13,"verses":[11],"references":[{"surah":13,"verses":[11]}],"verseLabel":"الرعد: 11","question":"ما سرّ إفراد الضمير في ﴿لَهُ مُعَقِّبَاتٌ﴾ مع شمول الكلام للناس؟","answer":"يرجع الضمير إلى كل فرد ممّن تقدّم ذكرهم في ﴿مَنْ أَسَرَّ الْقَوْلَ وَمَنْ جَهَرَ بِهِ﴾ وما بعدها؛ فالإفراد يلحظ الإنسان بعينه، مع دخول الجميع في الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص726–727، تحت «نكتة إفراد الضمائر في الآية الكريمة»","url":""}]},{"id":"s13-40","number":40,"surah":13,"verses":[11],"references":[{"surah":13,"verses":[11]}],"verseLabel":"الرعد: 11","question":"هل في قوله تعالى: ﴿لَهُ مُعَقِّبَاتٌ مِنْ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِ يَحْفَظُونَهُ مِنْ أَمْرِ اللَّهِ﴾ تقديم وتأخير؟","answer":"ذهب بعض المفسرين إلى تقدير تقديم وتأخير، وجعلوا المعنى: له معقبات من أمر الله يحفظونه. لكن المصدر رجّح إبقاء النظم على ترتيبه؛ لأن حمل القرآن على التقديم والتأخير خلاف الأصل مع إمكان فهمه من غير عكس للترتيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص730–731، تحت «بلاغة ترتيب الكلام في الآية الكريمة»","url":""}]},{"id":"s13-41","number":41,"surah":13,"verses":[11],"references":[{"surah":13,"verses":[11]}],"verseLabel":"الرعد: 11","question":"ما معنى «من» في قوله: «من أمر الله»؟","answer":"من توجيهات العبارة أن حفظ الملائكة سببه أمر الله، فهم يحفظون الإنسان بأمره وإذنه، لا استقلالًا عنه. وتعرض الموسوعة توجيهات أخرى لـ«من»؛ لذا لا يُجعل هذا المعنى الوجه الوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص729–731، تحت «معنى «من» في قوله: «من أمر الله»»","url":""}]},{"id":"s13-42","number":42,"surah":13,"verses":[11],"references":[{"surah":13,"verses":[11]}],"verseLabel":"الرعد: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ اللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ﴾ بالمضارع المنفي؟","answer":"يؤكد نفيَ سلب النعمة في الأحوال المتجددة، حتى يغيّر الناس ما بأنفسهم من الخير إلى ضده؛ فليس النفي مقصورًا على حالة واحدة منقضية.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص733، تحت «نكتة المضارع المنفي في «لا يغيّر»»","url":""}]},{"id":"s13-43","number":43,"surah":13,"verses":[11],"references":[{"surah":13,"verses":[11]}],"verseLabel":"الرعد: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا بِقَوْمٍ﴾، دون أن يقال: حال قوم؟","answer":"تُبهم «ما» الأحوال وتعمّمها، ثم يعيّن السياق المراد: ما بالقوم من نعمة وخير. ويستحضر لفظ «قوم» اجتماعهم؛ فالتغيير وما يعقبه قد يعمّ الجماعة بسبب ما يقع منها أو من بعضها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص733–734، تحت «فائدة مجيء الموصول بأداة «ما»»","url":""}]},{"id":"s13-44","number":44,"surah":13,"verses":[11],"references":[{"surah":13,"verses":[11]}],"verseLabel":"الرعد: 11","question":"ما دلالة التعبير بقوله: «من دونه»؟","answer":"«من دونه» تنفي أن يكون لهم وليّ سواه يدفع عنهم ما أراده؛ و«والٍ» من يتولى التدبير والنفع. وجاءت «من» قبل «والٍ» لتؤكد استغراق النفي: فلا ناصر يحميهم من قضائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص739–740، تحت «دلالة التعبير بقوله: «من دونه»»","url":""}]},{"id":"s13-45","number":45,"surah":13,"verses":[12],"references":[{"surah":13,"verses":[12]}],"verseLabel":"الرعد: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿يُرِيكُمُ الْبَرْقَ خَوْفًا وَطَمَعًا﴾ فجمع الضدين؟","answer":"البرق نفسه باعث للخوف من صواعقه وللطمع في الغيث الذي يبشّر به؛ فجمع الوصفين يذكّر بأن من تُخشى عقوبته هو الذي تُرجى رحمته ورزقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص748، تحت «بلاغة الجمع في «خوفًا وطمعًا»»","url":""}]},{"id":"s13-46","number":46,"surah":13,"verses":[12],"references":[{"surah":13,"verses":[12]}],"verseLabel":"الرعد: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿يُنْشِئُ السَّحَابَ﴾ لا يخلق؟","answer":"الإنشاء يصور تكوينه المتجدد شيئًا بعد شيء من بدايات دقيقة حتى يثقل بالماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص749–750، تحت «نكتة التعبير بلفظ «ينشئ»»","url":""}]},{"id":"s13-47","number":47,"surah":13,"verses":[12],"references":[{"surah":13,"verses":[12]}],"verseLabel":"الرعد: 12","question":"ما دلالة وصف السحاب بـ﴿الثِّقَالِ﴾؟","answer":"ليحس القارئ بما حمله من ماء كثير، فتقوى صورة القدرة والبشارة بالمطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص750، تحت «فائدة وصف السحاب بـ«الثقال»»","url":""}]},{"id":"s13-48","number":48,"surah":13,"verses":[13],"references":[{"surah":13,"verses":[13]}],"verseLabel":"الرعد: 13","question":"ما سرّ تعلّق صفة الحمد بتسبيح الرعد في قوله تعالى: ﴿يُسَبِّحُ الرَّعْدُ بِحَمْدِهِ﴾؟","answer":"التسبيح تنزيه لله عن النقص، والحمد ثناء عليه؛ ويقترنان هنا لأن الرعد مع دلالته على القدرة يبشّر بقرب الغيث، وهو نعمة تستوجب الحمد.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص753–754، تحت «سرّ تعلّق صفة الحمد بتسبيح الرعد»","url":""}]},{"id":"s13-49","number":49,"surah":13,"verses":[13],"references":[{"surah":13,"verses":[13]}],"verseLabel":"الرعد: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿مَنْ يَشَاءُ﴾ في إرسال الصواعق؟","answer":"يبين أن الإصابة بالصواعق تابعة لمشيئة الله، فلا يجبره أحد على إنزال العذاب ولا يعجز عن إنزاله؛ وتأخيره عن المكذبين لا يدل على العجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص755–756، تحت «فائدة التعبير بقوله: «من يشاء»»","url":""}]},{"id":"s13-50","number":50,"surah":13,"verses":[13],"references":[{"surah":13,"verses":[13]}],"verseLabel":"الرعد: 13","question":"ما دلالة التعبير بـ﴿يُجَادِلُونَ فِي اللَّهِ﴾ مع أن جدالهم في دلائل توحيده وقدرته؟","answer":"في العبارة حذف يقدَّر بحسب السياق، كجدالهم في توحيد الله أو قدرته على البعث. وإضافة الجدال إلى اسم الله مباشرة تهوّل موقفهم وتبيّن شناعة جدالهم بعد ظهور الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص759–760، تحت «براعة المجاز بالحذف في ذكر لفظ الجلالة»","url":""}]},{"id":"s13-51","number":51,"surah":13,"verses":[13],"references":[{"surah":13,"verses":[13]}],"verseLabel":"الرعد: 13","question":"ما وجه البلاغة في التعبير بقوله: «المحال»؟","answer":"تذكر الموسوعة في «المحال» معنى قوة الأخذ والمماحلة والمكر بالمعاندين من حيث لا يشعرون؛ فوصفه بالشدة يناسب تهديد من يجادل في الله مع ظهور قدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص761–762، تحت «بلاغة التعبير بقوله: «المحال»»","url":""}]},{"id":"s13-52","number":52,"surah":13,"verses":[14],"references":[{"surah":13,"verses":[14]}],"verseLabel":"الرعد: 14","question":"ما سرّ تقديم الجارّ والمجرور في السياق في قوله تعالى: ﴿لَهُ دَعْوَةُ الْحَقِّ﴾؟","answer":"تقديم «له» يفيد اختصاص الله بدعوة الحق في مقابل دعاء الأصنام؛ فهو الذي يسمع ويجيب، أما المعبودات الباطلة فلا تملك لداعيها نفعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص769–770، تحت «سرّ تقديم الجارّ والمجرور في السياق»","url":""}]},{"id":"s13-53","number":53,"surah":13,"verses":[14],"references":[{"surah":13,"verses":[14]}],"verseLabel":"الرعد: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿يَسْتَجِيبُونَ﴾ لا يجيبون؟","answer":"توجّه الموسوعة الاستجابة بأنها إجابة توافق طلب السائل وتحقّق مراده؛ فنفيها يفضح عجز الأصنام عن إسعاف داعيها. وتذكر أيضًا أن السين والتاء قد تفيدان تقوية الفعل، فلا يُحصر معناهما هنا في مجرد طلب الإجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص773–774، تحت «سرّ إيثار الفعل «يستجيبون» دون «يجيبون»»","url":""}]},{"id":"s13-54","number":54,"surah":13,"verses":[14],"references":[{"surah":13,"verses":[14]}],"verseLabel":"الرعد: 14","question":"ما دلالة تشبيه داعي الأصنام بباسط كفّيه إلى الماء ليبلغ فاه؟","answer":"يصوّر تعلّقًا شديدًا بمطلوب لا يُنال بهذه الوسيلة: فالعطشان يدعو الماء أن يأتي فاه، والماء لا يستجيب له. كذلك من يدعو ما لا يسمع ولا ينفع؛ فالصورة تكشف عجز المعبود وخيبة داعيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص776–777، تحت «بلاغة (التشبيه التمثيلي) أو (المركّب العقلي)»","url":""}]},{"id":"s13-55","number":55,"surah":13,"verses":[14],"references":[{"surah":13,"verses":[14]}],"verseLabel":"الرعد: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿كفَّيه﴾ لا يديه؟","answer":"لأن الكفين موضع غرف الماء وتلقيه، فهما أدق في الصورة من عموم اليدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص778، تحت «إيثار الكفّين على اليدين في السياق المبين»","url":""}]},{"id":"s13-56","number":56,"surah":13,"verses":[14],"references":[{"surah":13,"verses":[14]}],"verseLabel":"الرعد: 14","question":"ما معنى الحرف «في» من السياق المحكم؟","answer":"جعل الدعاء نفسه غارقًا في الضلال، مبالغة في تصوير ضياعه وعدم بلوغه غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص782، تحت «معنى الحرف «في» من السياق المحكم»","url":""}]},{"id":"s13-57","number":57,"surah":13,"verses":[15],"references":[{"surah":13,"verses":[15]}],"verseLabel":"الرعد: 15","question":"كيف يسجد لله من في الكون ﴿طَوْعًا وَكَرْهًا﴾؟","answer":"المؤمن يسجد اختيارًا، والجميع خاضعون قهرًا لسننه وقدره؛ فلا يخرج مخلوق عن سلطان ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص788–789، 791، تحت «دلالة الطوع والكره على العموم»","url":""}]},{"id":"s13-58","number":58,"surah":13,"verses":[15],"references":[{"surah":13,"verses":[15]}],"verseLabel":"الرعد: 15","question":"ما دلالة ذكر سجود الظلال بعد سجود أصحابها؟","answer":"الظلال تابعة لأصحابها، ومع ذلك لا يملكون منع امتدادها وانقباضها وفق ما سخّرها الله له؛ فذكرها يجسّد شمول الخضوع، حتى ظلّ المعاند منقاد لربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص792–793، تحت «سرّ التعبير بلفظ (الظلال) في الآية الكريمة»","url":""}]},{"id":"s13-59","number":59,"surah":13,"verses":[16],"references":[{"surah":13,"verses":[16]}],"verseLabel":"الرعد: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿أَوْلِيَاءَ﴾ لا أربابًا؟","answer":"الوليّ والناصر أعمّ من الرب؛ فالتوبيخ على طلب النصرة من غير الله، مع عجز المعبودات المذكورة، يستلزم التوبيخ على اتخاذها أربابًا، وهو الوصف الأخص.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص19، تحت «إيثار التعبير بالأولياء دون الأرباب»","url":""}]},{"id":"s13-60","number":60,"surah":13,"verses":[16],"references":[{"surah":13,"verses":[16]}],"verseLabel":"الرعد: 16","question":"ما دلالة نفي الملكية للنفس في قوله تعالى: ﴿لَا يَمْلِكُونَ لِأَنْفُسِهِمْ نَفْعًا وَلَا ضَرًّا﴾؟","answer":"بدأ بعجزهم عن أنفسهم؛ فمن عجز عن نفع نفسه ودفع ضرها كان أعجز عن غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص20، تحت «دلالة نفي الملكية للنفس»","url":""}]},{"id":"s13-61","number":61,"surah":13,"verses":[16],"references":[{"surah":13,"verses":[16]}],"verseLabel":"الرعد: 16","question":"ما دلالة تكرار ﴿لَا﴾ في ﴿لَا يَمْلِكُونَ لِأَنْفُسِهِمْ نَفْعًا وَلَا ضَرًّا﴾؟","answer":"للنص على استقلال النفي بكل واحد من النفع والضر، فلا يتوهم ثبوت أحدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص21، تحت «نكتة تكرار (لا) النافية»","url":""}]},{"id":"s13-62","number":62,"surah":13,"verses":[16],"references":[{"surah":13,"verses":[16]}],"verseLabel":"الرعد: 16","question":"ما بلاغة تصوير الكفر بالظلمات والإيمان بالنور؟","answer":"يصوّر الكافر كمن يتخبط في الظلام، والمؤمن كمن يبصر طريقه ويهتدي بالنور.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص22، تحت «بلاغة الاستعارتين التصريحيتين في سياق الآية»","url":""}]},{"id":"s13-130","number":130,"surah":13,"verses":[16],"references":[{"surah":13,"verses":[16]}],"verseLabel":"الرعد: 16","question":"لماذا جُمعت ﴿الظلمات﴾ وأُفرد ﴿النور﴾؟","answer":"جُمعت الظلمات لتعدد طرق الشك والباطل، وأُفرد النور لاتحاد طريق الإيمان والحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص24، تحت «سرّ جمع الظلمات وإفراد النور»","url":""}]},{"id":"s13-63","number":63,"surah":13,"verses":[16],"references":[{"surah":13,"verses":[16]}],"verseLabel":"الرعد: 16","question":"ما سرّ ختام الآية بـ﴿الْوَاحِدُ الْقَهَّارُ﴾؟","answer":"«الواحد» يهدم تعدد الشركاء، و«القهار» يهدم توهم استقلالهم بالقوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص30، تحت «إيثار اسمي «الواحد» و«القهّار» دون غيرهما»","url":""}]},{"id":"s13-64","number":64,"surah":13,"verses":[17],"references":[{"surah":13,"verses":[17]}],"verseLabel":"الرعد: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْزَلَ مِنَ السَّمَاءِ مَاءً﴾ لا غيثًا؟","answer":"«الماء» أعمّ، فيشمل ما يكون رحمة وما يكون عذابًا؛ أما «الغيث» فغالب وروده في مقام الإنعام والرحمة. والسياق هنا يضرب مثلًا للحق والباطل، فلا يقتصر على معنى الإغاثة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص38، تحت «إيثار لفظ الماء على الغيث»","url":""}]},{"id":"s13-65","number":65,"surah":13,"verses":[17],"references":[{"surah":13,"verses":[17]}],"verseLabel":"الرعد: 17","question":"ما سرّ إسناد السيلان إلى الأودية في ﴿فَسَالَتْ أَوْدِيَةٌ﴾؟","answer":"يصوّر الماء المتدفق بين جانبي الوادي حتى يخيل للناظر أن الوادي نفسه يسيل معه؛ فإسناد السيلان إلى محله يبرز قوة المشهد وكثرة الماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص41–42، تحت «سرّ إسناد السيلان إلى الوادي دون الماء»","url":""}]},{"id":"s13-66","number":66,"surah":13,"verses":[17],"references":[{"surah":13,"verses":[17]}],"verseLabel":"الرعد: 17","question":"ما فائدة الحال في قوله تعالى «بقدرها»؟","answer":"تحمل الأودية من الماء بحسب سعتها؛ وفي هذا احتراس من توهّم سيل مدمّر يجاوز طاقتها. وعلى تفسير المثل بالقرآن والقلوب، تنتفع القلوب بالوحي بحسب ما تقبله وتعيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص39–40، 44–45، تحت «فائدة الحال في قوله تعالى «بقدرها»»","url":""}]},{"id":"s13-67","number":67,"surah":13,"verses":[17],"references":[{"surah":13,"verses":[17]}],"verseLabel":"الرعد: 17","question":"ما دلالة وصف الزبد بالرابي في الآية الكريمة في قوله تعالى: ﴿فَاحْتَمَلَ السَّيْلُ زَبَدًا رَابِيًا﴾؟","answer":"جعل الزبد محمولًا طافيًا ليجسد ظهور الباطل مؤقتًا مع خفته وانفصاله عن جوهر النافع.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص42–44، تحت «دلالة وصف الزبد بالرابي في الآية الكريمة»","url":""}]},{"id":"s13-68","number":68,"surah":13,"verses":[17],"references":[{"surah":13,"verses":[17]}],"verseLabel":"الرعد: 17","question":"ما سرّ عدم التصريح بإخراج المعادن من الأرض في المثل، مع التصريح بإنزال الماء من السماء؟","answer":"تذكر الموسوعة أن إخراج المعادن داخل ضمن المثل، فلا يحتاج إلى تصريح مستقل. وانتقل البيان إلى إيقاد النار عليها وظهور زبدها؛ وهو مشهد يعرفه أهل الحضر، فيكمل مثل السيل الذي يعرفه أهل البدو.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص47–48، تحت «سرّ العدول عن ذكر إخراج ما يوقدون عليه من الأرض»","url":""}]},{"id":"s13-69","number":69,"surah":13,"verses":[17],"references":[{"surah":13,"verses":[17]}],"verseLabel":"الرعد: 17","question":"ما سرّ إفراد ﴿الزَّبَدُ﴾ مع وروده في مثَلَي الماء والمعدن؟","answer":"لأن زبد الماء وزبد المعدن متحدان في الصفة المقصودة: الطفو والذهاب بلا نفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص53–54، تحت «سرّ إفراد الزبد في قوله «فأمّا الزبد»»","url":""}]},{"id":"s13-70","number":70,"surah":13,"verses":[17],"references":[{"surah":13,"verses":[17]}],"verseLabel":"الرعد: 17","question":"ما سرّ تكرار ﴿كَذَلِكَ يَضْرِبُ اللَّهُ﴾ في آية مثَل الحق والباطل؟","answer":"يؤكد التكرار المثل ويعظّم شأنه بعد تفصيله، وتنتقل الخاتمة من مثل الحق والباطل المذكور إلى تقرير سنة أعمّ في ضرب الأمثال للناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص59، تحت «نكتة تكرار جملة «كذلك يضرب الله»»","url":""}]},{"id":"s13-71","number":71,"surah":13,"verses":[18],"references":[{"surah":13,"verses":[18]}],"verseLabel":"الرعد: 18","question":"ما دلالة إجمال جزاء المستجيبين في كلمة ﴿الْحُسْنَى﴾؟","answer":"توحي بغاية الحسن، وتترك الجزاء مجملًا تعظيمًا له؛ فهو أجلّ من أن يحيط وصف بتفاصيله. وتذكر الموسوعة أن الجنة أبلغ ما يتحقق فيه هذا الوصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص68–69، تحت «إيثار الإجمال في جزاء المستجيبين»","url":""}]},{"id":"s13-72","number":72,"surah":13,"verses":[18],"references":[{"surah":13,"verses":[18]}],"verseLabel":"الرعد: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿سُوءُ الْحِسَابِ﴾ لا سوء العقاب؟","answer":"الحساب يستحضر المناقشة والاستقصاء فيما قُدّم من الأعمال، وقد يسوء الإنسان به ولو لم يعقبه عقاب. فالتعبير أوسع من ذكر العقاب وحده، وفيه تخويف من شدة المحاسبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص74–75، تحت «إيثار لفظ «الحساب» دون (العقاب والعذاب)»","url":""}]},{"id":"s13-73","number":73,"surah":13,"verses":[19],"references":[{"surah":13,"verses":[19]}],"verseLabel":"الرعد: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿أَفَمَنْ يَعْلَمُ﴾ لا أفمن يرى؟","answer":"لأن المراد علم يجمع النظر الصحيح والاعتبار حتى يفضي إلى يقين يستقرّ في القلب ويتحقق به الإيمان؛ فلا يقتصر على مجرد الرؤية أو النظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص85، تحت «سرّ اختيار العلم دون غيره»","url":""}]},{"id":"s13-74","number":74,"surah":13,"verses":[19],"references":[{"surah":13,"verses":[19]}],"verseLabel":"الرعد: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿أَعْمَى﴾ لا «لا يبصر»؟","answer":"العمى وصف متمكن يصور فساد البصيرة، بخلاف عدم الإبصار الذي قد يكون عارضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص89–90، تحت «دلالة التعبير بـ«أعمى» دون (لا يبصر)»","url":""}]},{"id":"s13-75","number":75,"surah":13,"verses":[19],"references":[{"surah":13,"verses":[19]}],"verseLabel":"الرعد: 19","question":"ما دلالة أسلوب القصر في قوله تعالى: ﴿إِنَّمَا يَتَذَكَّرُ أُولُو الْأَلْبَابِ﴾؟","answer":"يقصر التذكّر النافع على أصحاب العقول السليمة التي تنتفع بما تعلم؛ فاللُّبّ هو العقل الصافي الذي يهدي صاحبه، لا مجرد عقل يمتلكه ثم يعطّله عن إدراك الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص91–93، تحت «دلالة أسلوب القصر»","url":""}]},{"id":"s13-76","number":76,"surah":13,"verses":[20],"references":[{"surah":13,"verses":[20]}],"verseLabel":"الرعد: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿يُوفُونَ بِعَهْدِ اللَّهِ﴾ بالمضارع؟","answer":"للدلالة على أن الوفاء خُلُق متجدد ملازم، لا موقفًا عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص99، تحت «دلالة التعبير بالمضارع»","url":""}]},{"id":"s13-77","number":77,"surah":13,"verses":[20],"references":[{"surah":13,"verses":[20]}],"verseLabel":"الرعد: 20","question":"ما سرّ الجمع بين الوفاء بالعهد وعدم نقض الميثاق؟","answer":"الأول إثبات للأداء، والثاني نفي للإفساد بعد التوثيق؛ فاجتمع كمال الفعل والسلامة من ضده.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص102، 105، تحت «سرّ الجمع بين الوفاء بالعهد، وعدم نقض الميثاق»","url":""}]},{"id":"s13-78","number":78,"surah":13,"verses":[20],"references":[{"surah":13,"verses":[20]}],"verseLabel":"الرعد: 20","question":"ما سرّ التعبير بقوله تعالى: ﴿الميثاق﴾ بعد ﴿العهد﴾؟","answer":"من توجيهات الموسوعة أن ذكر الميثاق يوسّع الدلالة إلى ما التزمه الإنسان، فيشمل مواثيق الناس وعهودهم إلى جانب عهد الله؛ وهو تأكيد لإحكام التزامهم، لا تكرار خالٍ من فائدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص105–106، تحت «سرّ اختيار التعبير بالميثاق دون العهد»","url":""}]},{"id":"s13-79","number":79,"surah":13,"verses":[21],"references":[{"surah":13,"verses":[21]}],"verseLabel":"الرعد: 21","question":"ما دلالة تكرار ﴿الَّذِينَ﴾ في صفات أولي الألباب؟","answer":"لتجديد التنبيه إلى استقلال كل طائفة من الصفات بالعناية والمدح.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص111، تحت «سرّ تكرار اسم الموصول «الذين»»","url":""}]},{"id":"s13-80","number":80,"surah":13,"verses":[21],"references":[{"surah":13,"verses":[21]}],"verseLabel":"الرعد: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا أَمَرَ اللَّهُ بِهِ أَنْ يُوصَلَ﴾ ولم يحدد؟","answer":"عمّم ليشمل الأرحام والإيمان والعهود وكل صلة أمر الله بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص111–112، تحت «دلالة التعبير بـ«ما» دون (الذي)»","url":""}]},{"id":"s13-81","number":81,"surah":13,"verses":[21],"references":[{"surah":13,"verses":[21]}],"verseLabel":"الرعد: 21","question":"ما سرّ اختلاف متعلّق الخشية والخوف في قوله تعالى: ﴿يَخْشَوْنَ رَبَّهُمْ وَيَخَافُونَ سُوءَ الْحِسَابِ﴾؟","answer":"الخشية مقرونة بتعظيم المخشيّ والعلم بجلاله، فناسب تعلقها بربهم؛ والخوف من سوء الحساب يبعث على الطاعة واجتناب المخالفة. وقُدّمت الخشية لأنها الأصل الذي ينشأ عنه الخوف من عقابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص114–116، تحت «سرّ اختلاف متعلّق الخشية والخوف»","url":""}]},{"id":"s13-82","number":82,"surah":13,"verses":[22],"references":[{"surah":13,"verses":[22]}],"verseLabel":"الرعد: 22","question":"ما دلالة حذف متعلّق الصبر في ﴿صَبَرُوا﴾؟","answer":"ليعم الصبر على الطاعة وعن المعصية وعلى البلاء، فلا يحصر في لون واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص121، تحت «سرّ التعبير بالصبر وحذف متعلّقه»","url":""}]},{"id":"s13-83","number":83,"surah":13,"verses":[22],"references":[{"surah":13,"verses":[22]}],"verseLabel":"الرعد: 22","question":"ما وجه البلاغة في التعبير بقوله: «وجه ربهم»؟","answer":"«الابتغاء» طلب واجتهاد، ويقيّد التعبير صبرهم بقصد رضا الله وثوابه، لا بطلب السمعة أو مباهاة الناس. فالمقصود إبراز إخلاص الدافع إلى الصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص122–123، تحت «بلاغة التعبير بقوله: «وجه ربهم»»","url":""}]},{"id":"s13-84","number":84,"surah":13,"verses":[22],"references":[{"surah":13,"verses":[22]}],"verseLabel":"الرعد: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿أَقَامُوا الصَّلَاةَ﴾ لا أدّوها؟","answer":"الإقامة تتضمن إتمام أركانها وحدودها والمحافظة عليها، لا مجرد وقوع الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص124–125، تحت «سرّ التعبير بـ(إقامة الصلاة)، دون أدائها»","url":""}]},{"id":"s13-85","number":85,"surah":13,"verses":[22],"references":[{"surah":13,"verses":[22]}],"verseLabel":"الرعد: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْفَقُوا مِمَّا رَزَقْنَاهُمْ﴾ ولم يخص الزكاة؟","answer":"ليشمل الواجب والتطوع، و«مِن» تذكر أن المطلوب بعض الرزق لا كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص125–126، تحت «سرّ التعبير عن الزكاة بالإنفاق»","url":""}]},{"id":"s13-86","number":86,"surah":13,"verses":[22],"references":[{"surah":13,"verses":[22]},{"surah":14,"verses":[31]}],"verseLabel":"الرعد: 22؛ إبراهيم: 31","question":"ما سرّ تقديم ﴿سِرًّا﴾ على ﴿عَلَانِيَةً﴾؟","answer":"في الرعد: 22: تقديم السر يلفت إلى أنه الأصل عند انتفاء سبب يرجّح الإعلان؛ لبعده عن الرياء. وقد تكون العلانية أفضل إذا حققت مقصدًا شريفًا، كالقدوة.\n\nفي إبراهيم: 31: تقديم السر يبرز الإخلاص وصيانة كرامة المتصدَّق عليه، مع بقاء فضل الإعلان إذا دعا الناس إلى الاقتداء والتعاون.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص130، تحت «دلالة البدء بالسرّ»","url":""}]},{"id":"s13-87","number":87,"surah":13,"verses":[22],"references":[{"surah":13,"verses":[22]}],"verseLabel":"الرعد: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿يَدْرَءُونَ بِالْحَسَنَةِ السَّيِّئَةَ﴾ لا يدفعون؟","answer":"«يدرؤون» يجمع وجوه مدافعة السيئة بالحسنة: بالتوبة والعمل الصالح بعد الذنب، وبالعدول عن السيئة، وبمقابلة إساءة الآخرين بالإحسان. فاختير لسعة دلالته في هذا المقام، لا لمجرد دفع الضرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص130–132، تحت «سرّ اصطفاء «يدرؤون» دون (يدفعون)»","url":""}]},{"id":"s13-88","number":88,"surah":13,"verses":[23],"references":[{"surah":13,"verses":[23]}],"verseLabel":"الرعد: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿جَنَّاتُ عَدْنٍ﴾ بالجمع؟","answer":"يدل الجمع على تعدّد الجنات وتنوّع النعيم، وتذكر الموسوعة أنه يلائم كذلك تفاوت درجات أهلها؛ فليس الجميع في درجة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص140–141، تحت «سرّ التعبير بالجمع دون الإفراد»","url":""}]},{"id":"s13-89","number":89,"surah":13,"verses":[23],"references":[{"surah":13,"verses":[23]}],"verseLabel":"الرعد: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿يَدْخُلُونَهَا﴾ لا يسكنونها؟","answer":"الدخول هو أول لحظات الفرح واللقاء بعد الانتظار، فاستحضره لتجديد المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص141، تحت «سرّ التعبير بالفعل «يدخلونها» دون (يسكنونها)»","url":""}]},{"id":"s13-90","number":90,"surah":13,"verses":[23],"references":[{"surah":13,"verses":[23]}],"verseLabel":"الرعد: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَنْ صَلَحَ﴾ لا «والذين صلحوا»؟","answer":"«من» تفيد العموم، فتشمل كل من صلح من آبائهم وأزواجهم وذرياتهم. فيجتمع عموم اللحاق مع شرط الصلاح؛ ولا تكفي القرابة وحدها دون إيمان وعمل صالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص142، تحت «سرّ التعبير بـ«من» دون (الذي)»","url":""}]},{"id":"s13-91","number":91,"surah":13,"verses":[23],"references":[{"surah":13,"verses":[23]}],"verseLabel":"الرعد: 23","question":"ما سرّ تفصيل الآباء والأزواج والذريات بدل الاكتفاء بلفظ «الأهل»؟","answer":"التفصيل يلفت إلى أهمية كل صنف على حدة، وإلى ما يجد أهل الجنة في اجتماعه بهم من تمام الأنس والسرور؛ مع القيد السابق: ﴿وَمَنْ صَلَحَ﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص143–144، تحت «دلالة ذكر هذه الأصناف دون التعبير عنهم بالأهل»","url":""}]},{"id":"s13-92","number":92,"surah":13,"verses":[23],"references":[{"surah":13,"verses":[23]}],"verseLabel":"الرعد: 23","question":"ما دلالة إفراد ﴿بَابٍ﴾ في ﴿مِنْ كُلِّ بَابٍ﴾؟","answer":"يدل على دخول الملائكة من كل باب مختصّ بأهل الجنة المقصودين بالسلام؛ ومع «كل» يشمل الدخول أبوابهم بابًا بابًا، فيظهر كثرة الوفود وتتابع التكريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص146–147، تحت «دلالة التعبير بالإفراد «باب» دون الجمع (أبواب)»","url":""}]},{"id":"s13-93","number":93,"surah":13,"verses":[24],"references":[{"surah":13,"verses":[24]}],"verseLabel":"الرعد: 24","question":"ما سرّ التعبير بقوله تعالى: ﴿سَلَامٌ عَلَيْكُمْ﴾ بالتنكير؟","answer":"يفيد تعظيم هذا السلام وتفخيمه؛ فهو سلام من الله تبشّرهم به ملائكته، ومعه كمال الأمان. أما استمراره فتدل عليه الجملة الاسمية، فلا يُنسب التجدد إلى التنكير وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص151، تحت «دلالة التنكير في «سلام عليكم»»","url":""}]},{"id":"s13-94","number":94,"surah":13,"verses":[24],"references":[{"surah":13,"verses":[24]}],"verseLabel":"الرعد: 24","question":"ما دلالة تعدية السلام بـ﴿عَلَيْكُمْ﴾ بدل «لكم»؟","answer":"تذكر الموسوعة أن «سلام عليكم» تحية وبشارة بالأمان صادرة من الملائكة، أما «سلام لكم» فقد تُحمل على الدعاء وطلب السلامة. فاختير ما يلائم تهنئة أهل الجنة بسلام حاصل لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص151، تحت «دلالة تعدّي السلام بـ(على) دون اللام»","url":""}]},{"id":"s13-95","number":95,"surah":13,"verses":[24],"references":[{"surah":13,"verses":[24]}],"verseLabel":"الرعد: 24","question":"ما سرّ نسبة هذا التكريم إلى الصبر في ﴿بِمَا صَبَرْتُمْ﴾؟","answer":"لأنه الجامع الذي يحفظ جميع خصالهم: لا وفاء ولا صلاة ولا إحسان بلا صبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص151–152، تحت «سرّ اختيار الصبر دون بقية الصفات المذكورة لهم»","url":""}]},{"id":"s13-96","number":96,"surah":13,"verses":[25],"references":[{"surah":13,"verses":[25]}],"verseLabel":"الرعد: 25","question":"ما سرّ بدء وصف الناقضين في الرعد بـ﴿وَالَّذِينَ يَنْقُضُونَ عَهْدَ اللَّهِ﴾، دون الواو في نظيره من البقرة؟","answer":"في الرعد عُطفت صفات الناقضين على صفات الموفين بالعهد لإبراز المقابلة بين الفريقين. أما في البقرة فجاء ﴿الَّذِينَ يَنْقُضُونَ﴾ بيانًا للفاسقين المذكورين قبله، فاتصل الوصف بالموصوف دون حاجة إلى الواو.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص155–156، تحت «سرّ ذكر الواو هنا وحذفها في سورة البقرة»","url":""}]},{"id":"s13-97","number":97,"surah":13,"verses":[25],"references":[{"surah":13,"verses":[25]}],"verseLabel":"الرعد: 25","question":"ما سرّ التعبير بقوله تعالى: ﴿لَهُمُ اللَّعْنَةُ﴾ لا «عليهم اللعنة»؟","answer":"اللام تثبت اختصاصهم واستحقاقهم لها، لا مجرد نزولها عليهم في لحظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص161، تحت «سرّ التعبير بقوله: «لهم اللعنة»، ولم يقل: (عليهم اللعنة)»","url":""}]},{"id":"s13-98","number":98,"surah":13,"verses":[26],"references":[{"surah":13,"verses":[26]}],"verseLabel":"الرعد: 26","question":"ما سرّ التعبير في قوله تعالى: ﴿يَبْسُطُ الرِّزْقَ... وَيَقْدِرُ﴾ لا يوسع ويضيق؟","answer":"«يبسط» يصوّر انتشار الرزق وسعته، وأما «يقدر» فتذكر الموسوعة أنه يدل هنا على تضييق شديد يلائم مقابلة ذلك البسط. فلا يُختزل معنى «يقدر» في مجرد ضبط المقدار دون التضييق.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص167–168، تحت «سرّ اختيار الفعل «يبسط» دون (يوسّع)»","url":""}]},{"id":"s13-99","number":99,"surah":13,"verses":[26],"references":[{"surah":13,"verses":[26]}],"verseLabel":"الرعد: 26","question":"ما دلالة تنكير ﴿مَتَاعٌ﴾ في وصف الحياة الدنيا؟","answer":"للتحقير والتقليل: شيء قليل عابر إذا قيس بالآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص171، تحت «سرّ تنكير «متاع»»","url":""}]},{"id":"s13-100","number":100,"surah":13,"verses":[27],"references":[{"surah":13,"verses":[27]}],"verseLabel":"الرعد: 27","question":"ما دلالة ذكر المشيئة مع الإضلال والإنابة مع الهداية في ﴿إِنَّ اللَّهَ يُضِلُّ مَنْ يَشَاءُ وَيَهْدِي إِلَيْهِ مَنْ أَنَابَ﴾؟","answer":"الهداية والإضلال كلاهما تحت مشيئة الله؛ وذكر الإنابة في جانب الهداية يرغّب في الرجوع إليه والإقبال عليه، ويبيّن قبول المنيب بفضله. فلا يدل اختلاف التعبير على خروج الهداية عن مشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص183–184، تحت «سرّ ذكر المشيئة مع الإضلال، وعدم ذكرها مع الهداية»","url":""}]},{"id":"s13-101","number":101,"surah":13,"verses":[28],"references":[{"surah":13,"verses":[28]}],"verseLabel":"الرعد: 28","question":"ما سرّ التعبير في قوله تعالى: ﴿تَطْمَئِنُّ قُلُوبُهُمْ بِذِكْرِ اللَّهِ﴾ بالمضارع؟","answer":"لتصوير السكينة وهي تتجدد كلما تجدد الذكر، لا أثرًا وقع وانتهى.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص189، تحت «سرّ التعبير بالمضارع «وتطمئنّ»»","url":""}]},{"id":"s13-102","number":102,"surah":13,"verses":[28],"references":[{"surah":13,"verses":[28]}],"verseLabel":"الرعد: 28","question":"ما دلالة التعبير عن القرآن بـ﴿ذِكْرِ اللَّهِ﴾ على هذا الوجه من تفسير الآية؟","answer":"تذكر الموسوعة أنه سُمّي ذكرًا لما فيه من المواعظ وأخبار الأمم، وتلحظ في الذكر معنى الشرف أيضًا؛ فهو شرف لمن ينتفع به. وهذا وجه في تفسير الذكر، ولا يحصر الآية في قراءة القرآن وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص190، تحت «سرّ التعبير عن القرآن بالذكر»","url":""}]},{"id":"s13-103","number":103,"surah":13,"verses":[29],"references":[{"surah":13,"verses":[29]}],"verseLabel":"الرعد: 29","question":"ما سرّ الجمع بين «طوبى» و«حسن مآب»؟","answer":"«طوبى» تجمع الخير والغبطة، ثم «حسن مآب» يثبت جمال النهاية والمرجع.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص203، تحت «سرّ الجمع بين «طوبى» و«حسن مآب»»","url":""}]},{"id":"s13-104","number":104,"surah":13,"verses":[30],"references":[{"surah":13,"verses":[30]}],"verseLabel":"الرعد: 30","question":"ما سرّ اختيار اسم ﴿الرَّحْمَنِ﴾ في ﴿وَهُمْ يَكْفُرُونَ بِالرَّحْمَنِ﴾؟","answer":"لتفظيع كفرهم: يجحدون من عمّت رحمته، فيقابلون الإنعام بالكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص224، تحت «نكتة اختيار اسم (الرحمن)»","url":""}]},{"id":"s13-105","number":105,"surah":13,"verses":[30],"references":[{"surah":13,"verses":[30]}],"verseLabel":"الرعد: 30","question":"ما سرّ التعبير في قول النبي ﷺ: ﴿عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ مَتَابِ﴾؟","answer":"تقديم «عليه» و«إليه» يخصّ الله بالتوكل والرجوع والتوبة، ويناسب المقابلة مع من يستعين بالأصنام. فالمعنى إعلان الاعتماد عليه وحده والإقبال إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص230–232، تحت «سرّ القصر بالتقديم في: «وإليه متاب»»","url":""}]},{"id":"s13-106","number":106,"surah":13,"verses":[31],"references":[{"surah":13,"verses":[31]}],"verseLabel":"الرعد: 31","question":"ما دلالة ترتيب تسيير الجبال ثم تقطيع الأرض ثم تكليم الموتى؟","answer":"تذكر الموسوعة وجوهًا للترتيب؛ منها موافقة ترتيب مطالب المعاندين كما حُكيت، ومنها البدء بالجبال لمناسبتها طبيعة مكة، ثم الأرض وما يتصل بها، ثم الموتى. فلا يُحصر الترتيب في تعليل واحد بالتدرّج من الأسهل إلى الأصعب.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص242، 244–245، تحت «دلالة ترتيب الأمور الثلاثة في الآية»","url":""}]},{"id":"s13-107","number":107,"surah":13,"verses":[31],"references":[{"surah":13,"verses":[31]}],"verseLabel":"الرعد: 31","question":"ما سرّ التعبير بقوله تعالى: ﴿بَلْ لِلَّهِ الْأَمْرُ جَمِيعًا﴾؟","answer":"إضراب عن جدوى اقتراحاتهم إلى الحقيقة الحاكمة: كل أمر الهداية والآيات لله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص250–253، تحت «التعبير بـ«بل» في: «بل لله الأمر جميعًا» دون غيره»","url":""}]},{"id":"s13-108","number":108,"surah":13,"verses":[31],"references":[{"surah":13,"verses":[31]}],"verseLabel":"الرعد: 31","question":"ما وجه البلاغة في المجاز في إطلاق لفظ اليأس في قوله تعالى: ﴿أَفَلَمْ يَيْأَسِ الَّذِينَ آمَنُوا﴾؟","answer":"من وجوه التفسير أن «ييأس» بمعنى يعلم ويتبيّن، وتذكر الموسوعة توجيهه مجازًا من اليأس إلى العلم، وتذكر أيضًا معنى قطع الرجاء في إيمان المعاندين. والمقصود ألا يُعلّق المؤمنون الهداية بتحقق المقترحات؛ فلو شاء الله لهدى الناس جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص254–256، تحت «بلاغة المجاز في إطلاق لفظ اليأس»","url":""}]},{"id":"s13-109","number":109,"surah":13,"verses":[31],"references":[{"surah":13,"verses":[31]}],"verseLabel":"الرعد: 31","question":"ما سرّ التعبير بـ﴿جَمِيعًا﴾ في ﴿لَهَدَى النَّاسَ جَمِيعًا﴾؟","answer":"تبرز «جميعًا» اجتماع الناس على الهداية في حال واحدة، فتظهر شمول القدرة؛ وتناسب لفظها السابق في الآية: ﴿بَلْ لِلَّهِ الْأَمْرُ جَمِيعًا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص259، تحت «نكتة التعبير بـ«جميعًا» دون (كلّهم)»","url":""}]},{"id":"s13-110","number":110,"surah":13,"verses":[31],"references":[{"surah":13,"verses":[31]}],"verseLabel":"الرعد: 31","question":"ما سرّ التعبير بقوله تعالى: ﴿قَارِعَةٌ﴾ بالإفراد؟","answer":"يفيد الإفراد التهويل: فقارعة واحدة تكفي لإفزاعهم، فكيف إذا تكاثرت القوارع؟ وتذكر الموسوعة وجهًا آخر هو وحدة مقصد هذه القوارع في زجر المعاندين.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص267–268، تحت «دلالة الإفراد في: «قارعة»»","url":""}]},{"id":"s13-111","number":111,"surah":13,"verses":[31],"references":[{"surah":13,"verses":[31]}],"verseLabel":"الرعد: 31","question":"ما دلالة التعبير بقوله: «قريبًا»؟","answer":"على عود الضمير إلى القارعة، يوسّع قربها من دارهم التخويف: فقد يفزعهم ما يحيط بهم قبل أن يصيبهم مباشرة. والمضارع يستحضر دوام التهديد وتجدّده. وتذكر الموسوعة وجهًا آخر أن الخطاب للنبي ﷺ بحلوله قريبًا من ديارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص269–271، 274، تحت «دلالة التعبير بقوله: «قريبًا»»","url":""}]},{"id":"s13-112","number":112,"surah":13,"verses":[31],"references":[{"surah":13,"verses":[31]}],"verseLabel":"الرعد: 31","question":"ما دلالة إفراد ﴿الْمِيعَادَ﴾ وتعريفه؟","answer":"تربط الموسوعة الإفراد باستواء المواعيد عند الله في سهولة إنجازها ودقته، مع اختلاف آثارها على العباد. والتعريف يرسّخ الثقة بتحقّق الميعاد والعدل فيه، فلا يدل الإفراد على نفي تعدّد المواعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص280، تحت «سرّ إفراد لفظة «الميعاد» لا جمعها»","url":""}]},{"id":"s13-113","number":113,"surah":13,"verses":[33],"references":[{"surah":13,"verses":[33]}],"verseLabel":"الرعد: 33","question":"ما دلالة حذف خبر «أفمن»؟","answer":"استفهام إنكاري ينفي التسوية بين الله القائم على كل نفس، المحصي لأعمالها، وبين معبودات عاجزة. ومن توجيهات النظم حذف الخبر لدلالة السياق عليه، كالتقدير: أهو كمن ليس كذلك؟ وفي الحذف تحقير للمقابل.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص302–305، تحت «دلالة حذف خبر «أفمن»»","url":""}]},{"id":"s13-114","number":114,"surah":13,"verses":[33],"references":[{"surah":13,"verses":[33]}],"verseLabel":"الرعد: 33","question":"ما سرّ التعبير في قوله تعالى: ﴿بِمَا كَسَبَتْ﴾ لا اكتسبت؟","answer":"«كسبت» أعم في الخير والشر، والمقام في إحاطة العلم بكل ما يصدر عن النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص307–308، تحت «سرّ اختيار «كسبت» دون (اكتسبت)»","url":""}]},{"id":"s13-115","number":115,"surah":13,"verses":[33],"references":[{"surah":13,"verses":[33]}],"verseLabel":"الرعد: 33","question":"ما سرّ التعبير بـ﴿شُرَكَاءَ﴾ دون «أنداد»، وما دلالة جمعها؟","answer":"«شركاء» يوافق اعترافهم بالله مع إشراك آلهة أخرى في عبادته، دون ادعاء مماثلتها له من كل وجه. والجمع يحكي كثرة معبوداتهم وتعدّدها، ثم يأتي ﴿سَمُّوهُمْ﴾ لإظهار عجز ما عظّموه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص310–311، تحت «سرّ التعبير بـ«شركاء» دون أنداد»","url":""}]},{"id":"s13-116","number":116,"surah":13,"verses":[35],"references":[{"surah":13,"verses":[35]}],"verseLabel":"الرعد: 35","question":"ما سرّ التعبير بالمثل دون الوصف في الآية في قوله تعالى: ﴿مَثَلُ الْجَنَّةِ الَّتِي وُعِدَ الْمُتَّقُونَ﴾؟","answer":"«مثل الجنة» يبيّن صفتها وشأنها العجيب، ويقرّب نعيمها الغائب إلى الفهم بما يُعرف من الأنهار والثمر والظل؛ مع أن حقيقة نعيمها أعظم مما يحيط به الوصف المألوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص338–339، تحت «سرّ التعبير بالمثل دون الوصف في الآية»","url":""}]},{"id":"s13-117","number":117,"surah":13,"verses":[35],"references":[{"surah":13,"verses":[35]}],"verseLabel":"الرعد: 35","question":"ما سرّ وصف الأكل بالدوام في الآية في قوله تعالى: ﴿أُكُلُهَا دَائِمٌ وَظِلُّهَا﴾؟","answer":"يبشّر الوصف بنعيم لا يزول ولا ينقطع، بخلاف نعيم الدنيا. ودلّ ﴿دَائِمٌ﴾ المذكور مع الأكل على دوام الظل أيضًا، فاستُغني عن تكراره إيجازًا: أكلها دائم وظلّها دائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص346–348، تحت «سرّ وصف الأكل بالدوام في الآية»","url":""}]},{"id":"s13-118","number":118,"surah":13,"verses":[36],"references":[{"surah":13,"verses":[36]}],"verseLabel":"الرعد: 36","question":"ما دلالة التعبير بالفعل المضارع «يفرحون»؟","answer":"المضارع يصور تجدد فرح أهل الكتاب الصادقين كلما وافق الوحي ما عندهم من الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص359–360، تحت «دلالة التعبير بالفعل المضارع «يفرحون»»","url":""}]},{"id":"s13-119","number":119,"surah":13,"verses":[37],"references":[{"surah":13,"verses":[37]}],"verseLabel":"الرعد: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿حُكْمًا عَرَبِيًّا﴾ لا كتابًا عربيًا؟","answer":"ليبرز وظيفة القرآن في الفصل والهداية والتشريع، لا مجرد لغته أو صورته المكتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص378–380، تحت «سرّ التعبير بقوله تعالى: «حكمًا»»","url":""}]},{"id":"s13-120","number":120,"surah":13,"verses":[38],"references":[{"surah":13,"verses":[38]}],"verseLabel":"الرعد: 38","question":"ما دلالة توكيد ﴿وَلَقَدْ أَرْسَلْنَا رُسُلًا مِنْ قَبْلِكَ﴾ في سياق ذكر الأزواج والذرية؟","answer":"يؤكد أن إرسال الرسل حقيقة ثابتة، وأن كونهم بشرًا لهم أزواج وذرية لا ينافي رسالتهم؛ ففيه ردّ على الاعتراض على النبي ﷺ بذلك، وتسلية له بسنة الرسل قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص390–392، تحت «دلالة دخول (قد) على «أرسلنا»»","url":""}]},{"id":"s13-121","number":121,"surah":13,"verses":[38],"references":[{"surah":13,"verses":[38]}],"verseLabel":"الرعد: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿إِلَّا بِإِذْنِ اللَّهِ﴾ وأظهر الاسم؟","answer":"يبين الاستثناء أن الرسول لا يأتي بالآية من تلقاء نفسه، وإنما بأمر الله ومشيئته. وإظهار اسم الله بعد «أرسلنا» و«جعلنا» يربّي المهابة ويؤكد أن الإذن صادر من صاحب العلم والقدرة المحيطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص399–401، تحت «بلاغة الالتفات في قوله: «إلا بإذن الله»»","url":""}]},{"id":"s13-122","number":122,"surah":13,"verses":[39],"references":[{"surah":13,"verses":[39]}],"verseLabel":"الرعد: 39","question":"كيف نفهم ﴿يَمْحُو اللَّهُ مَا يَشَاءُ وَيُثْبِتُ﴾ مع ﴿وَعِنْدَهُ أُمُّ الْكِتَابِ﴾؟","answer":"تذكر الموسوعة أوجهًا للمحو والإثبات، منها نسخ بعض الأحكام وإبقاء غيرها، وتغيير ما يشاء الله من أحوال الخلق. أما «أمّ الكتاب» فهو الأصل الجامع عنده الذي يرجع إليه ذلك كله؛ فلا تعني الآية تجدّد علم لله بعد جهل، بل تصرّفه بعلمه ومشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص406–408، 411–413، تحت «سرّ التعبير بقوله: «وعنده أمّ الكتاب»»","url":""}]},{"id":"s13-123","number":123,"surah":13,"verses":[41],"references":[{"surah":13,"verses":[41]},{"surah":21,"verses":[44]}],"verseLabel":"الرعد: 41؛ الأنبياء: 44","question":"ما سرّ التعبير في الرعد بقوله تعالى: ﴿ننقصها من أطرافها﴾؟","answer":"من توجيهات التعبير تصوير تقلص سلطان المشركين وامتداد سلطان المسلمين تدريجيًا، وإسناده إلى الله بيان لتدبيره ونصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص431، تحت «سرّ التعبير بقوله: «ننقصها»»","url":""}]},{"id":"s13-131","number":131,"surah":13,"verses":[41],"references":[{"surah":13,"verses":[41]},{"surah":21,"verses":[44]}],"verseLabel":"الرعد: 41؛ الأنبياء: 44","question":"ما بلاغة التمثيل في قوله تعالى في الأنبياء: ﴿نأتي الأرض ننقصها من أطرافها﴾؟","answer":"يمثل التعبير تراجع سلطان المعاندين أمام ظهور الحق، مع اتساع اللفظ لأوجه أخرى من النقص؛ فلا ينحصر في نقصان جغرافي مادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص417، تحت «بلاغة التمثيل في الآية»","url":""}]},{"id":"s13-124","number":124,"surah":13,"verses":[42],"references":[{"surah":13,"verses":[42]}],"verseLabel":"الرعد: 42","question":"ما دلالة وصف تدبيرهم بالمكر ثم قوله: ﴿فَلِلَّهِ الْمَكْرُ جَمِيعًا﴾؟","answer":"يصف المكر تدبيرهم الخفي وحيلهم لصدّ الدعوة؛ ثم يقصر التدبير النافذ على الله: فهو محيط بمكرهم وقادر على إبطاله وأخذهم من حيث لا يشعرون. وتعرض الموسوعة لإسناد المكر إليه توجيه الحقيقة أو المجاز والمشاكلة، فلا يحمل على مكر البشر المذموم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص440–443، تحت «سرّ التعبير بلفظ «المكر»»","url":""}]},{"id":"s13-125","number":125,"surah":13,"verses":[43],"references":[{"surah":13,"verses":[43]}],"verseLabel":"الرعد: 43","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَنْ عِنْدَهُ عِلْمُ الْكِتَابِ﴾ ولم يسمِّهم؟","answer":"يبرز الموصول صفة العلم بالكتاب بوصفها موضع الحجة، ويحتمل العموم دون حصره في شخص مسمّى. وعلى تفسير المراد بعلماء أهل الكتاب يدخل من عرف دلائل صدق الرسول؛ وتذكر الموسوعة أقوالًا أخرى في تعيين المراد فلا يُقطع بقول واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص460–462، تحت «دلالة التعبير بالاسم الموصول»","url":""}]},{"id":"s13-132","number":132,"surah":13,"verses":[11],"references":[{"surah":13,"verses":[11]}],"verseLabel":"الرعد: 11","question":"ما سر إسناد إرادة السوء إلى لفظ الجلالة دون «الرب» في قوله: ﴿وإذا أراد الله بقوم سوءًا فلا مردّ له﴾؟","answer":"لم يرد في القرآن إسناد إرادة السوء أو الضرّ إلى «الرب»، بل يُسند ذلك إلى الله كما يُسند إليه إرادة الخير والرحمة. أما «الرب» فلا يُسند إليه من الإرادة إلا إرادة الخير والرشد، كقوله: ﴿فأراد ربّك أن يبلغا أشدّهما﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص71 وص275.","url":""}]},{"id":"s13-133","number":133,"surah":13,"verses":[20,22],"references":[{"surah":13,"verses":[20,22]}],"verseLabel":"الرعد: 20، 22","question":"ما سر مجيء بعض صفات أولي الألباب بالمضارع ﴿يوفون، يصلون، يخشون، يدرؤون﴾، وبعضها بالماضي ﴿صبروا، أقاموا، أنفقوا﴾؟","answer":"ما كان مستمرًا ليس له وقت محدد جاء بالمضارع، كالوفاء والصلة والخشية ودرء السيئة. وما كان له وقت محدد جاء بالماضي، كإقامة الصلاة والإنفاق. وجاء الصبر بالماضي لأنه أسبق من الجميع والصفات مترتبة عليه، ولذا لم يرد الصبر صلةً في القرآن إلا بالماضي.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص71–74.","url":""}]},{"id":"s13-134","number":134,"surah":13,"verses":[21],"references":[{"surah":13,"verses":[21]}],"verseLabel":"الرعد: 21","question":"ما دلالة إطلاق الخشية في قوله: ﴿ويخشون ربّهم﴾، وتقييدها في مواضع أخرى بـ﴿بالغيب﴾؟","answer":"الخشية بالغيب جزء من الخشية العامة المطلقة، وكلّ موضع ذُكرت فيه الخشية بالغيب اشتمل على جزء مما ذُكر في آيات الرعد. أما الرعد ففصّلت في الصفات وزادت في الجزاء: عقبى الدار وجنات عدن ودخول الملائكة عليهم من كل باب، فناسبها الخشية المطلقة، فناظر بين المواضع في الإطلاق والتقييد.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص37–38.","url":""}]},{"id":"s13-135","number":135,"surah":13,"verses":[24],"references":[{"surah":13,"verses":[24]}],"verseLabel":"الرعد: 24","question":"ما دلالة تنكير السلام في تحية الملائكة: ﴿سلامٌ عليكم بما صبرتم﴾؟","answer":"النكرة أعم وأشمل من المعرفة، ولذلك كانت تحية أهل الجنة «سلام» بالتنكير، يحييهم بها الرحمن والملائكة، ولم ترد تحيتهم بالتعريف. وهو أيضًا ما سلّم به الله على رسله: ﴿سلامٌ على نوح في العالمين﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص151.","url":""}]},{"id":"s13-136","number":136,"surah":13,"verses":[32],"references":[{"surah":13,"verses":[32]}],"verseLabel":"الرعد: 32","question":"ما سر الختم بـ﴿فكيف كان عقاب﴾ هنا، وبـ﴿فكيف كان نكير﴾ في الحج؟","answer":"العقاب أشدّ موقعًا من النكير، لأن الإنكار قد يقع على ما لا عقاب فيه. وقد تقدّم في الرعد ﴿ولقد استُهزئ برسل من قبلك﴾، والاستهزاء زائد على التكذيب، فناسبه العقاب. أما آية الحج فلم يُذكر فيها غير التكذيب. وهذا التوجيه منقول عن «ملاك التأويل».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص232–233.","url":""}]},{"id":"s13-137","number":137,"surah":13,"verses":[40],"references":[{"surah":13,"verses":[40]}],"verseLabel":"الرعد: 40","question":"ما دلالة رسم ﴿وإن ما نرينّك﴾ مفصولة هنا، وموصولة في يونس وغافر ﴿وإمّا نرينّك﴾؟","answer":"هذا من رسم المصحف الذي لا يُقاس عليه، لكن قد يُلتمس له تعليل لا يُقطع بأنه مقصود: الكلام في الرعد على الدنيا والحساب في الآخرة: ﴿فإنما عليك البلاغ وعلينا الحساب﴾، ففُصلت إشارةً إلى الفصل بين الأحداث. أما يونس وغافر ففي سياق الآخرة والرجوع إلى الله، فوُصلت إشارةً إلى اتصال الأحداث.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص83–85.","url":""}]},{"id":"s13-138","number":138,"surah":13,"verses":[2],"references":[{"surah":13,"verses":[2]}],"verseLabel":"الرعد: 2","question":"ما الفرق بين ﴿كلٌّ يجري لأجل مسمّى﴾ باللام هنا، و﴿كلٌّ يجري إلى أجل مسمّى﴾ في لقمان؟","answer":"اللام تفيد التعليل، أي كلّ يجري لبلوغ الأجل ولهذه الغاية، و«إلى» تفيد الانتهاء، أي لا يزال جاريًا حتى ينتهي إلى آخر وقته. واختُصّت لقمان بـ«إلى» لأن ما يكتنفها منبّه على النهاية والحشر والإعادة، وهذا التوجيه منقول عن «درة التنزيل».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص212–213.","url":""}]},{"id":"s13-139","number":139,"surah":13,"verses":[9],"references":[{"surah":13,"verses":[9]}],"verseLabel":"الرعد: 9","question":"ما سر اقتران «الكبير» بـ«المتعال» في قوله: ﴿عالم الغيب والشهادة الكبير المتعال﴾؟","answer":"لا يصف الله نفسه بـ«الكبير» مفردًا ولا مع أي وصف آخر، بل يقرنه بـ«العلي» أو بما هو منه في الاشتقاق، كقوله: ﴿العليّ الكبير﴾. و«المتعال» هنا مشتق من مادة «العلي» نفسها، فجرى على هذا الاقتران.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص25.","url":""}]},{"id":"s13-140","number":140,"surah":13,"verses":[37],"references":[{"surah":13,"verses":[37]}],"verseLabel":"الرعد: 37","question":"ما سر الختم بـ﴿ما لك من الله من وليّ ولا واق﴾ هنا، وبـ﴿ولا نصير﴾ في البقرة؟","answer":"النصرة مختصة بالعقلاء، والوقاية عامة. وفي البقرة الكلام على اتباع ملتهم، وأهل الملة ينصرون أتباعهم فنفى النصير. أما الرعد ففي اتباع أهوائهم في بعض ما أُنزل، وهذا لا يقتضي النصرة بل ربما الحفظ، فنفى الواقي. ولم ترد «واق» إلا في الرعد، وناسبت فاصلتها فواصل السياق: ﴿متاب، الكتاب، الحساب﴾.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص19–21.","url":""}]},{"id":"s14-1","number":1,"surah":14,"verses":[1],"references":[{"surah":14,"verses":[1]}],"verseLabel":"إبراهيم: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿لِتُخْرِجَ النَّاسَ﴾ لا المؤمنين؟","answer":"لأن الرسالة موجهة إلى الناس جميعًا في كل زمان ومكان؛ فالتعبير يدفع توهم اختصاصها بالعرب أو بفئة دون أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص480–481، تحت «بلاغة الاحتراس في لفظ الناس»","url":""}]},{"id":"s14-2","number":2,"surah":14,"verses":[1,23],"references":[{"surah":14,"verses":[1,23]}],"verseLabel":"إبراهيم: 1؛ إبراهيم: 23","question":"ما دلالة ﴿بإذن ربهم﴾ في مطلع سورة إبراهيم؟","answer":"إخراج الناس من الظلمات إلى النور من آثار تربية الله لعباده؛ فذكر الربوبية يلائم الرعاية والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص484، تحت «نكتة ذكر عنوان الربوبية دون الألوهية»","url":""}]},{"id":"s14-163","number":163,"surah":14,"verses":[1,23],"references":[{"surah":14,"verses":[1,23]}],"verseLabel":"إبراهيم: 1؛ إبراهيم: 23","question":"ما دلالة إضافة الرب إلى ضمير المؤمنين في قوله: ﴿خالدين فيها بإذن ربهم﴾؟","answer":"تظهر الإضافة مزيد اللطف بالمؤمنين؛ فدخول الجنة ونعيمها من فضل ربهم ورحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص774، تحت «سر إضافة الضمير، إلى الرب القدير»","url":""}]},{"id":"s14-3","number":3,"surah":14,"verses":[1],"references":[{"surah":14,"verses":[1]}],"verseLabel":"إبراهيم: 1","question":"ما سرّ جمع ﴿الظلمات﴾ وإفراد ﴿النور﴾؟","answer":"لأن مسالك الضلال كثيرة متشعبة، والحق في أصله طريق واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص483، تحت «نكتة جمع الظلمات وإفراد النور»","url":""}]},{"id":"s14-4","number":4,"surah":14,"verses":[1],"references":[{"surah":14,"verses":[1]}],"verseLabel":"إبراهيم: 1","question":"ما دلالة وصف صاحب الصراط بـ﴿الْعَزِيزِ الْحَمِيدِ﴾؟","answer":"العزيز غالب لا تُعجزه معارضة، والحميد مستحق للحمد على نعمة الوحي والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص486–487، تحت «مناسبة تلازم صفتي العزيز الحميد»","url":""}]},{"id":"s14-5","number":5,"surah":14,"verses":[2],"references":[{"surah":14,"verses":[2]}],"verseLabel":"إبراهيم: 2","question":"ما بلاغة وصف الله بالموصول في قوله: ﴿الذي له ما في السماوات وما في الأرض﴾؟","answer":"تكشف الصلة ملك الله الشامل لكل شيء، فتقرر عظمته واستحقاقه وحده للعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص489، تحت «بلاغة التعبير بالموصول»","url":""}]},{"id":"s14-164","number":164,"surah":14,"verses":[2],"references":[{"surah":14,"verses":[2]}],"verseLabel":"إبراهيم: 2","question":"ما التعريض بالمشركين في قوله: ﴿الذي له ما في السماوات وما في الأرض﴾؟","answer":"يعرض بمن عدل عن صراط المالك لكل شيء إلى عبادة من لا يملك شيئا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص489، تحت «بلاغة التعريض بالمشركين»","url":""}]},{"id":"s14-6","number":6,"surah":14,"verses":[2],"references":[{"surah":14,"verses":[2]}],"verseLabel":"إبراهيم: 2","question":"ما دلالة ﴿مِنْ﴾ في قوله تعالى: ﴿وَوَيْلٌ لِلْكَافِرِينَ مِنْ عَذَابٍ شَدِيدٍ﴾؟","answer":"تدل على ابتداء الويل من عذاب شديد؛ وفي ذلك تهويل لما يلقونه، فإذا كان هذا مبدأ ويلهم فكيف بسائر العذاب؟","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص494، تحت «معنى حرف الجر من»","url":""}]},{"id":"s14-7","number":7,"surah":14,"verses":[3],"references":[{"surah":14,"verses":[3]}],"verseLabel":"إبراهيم: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿يَسْتَحِبُّونَ الْحَيَاةَ الدُّنْيَا عَلَى الْآخِرَةِ﴾ لا يحبون؟","answer":"تفيد الصيغة شدة الحب وتكلفه؛ فهم يؤثرون الدنيا ويطلبونها حتى يجعلوها أحب إليهم من الآخرة، لا مجرد ميل عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص502–503، تحت «معنى السين والتاء في قوله يستحبون»","url":""}]},{"id":"s14-8","number":8,"surah":14,"verses":[3],"references":[{"surah":14,"verses":[3]}],"verseLabel":"إبراهيم: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿يَبْغُونَهَا عِوَجًا﴾ لا ميلًا؟","answer":"العوج ميل مضطرب لا استقامة معه؛ فاختياره يصور رغبتهم في صرف سبيل الله عن استقامته، وهو أدل على الفساد من مطلق الميل.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص514، تحت «العوج والميل»","url":""}]},{"id":"s14-9","number":9,"surah":14,"verses":[3],"references":[{"surah":14,"verses":[3]}],"verseLabel":"إبراهيم: 3","question":"ما بلاغة ﴿في﴾ في قوله: ﴿في ضلال﴾؟","answer":"تصور ﴿في﴾ إحاطة الضلال بهم كأنه ظرف لا ينفكون عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص511، تحت «بلاغة استعمال حرف الظرفية في»","url":""}]},{"id":"s14-165","number":165,"surah":14,"verses":[3],"references":[{"surah":14,"verses":[3]}],"verseLabel":"إبراهيم: 3","question":"لماذا وصف الضلال بأنه ﴿بعيد﴾؟","answer":"يصور شدة ابتعادهم عن الحق وصعوبة رجوعهم إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص512، تحت «سر وصف لفظ ضلال بالبعيد»","url":""}]},{"id":"s14-10","number":10,"surah":14,"verses":[4],"references":[{"surah":14,"verses":[4]}],"verseLabel":"إبراهيم: 4","question":"ما سرّ إفراد ﴿لِسَانِ﴾ في قوله تعالى: ﴿بِلِسَانِ قَوْمِهِ﴾؟","answer":"لأن المراد اللغة، و«اللسان» بهذا المعنى اسم جنس يقع على القليل والكثير؛ فصح إفراده مع إضافته إلى القوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص519–520، تحت «وجه إفراد اللسان»","url":""}]},{"id":"s14-11","number":11,"surah":14,"verses":[4],"references":[{"surah":14,"verses":[4]}],"verseLabel":"إبراهيم: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿لِيُبَيِّنَ لَهُمْ﴾ بالمضارع؟","answer":"تدل صيغة المضارع على تجدد البيان واستمراره؛ إذ تتجدد حاجة المدعوين إلى بيان الرسالة وتوضيحها.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص522، تحت «دلالة صيغة المضارعة في ليبين»","url":""}]},{"id":"s14-12","number":12,"surah":14,"verses":[4],"references":[{"surah":14,"verses":[4]}],"verseLabel":"إبراهيم: 4","question":"ما دلالة ختام الآية بـ﴿الْعَزِيزُ الْحَكِيمُ﴾؟","answer":"العزيز لا يغلب في مشيئته ولا يخرج شيء عن قدرته، والحكيم يضع الأشياء مواضعها؛ فالهداية والإضلال جاريان على عزته وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص524–525، تحت «بلاغة التذييل في جملة الفاصلة»","url":""}]},{"id":"s14-13","number":13,"surah":14,"verses":[5],"references":[{"surah":14,"verses":[5]}],"verseLabel":"إبراهيم: 5","question":"ما سرّ التعبير في أمر موسى بـ﴿أَخْرِجْ قَوْمَكَ﴾؟","answer":"لفظ «قومك» يستحضر صلته بمن أرسل إليهم، ويبعث رحمته بهم وإحساسه بمسؤوليته عن هدايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص533، تحت «توجيه إيثار لفظ قوم»","url":""}]},{"id":"s14-14","number":14,"surah":14,"verses":[5],"references":[{"surah":14,"verses":[5]}],"verseLabel":"إبراهيم: 5","question":"ما سرّ جمع ﴿الظلمات﴾ وإفراد ﴿النور﴾ في أمر موسى بإخراج قومه؟","answer":"جُمعت الظلمات لتعدد مصادر الضلال ومظاهر الكفر، وأفرد النور لأن الحق واحد ومصدر الهداية واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص535، تحت «نكتتا جمع الظلمات وإفراد النور»","url":""}]},{"id":"s14-15","number":15,"surah":14,"verses":[5],"references":[{"surah":14,"verses":[5]}],"verseLabel":"إبراهيم: 5","question":"ما المراد بـ﴿أيام الله﴾؟","answer":"هي الأيام ذات الأحداث العظيمة من إنعام الله ونصره وإهلاك المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص538، تحت «بلاغة المجاز في قوله بأيام الله»","url":""}]},{"id":"s14-166","number":166,"surah":14,"verses":[5],"references":[{"surah":14,"verses":[5]}],"verseLabel":"إبراهيم: 5","question":"ما سر إضافة الأيام إلى الله؟","answer":"تعظم الإضافة شأنها وتبرز ما ظهر فيها من تدبير الله ونصره وعقابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص539، تحت «نكتة الإضافة في قوله بأيام الله»","url":""}]},{"id":"s14-16","number":16,"surah":14,"verses":[5],"references":[{"surah":14,"verses":[5]}],"verseLabel":"إبراهيم: 5","question":"ما دلالة ختام الآية بـ﴿لِكُلِّ صَبَّارٍ شَكُورٍ﴾؟","answer":"لأن المنتفع بآيات الله هو من يصبر عند البلاء ويشكر عند النعمة؛ فجمع الوصفين يلائم ما في أيام الله من الشدة والرخاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص543، تحت «سر اقتران وصفي صبار شكور»","url":""}]},{"id":"s14-17","number":17,"surah":14,"verses":[6],"references":[{"surah":14,"verses":[6]}],"verseLabel":"إبراهيم: 6","question":"ما سرّ التعبير في قول موسى: ﴿اذْكُرُوا نِعْمَةَ اللَّهِ﴾ بالإفراد؟","answer":"«نعمة» هنا اسم جنس يشمل نعم الله المتعددة، وفي إفرادها توجيه للنظر إلى جنس النعمة وما يندرج فيه من فضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص552–553، تحت «نكتة إفراد النعمة»","url":""}]},{"id":"s14-18","number":18,"surah":14,"verses":[6],"references":[{"surah":14,"verses":[6]}],"verseLabel":"إبراهيم: 6","question":"ما سرّ أمر بني إسرائيل بذكر نعمة الله في هذا الموضع؟","answer":"لأنهم كانوا متعلقين بالنعم الحسية؛ فجاء تذكيرهم بالنعم طريقًا إلى تذكيرهم بالمنعم وشكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص553، تحت «نكتة الأمر بذكر النعمة لا المنعم»","url":""}]},{"id":"s14-20","number":20,"surah":14,"verses":[6],"references":[{"surah":14,"verses":[6]}],"verseLabel":"إبراهيم: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿يُذَبِّحُونَ أَبْنَاءَكُمْ﴾ لا أولادكم؟","answer":"لأن المقصود قتل الذكور دون الإناث، ولفظ «الأولاد» يشملهما؛ فالتعبير بالأبناء يحدد من وقع عليهم التذبيح.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص560، تحت «فائدة التعبير بالأبناء دون الأولاد»","url":""}]},{"id":"s14-21","number":21,"surah":14,"verses":[6],"references":[{"surah":14,"verses":[6]}],"verseLabel":"إبراهيم: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿يَسْتَحْيُونَ نِسَاءَكُمْ﴾ بالمضارع؟","answer":"ليصور تجدد استحيائهن واستمراره، ويستحضر الإذلال المتكرر الذي كان يصاحب إبقاءهن أحياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص561، تحت «نكتة استعمال لفظ الاستحياء بصيغة المضارع»","url":""}]},{"id":"s14-22","number":22,"surah":14,"verses":[7],"references":[{"surah":14,"verses":[7]}],"verseLabel":"إبراهيم: 7","question":"ما سرّ حذف المفعول الثاني في قوله تعالى: ﴿لَأَزِيدَنَّكُمْ﴾؟","answer":"لإفادة عموم الزيادة دون حصرها في نعمة معينة؛ فقد تكون في الدنيا أو الآخرة أو فيهما، وتشمل ما يخطر للإنسان وما لا يخطر له.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص570–571، تحت «نكتة حذف المفعول»","url":""}]},{"id":"s14-23","number":23,"surah":14,"verses":[7],"references":[{"surah":14,"verses":[7]}],"verseLabel":"إبراهيم: 7","question":"ما سرّ قوله تعالى: ﴿إِنَّ عَذَابِي لَشَدِيدٌ﴾ بدل «لأعذبنكم»؟","answer":"صرح بالوعد بالزيادة، وجاء الوعيد بالعذاب تعريضًا؛ وهذا ألطف بالمخاطبين وأوقع في نفوسهم، والجملة أعم من تخصيصهم وحدهم بالعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص572، تحت «بلاغة اختلاف التعبير في المقابلات القرآنية»","url":""}]},{"id":"s14-24","number":24,"surah":14,"verses":[8],"references":[{"surah":14,"verses":[8]}],"verseLabel":"إبراهيم: 8","question":"ما سرّ التعبير في قول موسى: ﴿إِنْ تَكْفُرُوا أَنْتُمْ﴾ مع ذكر الضمير المنفصل؟","answer":"جاء ﴿أنتم﴾ لتوكيد ضمير الجماعة في ﴿تكفروا﴾، وللتمهيد لعطف ﴿ومن في الأرض﴾ عليه؛ وفي هذا التوكيد مزيد توجيه للزجر إلى المخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص577، تحت «فائدة الضمير المنفصل»","url":""}]},{"id":"s14-25","number":25,"surah":14,"verses":[8],"references":[{"surah":14,"verses":[8]}],"verseLabel":"إبراهيم: 8","question":"ما دلالة ختام الآية بـ﴿لَغَنِيٌّ حَمِيدٌ﴾؟","answer":"غني عن شكر عباده وتعظيمهم، وحميد مستحق للحمد على إنعامه الدائم؛ فلا يضره كفرهم ولا تنقص به صفاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص579، تحت «نكتة الختم بصفتي لغني حميد»","url":""}]},{"id":"s14-26","number":26,"surah":14,"verses":[9],"references":[{"surah":14,"verses":[9]}],"verseLabel":"إبراهيم: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿نَبَأُ الَّذِينَ مِنْ قَبْلِكُمْ﴾ لا خبرهم؟","answer":"لأن النبأ خبر ذو شأن وفائدة مهمة، فيلائم خبر الأمم السابقة الذي يستحق أن يتلقاه الجميع للعبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص583، تحت «سر إيثار لفظ نبأ»","url":""}]},{"id":"s14-27","number":27,"surah":14,"verses":[9],"references":[{"surah":14,"verses":[9]}],"verseLabel":"إبراهيم: 9","question":"ما سرّ ذكر قوم نوح وعاد وثمود ثم قوله: ﴿وَالَّذِينَ مِنْ بَعْدِهِمْ﴾؟","answer":"ذكرت تلك الأمم لقرب أخبار هلاكها من المخاطبين، ثم وسع الكلام إلى أمم أخرى كثيرة لا يحصيها إلا الله؛ فتجتمع العبرة بالمعلوم مع التنبيه إلى ما خفي من أخبار الأمم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص584، تحت «توجيه الخصوص بالذكر»","url":""}]},{"id":"s14-28","number":28,"surah":14,"verses":[9],"references":[{"surah":14,"verses":[9]}],"verseLabel":"إبراهيم: 9","question":"ما أثر الإعراب في بيان المعاني في قوله تعالى: ﴿لَا يَعْلَمُهُمْ إِلَّا اللَّهُ﴾؟","answer":"فيها بيان كثرة الأمم التي لا يحيط البشر بعددها وأحوالها، وأن علمها عند الله وحده؛ فلا يصح ادعاء الإحاطة بأخبار جميع الأمم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص585، تحت «أثر الإعراب في بيان المعاني»","url":""}]},{"id":"s14-29","number":29,"surah":14,"verses":[9],"references":[{"surah":14,"verses":[9]}],"verseLabel":"إبراهيم: 9","question":"ما دلالة صورة ﴿فَرَدُّوا أَيْدِيَهُمْ فِي أَفْوَاهِهِمْ﴾ في التعبير عن رفض الرسل؟","answer":"من أوجه تفسيرها أنهم ردوا أيديهم في أفواه الرسل لإسكاتهم؛ فتجسد الصورة شدة الغيظ والإصرار على إنهاء الحوار ومنع سماع الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص590، تحت «بلاغة استعمال حرف الظرفية»","url":""}]},{"id":"s14-30","number":30,"surah":14,"verses":[9],"references":[{"surah":14,"verses":[9]}],"verseLabel":"إبراهيم: 9","question":"ما دلالة وصف الشك بـ﴿مُرِيبٍ﴾ في قولهم: ﴿وَإِنَّا لَفِي شَكٍّ مِمَّا تَدْعُونَنَا إِلَيْهِ مُرِيبٍ﴾؟","answer":"«مريب» صفة للشك، تزيده توكيدًا وتصف ما يصاحبه من قلق واضطراب؛ فهم يبالغون في إظهار تشككهم في دعوة الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص593، تحت «علة وصف الشك بالمريب»","url":""}]},{"id":"s14-31","number":31,"surah":14,"verses":[10],"references":[{"surah":14,"verses":[10]}],"verseLabel":"إبراهيم: 10","question":"ما سرّ تقديم ﴿فِي اللَّهِ﴾ في قول الرسل: ﴿أَفِي اللَّهِ شَكٌّ﴾؟","answer":"لأن الإنكار منصب على تعلق الشك بالله مع ظهور أدلة وحدانيته؛ فقدم ما هو موضع الإنكار، لا مجرد وجود الشك في أي أمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص600، تحت «نكتة تقديم الجار والمجرور»","url":""}]},{"id":"s14-32","number":32,"surah":14,"verses":[10],"references":[{"surah":14,"verses":[10]}],"verseLabel":"إبراهيم: 10","question":"ما دلالة وصف الله بـ﴿فَاطِرِ السَّمَاوَاتِ وَالْأَرْضِ﴾ في مقام إنكار الشك؟","answer":"السماوات والأرض آيتان عظيمتان على وجود خالقهما ووحدانيته؛ فذكر إبداعهما يقيم الحجة على من يشك في فاطرهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص600، تحت «فائدة إيثار اسم فاطر»","url":""}]},{"id":"s14-33","number":33,"surah":14,"verses":[10],"references":[{"surah":14,"verses":[10]}],"verseLabel":"إبراهيم: 10","question":"ما بلاغة المجاز في قوله: ﴿يدعوكم﴾؟","answer":"ينسب الدعوة إلى الله إظهارا لعنايته ولطفه، إذ يدعوهم إلى الإيمان بواسطة رسله.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص602، تحت «بلاغة المجاز في لفظ الدعاء»","url":""}]},{"id":"s14-167","number":167,"surah":14,"verses":[10],"references":[{"surah":14,"verses":[10]}],"verseLabel":"إبراهيم: 10","question":"ما دلالة اللام في ﴿ليغفر لكم﴾؟","answer":"تبين أن المغفرة غاية الدعوة وثمرتها، وفي ذلك ترغيب في الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص603، تحت «دلالة تعدي الفعل باللام»","url":""}]},{"id":"s14-34","number":34,"surah":14,"verses":[10],"references":[{"surah":14,"verses":[10]}],"verseLabel":"إبراهيم: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيُؤَخِّرَكُمْ﴾ لا يمهلكم؟","answer":"لأن المقام مقام وعد بالمغفرة والسلامة إلى الأجل المقدر؛ فناسبه «التأخير»، بخلاف «الإمهال» الذي يكثر وروده في سياق الوعيد والتهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص604–605، تحت «نكتة إيثار استعمال لفظ التأخير دون الإمهال»","url":""}]},{"id":"s14-35","number":35,"surah":14,"verses":[10],"references":[{"surah":14,"verses":[10]}],"verseLabel":"إبراهيم: 10","question":"ما دلالة ﴿إلى﴾ في ﴿إلى أجل مسمى﴾؟","answer":"تدل على انتهاء مدة التأخير عند غاية محددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص605، تحت «فائدة استعمال حرف انتهاء الغاية»","url":""}]},{"id":"s14-168","number":168,"surah":14,"verses":[10],"references":[{"surah":14,"verses":[10]}],"verseLabel":"إبراهيم: 10","question":"ما دلالة وصف الأجل بأنه ﴿مسمى﴾؟","answer":"يبين أنه محدد معلوم لله وتستوفى مدته من غير تعجيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص605، تحت «فائدة النعت ودلالته»","url":""}]},{"id":"s14-36","number":36,"surah":14,"verses":[10],"references":[{"surah":14,"verses":[10]}],"verseLabel":"إبراهيم: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿تَصُدُّونَا﴾ لا تمنعوننا؟","answer":"الصد يجمع المنع والصرف؛ وفي هذا السياق هو صرفهم عن عبادة الأصنام بالحجة والبرهان، ولذلك كان أدق من مطلق المنع.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص607، تحت «نكتة التعبير بالصد دون المنع»","url":""}]},{"id":"s14-37","number":37,"surah":14,"verses":[11],"references":[{"surah":14,"verses":[11]}],"verseLabel":"إبراهيم: 11","question":"ما سرّ إضافة الرسل إلى أقوامهم في قوله: ﴿قَالَتْ لَهُمْ رُسُلُهُمْ﴾؟","answer":"لتذكيرهم بأن الرسل منهم، يعرفون صدقهم ولسانهم، فتقوم الحجة أقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص616، تحت «سر إضافة الرسل إلى ضمير أقوام»","url":""}]},{"id":"s14-38","number":38,"surah":14,"verses":[11],"references":[{"surah":14,"verses":[11]}],"verseLabel":"إبراهيم: 11","question":"ما سرّ التعبير في قول الرسل: ﴿إِنْ نَحْنُ إِلَّا بَشَرٌ مِثْلُكُمْ﴾؟","answer":"أقروا بالمماثلة البشرية ثم أبطلوا لوازمها الفاسدة؛ فالنبوة فضل من الله لا خروج عن البشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص617، تحت «سر تقييد الخبر بوصف مثلكم»","url":""}]},{"id":"s14-39","number":39,"surah":14,"verses":[11],"references":[{"surah":14,"verses":[11]}],"verseLabel":"إبراهيم: 11","question":"ما دلالة التعبير بالمضارع يشاء في قوله تعالى: ﴿يَمُنُّ عَلَى مَنْ يَشَاءُ مِنْ عِبَادِهِ﴾؟","answer":"يبين التعبير أن النبوة فضل من الله يمن به على من يشاء من عباده؛ فالمماثلة في البشرية لا تمنع اختصاص بعض البشر بالرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص620، تحت «دلالة التعبير بالمضارع يشاء»","url":""}]},{"id":"s14-40","number":40,"surah":14,"verses":[11],"references":[{"surah":14,"verses":[11]}],"verseLabel":"إبراهيم: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿بِسُلْطَانٍ﴾ نكرة؟","answer":"التنكير هنا لتعظيم شأن المعجزة التي طلبوها؛ فهي أمر لا يملكه الرسل من عند أنفسهم، وإنما تكون بإذن الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص622، تحت «غرض تنكير سلطان»","url":""}]},{"id":"s14-41","number":41,"surah":14,"verses":[11],"references":[{"surah":14,"verses":[11]}],"verseLabel":"إبراهيم: 11","question":"ما سرّ إظهار اسم الله في ﴿وَعَلَى اللَّهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ﴾؟","answer":"ليجدد الاهتمام ويعظم شأن التوكل على الله، فيثبت في النفس أن الاعتماد والنصرة منه سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص624، تحت «نكتة إظهار لفظ الجلالة في موضع الإضمار»","url":""}]},{"id":"s14-42","number":42,"surah":14,"verses":[11,12],"references":[{"surah":14,"verses":[11,12]}],"verseLabel":"إبراهيم: 11-12","question":"ما دلالة ﴿وعلى الله فليتوكل المؤمنون﴾؟","answer":"يربط التوكل بالإيمان؛ فالثقة بالله شأن المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص625، تحت «معنى ال في قوله المؤمنون»","url":""}]},{"id":"s14-169","number":169,"surah":14,"verses":[11,12],"references":[{"surah":14,"verses":[11,12]}],"verseLabel":"إبراهيم: 11-12","question":"ما دلالة ﴿وعلى الله فليتوكل المتوكلون﴾؟","answer":"يؤكد التوكل فيمن اتصف به ويحثهم على الثبات عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص638، تحت «جناس الاشتقاق فليتوكل المتوكلون»","url":""}]},{"id":"s14-43","number":43,"surah":14,"verses":[12],"references":[{"surah":14,"verses":[12]}],"verseLabel":"إبراهيم: 12","question":"ما الغرض البلاغي من الاستفهام وما لنا في قوله تعالى: ﴿وَمَا لَنَا أَلَّا نَتَوَكَّلَ عَلَى اللَّهِ﴾؟","answer":"هو استفهام إنكاري عن ترك التوكل: أي عذر لنا فيه وقد أنعم الله علينا بالهداية؟ فيقرر أن التوكل مقتضى الإيمان بنعمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص629، تحت «غرض الاستفهام وما لنا»","url":""}]},{"id":"s14-44","number":44,"surah":14,"verses":[12],"references":[{"surah":14,"verses":[12]}],"verseLabel":"إبراهيم: 12","question":"ما سرّ جمع ﴿سُبُلَنَا﴾ في كلام الرسل؟","answer":"لأن لكل رسول شريعة ومنهاجًا يهدي قومه به؛ فجمعت السبل باعتبار شرائع الرسل، مع وحدة أصل الهداية إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص631–632، تحت «سبب جمع سبيل في وقد هدانا سبلنا»","url":""}]},{"id":"s14-45","number":45,"surah":14,"verses":[12],"references":[{"surah":14,"verses":[12]}],"verseLabel":"إبراهيم: 12","question":"ما دلالة توالي المؤكدات في ﴿وَلَنَصْبِرَنَّ عَلَى مَا آذَيْتُمُونَا﴾؟","answer":"لام القسم ونون التوكيد الثقيلة تظهران رسوخ عزم الرسل على الصبر؛ وصيغة المضارع تصور تجدد ثباتهم كلما تجدد الأذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص632–633، تحت «نكتة توالي المؤكدات في ولنصبرن»","url":""}]},{"id":"s14-46","number":46,"surah":14,"verses":[12],"references":[{"surah":14,"verses":[12]}],"verseLabel":"إبراهيم: 12","question":"ما سرّ عدم تقييد الإيذاء بنوع معين في ﴿عَلَى مَا آذَيْتُمُونَا﴾؟","answer":"ليتسع لما يلقاه الرسل من العناد واقتراح الآيات وسائر الأذى، فيعلنوا الصبر عليه كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص633، تحت «نكتة حذف متعلق الإيذاء آذيتمونا»","url":""}]},{"id":"s14-47","number":47,"surah":14,"verses":[13],"references":[{"surah":14,"verses":[13]}],"verseLabel":"إبراهيم: 13","question":"ما دلالة المؤكدات في تهديد الكفار: ﴿لَنُخْرِجَنَّكُمْ﴾ و﴿لَتَعُودُنَّ﴾؟","answer":"لام القسم ونون التوكيد تكشفان شدة إصرارهم على تنفيذ أحد الأمرين: إخراج الرسل أو حملهم على الدخول في ملتهم؛ فيظهر بلوغ العناد حد الإكراه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص643، تحت «نكتة توالي المؤكدات لنخرجنكم»","url":""}]},{"id":"s14-48","number":48,"surah":14,"verses":[13],"references":[{"surah":14,"verses":[13]}],"verseLabel":"إبراهيم: 13","question":"كيف يُفهم قولهم: ﴿لَتَعُودُنَّ فِي مِلَّتِنَا﴾ مع أن الرسل لم يكونوا عليها؟","answer":"من أوجه تفسيره أن «العود» بمعنى الصيرورة: أي لتصيرن في ملتنا، لا الرجوع إلى كفر سابق. ويذكر المصدر أيضًا حمل الخطاب على الأتباع بطريق التغليب.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص645، تحت «نكتة التعبير بالعود رغم أنهم لم يكونوا على دينهم»","url":""}]},{"id":"s14-49","number":49,"surah":14,"verses":[13],"references":[{"surah":14,"verses":[13]}],"verseLabel":"إبراهيم: 13","question":"ما سرّ تقديم الإخراج على العودة في الملة؟","answer":"لأن المقام مقام تهديد وتخويف، فبدؤوا بالإخراج وهو العقوبة التي يقدرون عليها، وجعلوا الدخول في ملتهم سبيل النجاة منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص645، تحت «نكتة تقديم لنخرجنكم على لتعودن»","url":""}]},{"id":"s14-50","number":50,"surah":14,"verses":[13],"references":[{"surah":14,"verses":[13]}],"verseLabel":"إبراهيم: 13","question":"لماذا قيل: ﴿فأوحى إليهم ربهم﴾ بلفظ الرب؟","answer":"يناسب لفظ الرب تدبير أمر الرسل ونصرتهم وإهلاك الظالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص647، تحت «نكتة الإتيان بلفظ الرب دون لفظ الجلالة»","url":""}]},{"id":"s14-170","number":170,"surah":14,"verses":[13],"references":[{"surah":14,"verses":[13]}],"verseLabel":"إبراهيم: 13","question":"ما دلالة إضافة الرب إلى ضمير الرسل؟","answer":"في الإضافة تشريف وتأنيس وتأكيد أنهم في رعاية ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص648، تحت «نكتة إضافة الرب إلى ضمير الرسل»","url":""}]},{"id":"s14-51","number":51,"surah":14,"verses":[13,14],"references":[{"surah":14,"verses":[13,14]}],"verseLabel":"إبراهيم: 13-14","question":"ما دلالة التوكيد في ﴿لَنُهْلِكَنَّ الظَّالِمِينَ﴾ و﴿لَنُسْكِنَنَّكُمُ الْأَرْضَ﴾؟","answer":"لام القسم ونون التوكيد تثبتان تحقق الوعد بإهلاك الظالمين وإسكان الرسل والمؤمنين الأرض؛ فيطمئنون إلى وعد الله في مواجهة تهديد الكفار.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص648، تحت «نكتة توالي المؤكدات في لنهلكن»","url":""}]},{"id":"s14-52","number":52,"surah":14,"verses":[14],"references":[{"surah":14,"verses":[14]}],"verseLabel":"إبراهيم: 14","question":"ما دلالة ﴿ذلك لمن خاف مقامي﴾؟","answer":"يدل على خوف الوقوف بين يدي الله وهيبة مقامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص655، تحت «دلالة جملة الصلة»","url":""}]},{"id":"s14-171","number":171,"surah":14,"verses":[14],"references":[{"surah":14,"verses":[14]}],"verseLabel":"إبراهيم: 14","question":"لماذا عطف ﴿وخاف وعيد﴾؟","answer":"يجمع إلى تعظيم مقام الله الحذر من عقابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص656، تحت «نكتة عطف وخاف وعيد»","url":""}]},{"id":"s14-53","number":53,"surah":14,"verses":[14],"references":[{"surah":14,"verses":[14]}],"verseLabel":"إبراهيم: 14","question":"ما سرّ تقديم خوف المقام على خوف الوعيد؟","answer":"لأن تعظيم الله أصل، والخوف من العقوبة أثر تابع له.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص657، تحت «نكتة تقديم خوف المقام على الوعيد»","url":""}]},{"id":"s14-54","number":54,"surah":14,"verses":[15],"references":[{"surah":14,"verses":[15]}],"verseLabel":"إبراهيم: 15","question":"ما دلالة صيغة ﴿استفتحوا﴾؟","answer":"تدل زيادة المبنى على طلب الفتح والحكم والنصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص662، تحت «نكتة زيادة المبنى في واستفتحوا»","url":""}]},{"id":"s14-172","number":172,"surah":14,"verses":[15],"references":[{"surah":14,"verses":[15]}],"verseLabel":"إبراهيم: 15","question":"إلى من يعود ضمير ﴿استفتحوا﴾؟","answer":"يحتمل الرسل الذين طلبوا النصر، أو الكفار الذين طلبوا الفصل والعذاب تهكما.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص661، تحت «معنى الواو ودلالتها في واستفتحوا»","url":""}]},{"id":"s14-55","number":55,"surah":14,"verses":[15],"references":[{"surah":14,"verses":[15]}],"verseLabel":"إبراهيم: 15","question":"ما دلالة الجمع بين ﴿جَبَّارٍ عَنِيدٍ﴾؟","answer":"«جبار» يصور تكبره وامتناعه عن قبول الحق، و«عنيد» يصور ميله عن الحق ومعاندته له؛ فاجتمع الاستكبار والإصرار على المخالفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص664، تحت «نكتة الجمع بين جبار وعنيد»","url":""}]},{"id":"s14-56","number":56,"surah":14,"verses":[15],"references":[{"surah":14,"verses":[15]}],"verseLabel":"إبراهيم: 15","question":"ما سرّ تنكير ﴿جَبَّارٍ﴾ و﴿عَنِيدٍ﴾؟","answer":"لتهوين شأنه وتحقيره؛ فمهما اشتد تجبره وعناده في الدنيا فمآله الخيبة والخذلان.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص665، تحت «نكتة تنكير جبار وعنيد»","url":""}]},{"id":"s14-57","number":57,"surah":14,"verses":[16],"references":[{"surah":14,"verses":[16]}],"verseLabel":"إبراهيم: 16","question":"ما وجه البلاغة في الاستعارة في من ورائه جهنم في قوله تعالى: ﴿مِنْ وَرَائِهِ جَهَنَّمُ﴾؟","answer":"تصور العبارة جهنم مترصدة له لا يفلت منها؛ ومن معانيها أن عذابها آتٍ بعد حياته وخيبته في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص668، تحت «بلاغة الاستعارة في من ورائه جهنم»","url":""}]},{"id":"s14-58","number":58,"surah":14,"verses":[16],"references":[{"surah":14,"verses":[16]}],"verseLabel":"إبراهيم: 16","question":"ما سرّ بناء ﴿يُسْقَى﴾ للمفعول؟","answer":"لأن الغرض تصوير ما يلقاه من السقيا والعذاب، فلا يتعلق المقصود بتسمية الساقي؛ فيبقى النظر منصبًا على حال المعذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص669، تحت «نكتة التعبير بالفعل المبني للمفعول ويسقى»","url":""}]},{"id":"s14-59","number":59,"surah":14,"verses":[16],"references":[{"surah":14,"verses":[16]}],"verseLabel":"إبراهيم: 16","question":"ما النكتة البلاغية في الإيضاح بعد الإبهام في قوله تعالى: ﴿مَاءٍ صَدِيدٍ﴾؟","answer":"يذكر الماء أولًا فيثير توقع الارتواء، ثم يبين أنه صديد فينقلب التوقع إلى نفور وعذاب؛ وهذا الإيضاح بعد الإبهام يزيد الصورة تهويلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص671، تحت «نكتة الإيضاح بعد الإبهام»","url":""}]},{"id":"s14-60","number":60,"surah":14,"verses":[17],"references":[{"surah":14,"verses":[17]}],"verseLabel":"إبراهيم: 17","question":"ما دلالة التعبير بيتجرعه في قوله تعالى: ﴿يَتَجَرَّعُهُ﴾؟","answer":"التفعل يصور ابتلاعه جرعة بعد جرعة بمشقة، لا شربًا طبيعيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص675، تحت «دلالة التعبير بيتجرعه»","url":""}]},{"id":"s14-61","number":61,"surah":14,"verses":[17],"references":[{"surah":14,"verses":[17]}],"verseLabel":"إبراهيم: 17","question":"ما النكتة البلاغية في الكناية في ويأتيه الموت من كل مكان في قوله تعالى: ﴿وَيَأْتِيهِ الْمَوْتُ مِنْ كُلِّ مَكَانٍ﴾؟","answer":"تصور العبارة أسباب الموت وآلامه محيطة به من كل جهة، كأنها تهاجمه؛ ومع اجتماعها لا يموت فيستريح، بل يستمر عذابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص677، تحت «نكتة الكناية في ويأتيه الموت من كل مكان»","url":""}]},{"id":"s14-62","number":62,"surah":14,"verses":[17],"references":[{"surah":14,"verses":[17]}],"verseLabel":"إبراهيم: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا هُوَ بِمَيِّتٍ﴾ جملة اسمية مؤكدة بالباء؟","answer":"لترسيخ نفي الموت تمامًا مع تكرر أسبابه، فلا يجد نهاية للألم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص679، تحت «فائدة التعبير بالجملة الاسمية وما هو بميت»","url":""}]},{"id":"s14-63","number":63,"surah":14,"verses":[17],"references":[{"surah":14,"verses":[17]}],"verseLabel":"إبراهيم: 17","question":"ما دلالة تكرار ﴿مِنْ وَرَائِهِ﴾ في وصف العذاب؟","answer":"يجدد التهديد بما ينتظره من العذاب، ويصور مجيئه من جهة خافية يغفل عنها؛ فلا ينتهي هوله بما وصف من الصديد وآلام الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص681، تحت «نكتة تكرار من ورائه»","url":""}]},{"id":"s14-64","number":64,"surah":14,"verses":[17],"references":[{"surah":14,"verses":[17]}],"verseLabel":"إبراهيم: 17","question":"ما دلالة وصف العذاب بـ﴿غَلِيظٌ﴾؟","answer":"استعير الغلظ، وهو ضد الرقة في المحسوسات، لشدة العذاب واستمراره؛ فيوحي بعذاب لا يخف ولا ينقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص681، تحت «نكتة التعبير بالاستعارة عذاب غليظ»","url":""}]},{"id":"s14-65","number":65,"surah":14,"verses":[18],"references":[{"surah":14,"verses":[18]}],"verseLabel":"إبراهيم: 18","question":"ما سرّ تشبيه أعمال الكافرين بالرماد؟","answer":"الرماد يتفرق فلا يبقى منه نفع، وكذلك أعمالهم لا تنفعهم في الآخرة لفقد أصل الإيمان. وهو أثر احتراق، فيناسب تصوير ما أبطله الكفر من ثمرات الأعمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص691، تحت «أوجه الشبه بين أعمال الكفار وبين الرماد»","url":""}]},{"id":"s14-66","number":66,"surah":14,"verses":[18],"references":[{"surah":14,"verses":[18]}],"verseLabel":"إبراهيم: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿اشْتَدَّتْ بِهِ الرِّيحُ﴾ بالإفراد؟","answer":"يلائم الإفراد هنا صورة الريح الشديدة التي تذرو الرماد. ويذكر المصدر أن جمع الرياح يكثر في سياق الرحمة؛ وهذا فرق أغلبِيّ، لا قاعدة تمنع ورود قراءة «الرياح» في الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص696، تحت «الريح والرياح»","url":""}]},{"id":"s14-67","number":67,"surah":14,"verses":[18],"references":[{"surah":14,"verses":[18]}],"verseLabel":"إبراهيم: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا يَقْدِرُونَ مِمَّا كَسَبُوا عَلَى شَيْءٍ﴾، وفي البقرة: ﴿لَا يَقْدِرُونَ عَلَى شَيْءٍ مِمَّا كَسَبُوا﴾؟","answer":"في إبراهيم يدور المثل على أعمال الكافرين وما كسبوه بها، فقدم ﴿مما كسبوا﴾ اهتمامًا بالكسب. أما في البقرة فالسياق في إبطال الصدقة بالمن والأذى، فقدم نفي القدرة على أي شيء من ثمرتها ثم ذكر الكسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص693–694، تحت «المتشابه اللفظي بين آيتي البقرة وإبراهيم»","url":""}]},{"id":"s14-68","number":68,"surah":14,"verses":[18],"references":[{"surah":14,"verses":[18]}],"verseLabel":"إبراهيم: 18","question":"ما دلالة تنكير ﴿شَيْءٍ﴾ في ﴿لَا يَقْدِرُونَ مِمَّا كَسَبُوا عَلَى شَيْءٍ﴾؟","answer":"يشمل النفي أدنى ما ينتفع به من العمل؛ فلا يقدرون على قليل ولا كثير من ثمراته، وفيه بيان ضياع ما كانوا يرجون.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص695، تحت «الغرض من تنكير شيء»","url":""}]},{"id":"s14-69","number":69,"surah":14,"verses":[19],"references":[{"surah":14,"verses":[19]}],"verseLabel":"إبراهيم: 19","question":"ما سرّ تقديم السماوات على الأرض في الاستدلال بالخلق؟","answer":"لأن خلق السماوات وما فيهن أعظم وأعجب، فناسب البدء بها في مقام الاستدلال على قدرة الخالق.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص702، تحت «نكتة تقديم السماوات على الأرض في السياق»","url":""}]},{"id":"s14-71","number":71,"surah":14,"verses":[19,20],"references":[{"surah":14,"verses":[19,20]}],"verseLabel":"إبراهيم: 19-20","question":"ما دلالة الخطاب في ﴿يذهبكم ويأت بخلق جديد﴾؟","answer":"يحول دليل الخلق إلى تهديد مباشر بالاستبدال.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص706، تحت «دلالة التعبير بضمير الخطاب في يذهبكم»","url":""}]},{"id":"s14-173","number":173,"surah":14,"verses":[19,20],"references":[{"surah":14,"verses":[19,20]}],"verseLabel":"إبراهيم: 19-20","question":"ما دلالة ﴿وما ذلك على الله بعزيز﴾؟","answer":"ينفي عن الإذهاب والإبدال كل صعوبة؛ فهو هين على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص709، تحت «دلالة العطف في قوله وما ذلك في السياق»","url":""}]},{"id":"s14-72","number":72,"surah":14,"verses":[20],"references":[{"surah":14,"verses":[20]}],"verseLabel":"إبراهيم: 20","question":"ما سرّ تقديم ﴿عَلَى اللَّهِ﴾ على ﴿بِعَزِيزٍ﴾؟","answer":"لإبراز تعلق نفي العجز بقدرة الله؛ فإذهابهم والإتيان بخلق جديد لا يصعب عليه، وهو تعريض بضعفهم أمام قدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص710، تحت «سر تقديم على الله على بعزيز»","url":""}]},{"id":"s14-73","number":73,"surah":14,"verses":[21],"references":[{"surah":14,"verses":[21]}],"verseLabel":"إبراهيم: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿وَبَرَزُوا لِلَّهِ جَمِيعًا﴾ بالماضي؟","answer":"لتحقيق وقوع القيامة حتى كأنها حدثت وشوهدت.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص716–717، تحت «دلالة العدول إلى التعبير بالماضي في برزوا»","url":""}]},{"id":"s14-74","number":74,"surah":14,"verses":[21],"references":[{"surah":14,"verses":[21]}],"verseLabel":"إبراهيم: 21","question":"ما سرّ التعبير في قول الضعفاء: ﴿إِنَّا كُنَّا لَكُمْ تَبَعًا﴾ بالمصدر؟","answer":"على تفسير «تبعًا» بالمصدر، فيه مبالغة في شدة انقيادهم حتى كأنهم نفس التبعية؛ ويحتمل اللفظ أيضًا أن يكون جمعًا لتابع.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص722–723، تحت «دلالة التعبير بلفظ تبعًا دون تابعين»","url":""}]},{"id":"s14-75","number":75,"surah":14,"verses":[21],"references":[{"surah":14,"verses":[21]}],"verseLabel":"إبراهيم: 21","question":"ما دلالة الفاء في قوله تعالى: ﴿فَقَالَ الضُّعَفَاءُ﴾ بعد ﴿وَبَرَزُوا لِلَّهِ جَمِيعًا﴾؟","answer":"تصل مشهد البروز بمواجهة الأتباع لقادتهم؛ فما إن يظهروا للحساب حتى يحتج الضعفاء بتبعيتهم، فينكشف عجز من اتبعوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص719، تحت «دلالة الفاء في جملة فقال الضعفاء»","url":""}]},{"id":"s14-76","number":76,"surah":14,"verses":[21],"references":[{"surah":14,"verses":[21]}],"verseLabel":"إبراهيم: 21","question":"ما سرّ التعبير في قول المستكبرين: ﴿لَهَدَيْنَاكُمْ﴾ مع نسبة الهداية إلى أنفسهم؟","answer":"من تفسير الكلام: لو أرشدنا الله إلى طريق النجاة من العذاب لأرشدناكم. وإسناد هدايتهم إلى أنفسهم يصور بقاء نزعة التسلط؛ فكأن الأتباع لا يزالون تابعين لهم حتى في طلب الخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص730، تحت «نكتة لهديناكم بدل إسنادها لله تعالى لهداكم»","url":""}]},{"id":"s14-77","number":77,"surah":14,"verses":[21],"references":[{"surah":14,"verses":[21]}],"verseLabel":"إبراهيم: 21","question":"ما دلالة تقديم ﴿سَوَاءٌ﴾ في قولهم: ﴿سَوَاءٌ عَلَيْنَا أَجَزِعْنَا أَمْ صَبَرْنَا﴾؟","answer":"لتأكيد اليأس من النجاة قبل ذكر الجزع والصبر؛ فكلاهما لا يغير مصيرهم، وفيه تيئيس للأتباع الذين رجوا من قادتهم الإغاثة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص731، تحت «الغرض من تقديم الخبر سواء في السياق»","url":""}]},{"id":"s14-78","number":78,"surah":14,"verses":[22],"references":[{"surah":14,"verses":[22]}],"verseLabel":"إبراهيم: 22","question":"ما سرّ التعبير في قول الشيطان: ﴿لَمَّا قُضِيَ الْأَمْرُ﴾ بالبناء للمفعول؟","answer":"لأن القاضي هو الله، وحذف ذكره يصور تفرده بالحكم وعدم وجود شريك له؛ وينصب الاهتمام على نفاذ القضاء وانتهاء الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص743، تحت «دلالة التعبير بالفعل المبني للمفعول قضي»","url":""}]},{"id":"s14-79","number":79,"surah":14,"verses":[22],"references":[{"surah":14,"verses":[22]}],"verseLabel":"إبراهيم: 22","question":"ما دلالة المقابلة بين ﴿وَعَدَكُمْ وَعْدَ الْحَقِّ﴾ و﴿وَوَعَدْتُكُمْ فَأَخْلَفْتُكُمْ﴾؟","answer":"وصف وعد الله بالحق يقرر صدقه وتحققه، والتصريح بإخلاف الشيطان يكشف كذب وعده. ويُفهم من الجملتين وفاء الله بوعده وبطلان ما أغراهم به الشيطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص750، تحت «بلاغة الاحتباك في السياق المحكم»","url":""}]},{"id":"s14-80","number":80,"surah":14,"verses":[22],"references":[{"surah":14,"verses":[22]}],"verseLabel":"إبراهيم: 22","question":"ما الغرض البلاغي من التعبير بفعل الأمر ولوموا في قوله تعالى: ﴿فَلَا تَلُومُونِي وَلُومُوا أَنْفُسَكُمْ﴾؟","answer":"يفرع اللوم على استجابتهم له باختيارهم؛ فقد دعاهم ولم يجبرهم، فاختاروا وسوسته مع قيام الحجج. والكلام لا ينفي استحقاق الشيطان للوم، بل يبين مسؤوليتهم عن اتباعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص756، تحت «الغرض من التعبير بفعل الأمر ولوموا»","url":""}]},{"id":"s14-81","number":81,"surah":14,"verses":[22],"references":[{"surah":14,"verses":[22]}],"verseLabel":"إبراهيم: 22","question":"ما سرّ تقديم ﴿مَا أَنَا بِمُصْرِخِكُمْ﴾ على ﴿وَمَا أَنْتُمْ بِمُصْرِخِيَّ﴾؟","answer":"بدأ بعجزه عن إنقاذهم لأنه ما تعلق به رجاؤهم، ثم نفى قدرتهم على إنقاذه أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص760، تحت «نكتة تقديم نفي إغاثته على نفي إغاثتهم»","url":""}]},{"id":"s14-82","number":82,"surah":14,"verses":[22],"references":[{"surah":14,"verses":[22]}],"verseLabel":"إبراهيم: 22","question":"ما دلالة التوكيد في ﴿إن الظالمين لهم عذاب أليم﴾؟","answer":"يؤكد ثبوت العذاب وانقطاع الطمع في النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص764، تحت «سر التوكيد بإن واسمية الجملة»","url":""}]},{"id":"s14-174","number":174,"surah":14,"verses":[22],"references":[{"surah":14,"verses":[22]}],"verseLabel":"إبراهيم: 22","question":"ما دلالة تقديم ﴿لهم﴾؟","answer":"يبرز اختصاص الظالمين بالعذاب واستحقاقهم له.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص765، تحت «سر تقديم الخبر لهم على المبتدأ عذاب»","url":""}]},{"id":"s14-85","number":85,"surah":14,"verses":[23],"references":[{"surah":14,"verses":[23]}],"verseLabel":"إبراهيم: 23","question":"ما سرّ تقديم ﴿فِيهَا﴾ على ﴿سَلَامٌ﴾ في قوله: ﴿تَحِيَّتُهُمْ فِيهَا سَلَامٌ﴾؟","answer":"للاهتمام بالسلام الذي يلقاه أهل الجنة فيها، وإبراز خصوصية تلك الدار بسلامها الكامل؛ فالاهتمام منصب على ما ينتظرهم من نعيم وأمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص776، تحت «سر تقديم فيها على خبر المبتدأ»","url":""}]},{"id":"s14-86","number":86,"surah":14,"verses":[24],"references":[{"surah":14,"verses":[24]}],"verseLabel":"إبراهيم: 24","question":"إلى من يتوجه الخطاب في ﴿ألم تر﴾؟","answer":"إلى الرسول ﷺ، ويدخل فيه كل من يصلح للتأمل والاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص783، تحت «المقصود بالخطاب في جملة ألم تر»","url":""}]},{"id":"s14-175","number":175,"surah":14,"verses":[24],"references":[{"surah":14,"verses":[24]}],"verseLabel":"إبراهيم: 24","question":"ما دلالة الاستفهام بـ﴿كيف﴾؟","answer":"يوجه النظر إلى هيئة المثل العجيبة وطريقة تصويره.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص783، تحت «سر الاستفهام بالأداة كيف»","url":""}]},{"id":"s14-87","number":87,"surah":14,"verses":[24],"references":[{"surah":14,"verses":[24]}],"verseLabel":"إبراهيم: 24","question":"ما سرّ التعبير في قوله تعالى: ﴿ضَرَبَ اللَّهُ مَثَلًا﴾ وذكر اسم الجلالة؟","answer":"إسناد ضرب المثل إلى اسم الله يعظم شأنه؛ فهو صادر عمن له كمال العلم، فيدعو إلى تلقيه بالتدبر واليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص784، تحت «سر التعبير باسم الجلالة الله مسندًا إليه»","url":""}]},{"id":"s14-88","number":88,"surah":14,"verses":[24],"references":[{"surah":14,"verses":[24]}],"verseLabel":"إبراهيم: 24","question":"ما دلالة وصف ﴿كَلِمَةً﴾ بأنها ﴿طَيِّبَةً﴾؟","answer":"يشير الوصف إلى الكلمة التي تستقيم بها النفس ويظهر خيرها؛ وفي مقدمتها كلمة التوحيد، بما يترتب عليها من إيمان راسخ وعمل صالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص786، تحت «الغرض من وصف الكلمة بوصف طيبة»","url":""}]},{"id":"s14-89","number":89,"surah":14,"verses":[24],"references":[{"surah":14,"verses":[24]}],"verseLabel":"إبراهيم: 24","question":"ما دلالة تشبيه الكلمة الطيبة بشجرة؟","answer":"تجمع الشجرة أصلًا راسخًا وفروعًا عالية وثمرًا نافعًا؛ فيقرب هذا المشهد معنى الإيمان الثابت وما يثمره من قول طيب وعمل صالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص788، تحت «بلاغة التشبيه التمثيلي في السياق»","url":""}]},{"id":"s14-90","number":90,"surah":14,"verses":[24],"references":[{"surah":14,"verses":[24]}],"verseLabel":"إبراهيم: 24","question":"ما سرّ تقديم جملة أصلها ثابت على وفرعها في السماء في قوله تعالى: ﴿أَصْلُهَا ثَابِتٌ وَفَرْعُهَا فِي السَّمَاءِ﴾؟","answer":"ثبات الأصل يصور رسوخ الإيمان في القلب، وارتفاع الفرع يصور سمو الكلمة الطيبة وخيراتها؛ فجمع المثل بين الثبات والعلو.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص790، تحت «سر تقديم جملة أصلها ثابت على وفرعها في السماء»","url":""}]},{"id":"s14-91","number":91,"surah":14,"verses":[25],"references":[{"surah":14,"verses":[25]}],"verseLabel":"إبراهيم: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿تُؤْتِي أُكُلَهَا كُلَّ حِينٍ﴾ لا ثمرها؟","answer":"الأُكُل هو ما يؤكل من الثمر، فهو أخص منه ويصرح بصلاحه للانتفاع؛ وهذا أنسب بصورة الشجرة الطيبة كاملة النفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص802–803، تحت «أكلها وثمرها»","url":""}]},{"id":"s14-92","number":92,"surah":14,"verses":[25],"references":[{"surah":14,"verses":[25]}],"verseLabel":"إبراهيم: 25","question":"ما دلالة القيد ﴿بإذن﴾ في إثمار الشجرة؟","answer":"يبين أن استمرار إثمارها لا يكون إلا بتقدير خالقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص798، تحت «دلالة القيد بشبه الجملة بإذن»","url":""}]},{"id":"s14-176","number":176,"surah":14,"verses":[25],"references":[{"surah":14,"verses":[25]}],"verseLabel":"إبراهيم: 25","question":"ما سر الإضافة في ﴿بإذن ربها﴾؟","answer":"تذكر برعاية الله للشجرة وتدبيره لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص798، تحت «سر الإضافة إلى الربوبية»","url":""}]},{"id":"s14-93","number":93,"surah":14,"verses":[26],"references":[{"surah":14,"verses":[26]}],"verseLabel":"إبراهيم: 26","question":"ما دلالة وصف الشجرة الخبيثة بـ﴿اجْتُثَّتْ مِنْ فَوْقِ الْأَرْضِ﴾؟","answer":"تصورها مقتَلعة لا جذور راسخة لها؛ فيقابل ذلك ثبات الشجرة الطيبة، ويمثل افتقار الكلمة الخبيثة إلى الحجة والثبات والنفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص16، تحت «سر تقييد الاجتثاث من فوق الأرض»","url":""}]},{"id":"s14-94","number":94,"surah":14,"verses":[26],"references":[{"surah":14,"verses":[26]}],"verseLabel":"إبراهيم: 26","question":"ما دلالة حرف الجر في من قرار في قوله تعالى: ﴿مَا لَهَا مِنْ قَرَارٍ﴾؟","answer":"الجملة الاسمية والنكرة في سياق النفي، مع «من» المؤكدة للاستغراق، تنفي عنها كل ثبات؛ فتلائم صورة الكلمة الخبيثة التي لا حجة لها ولا رسوخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص17، تحت «دلالة حرف الجر في من قرار»","url":""}]},{"id":"s14-95","number":95,"surah":14,"verses":[27],"references":[{"surah":14,"verses":[27]}],"verseLabel":"إبراهيم: 27","question":"ما دلالة الاستئناف في الآية في قوله تعالى: ﴿يُثَبِّتُ اللَّهُ الَّذِينَ آمَنُوا بِالْقَوْلِ الثَّابِتِ﴾؟","answer":"بعد تمثيل الكلمة الطيبة بالشجرة الراسخة، يبين أن الله يثبت أهل الإيمان بالقول الحق في الدنيا والآخرة؛ فيتصل ثبات الكلمة بثبات أصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص21، تحت «دلالة الاستئناف في الآية»","url":""}]},{"id":"s14-96","number":96,"surah":14,"verses":[27],"references":[{"surah":14,"verses":[27]}],"verseLabel":"إبراهيم: 27","question":"ما سر الجناس بين ﴿يُثَبِّتُ﴾ و﴿الثَّابِتِ﴾؟","answer":"اشتُق وصف ﴿الثابت﴾ من مادة الفعل ﴿يثبت﴾؛ للإشارة إلى توفيق الله للمؤمنين وتثبيته إياهم بالقول الثابت.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص23، تحت «نكتة الجناس في يثبت والثابت»","url":""}]},{"id":"s14-97","number":97,"surah":14,"verses":[28],"references":[{"surah":14,"verses":[28]}],"verseLabel":"إبراهيم: 28","question":"ما الغرض البلاغي من الاستعارة في الفعل بدلوا في قوله تعالى: ﴿بَدَّلُوا نِعْمَتَ اللَّهِ كُفْرًا﴾؟","answer":"صور مقابلة النعمة بالكفر بالتبديل: جعلوا الكفر موضع الشكر الذي تقتضيه نعمة الله، وفي ذلك تقبيح لجحودهم وسوء اختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص32–33، تحت «غرض الاستعارة في الفعل بدلوا»","url":""}]},{"id":"s14-98","number":98,"surah":14,"verses":[29],"references":[{"surah":14,"verses":[29]}],"verseLabel":"إبراهيم: 29","question":"ما سرّ تقديم ﴿جَهَنَّمَ﴾ في ﴿جَهَنَّمَ يَصْلَوْنَهَا﴾؟","answer":"لتعجيل بيان المصير وتهويله؛ فبعد ذكر ﴿دار البوار﴾ يأتي اسم جهنم كاشفًا عن ذلك الهلاك ومفزعًا للسامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص40، تحت «غرض تقديم المفعول به جهنم»","url":""}]},{"id":"s14-99","number":99,"surah":14,"verses":[30],"references":[{"surah":14,"verses":[30]}],"verseLabel":"إبراهيم: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿جَعَلُوا لِلَّهِ أَنْدَادًا﴾ وقدّم ﴿لله﴾؟","answer":"لتعجيل الإنكار وتفظيع الشرك؛ فقد جعلوا الأنداد لله الذي يعلمون أنه خالقهم ورازقهم، فاشتد تقبيح صنيعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص45، تحت «غرض تقديم لله على أندادًا»","url":""}]},{"id":"s14-100","number":100,"surah":14,"verses":[31],"references":[{"surah":14,"verses":[31]}],"verseLabel":"إبراهيم: 31","question":"ما دلالة التعبير عن الأمر بـ﴿يُقِيمُوا الصَّلَاةَ وَيُنْفِقُوا﴾ بصيغة المضارع؟","answer":"للدلالة على تجدد الإقامة والإنفاق واستمرارهما، لا أداء مرة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص54–55، تحت «نكتة الأمر بالمضارع يقيموا وينفقوا»","url":""}]},{"id":"s14-101","number":101,"surah":14,"verses":[31],"references":[{"surah":14,"verses":[31]}],"verseLabel":"إبراهيم: 31","question":"لماذا حُذفت لام الأمر قبل ﴿يُقِيمُوا﴾؟","answer":"على توجيه المضارع بالأمر المقدر، الأصل «ليقيموا»، فحذفت لام الأمر تخفيفًا لدلالة السياق عليها؛ واستعمال المضارع يفيد طلب دوام الفعل وتجديده.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص54–55، تحت «نكتة الأمر بالمضارع يقيموا وينفقوا»","url":""}]},{"id":"s14-103","number":103,"surah":14,"verses":[31],"references":[{"surah":14,"verses":[31]}],"verseLabel":"إبراهيم: 31","question":"ما الغرض البلاغي من التعبير بالكناية في نفي البيع والخلال في قوله تعالى: ﴿مِنْ قَبْلِ أَنْ يَأْتِيَ يَوْمٌ لَا بَيْعٌ فِيهِ وَلَا خِلَالٌ﴾؟","answer":"ينبه نفي البيع والخلال إلى انقطاع وسائل التدارك الدنيوية؛ فلا بيع ولا صداقة تتيح تعويض العمل الفائت. وفي ذلك حث على المبادرة بالصلاة والإنفاق قبل مجيء ذلك اليوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص58، تحت «غرض التعبير بالكناية في نفي البيع والخلال»","url":""}]},{"id":"s14-104","number":104,"surah":14,"verses":[32],"references":[{"surah":14,"verses":[32]}],"verseLabel":"إبراهيم: 32","question":"ما سرّ تقديم ﴿مِنَ السَّمَاءِ﴾ على ﴿مَاءً﴾؟","answer":"للاهتمام بجهة نزول الماء وإبراز المنة بها، ولتشويق السامع إلى ما أنزل منها قبل التصريح بالماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص65، تحت «غرض تقديم من السماء على ماء»","url":""}]},{"id":"s14-105","number":105,"surah":14,"verses":[32],"references":[{"surah":14,"verses":[32]}],"verseLabel":"إبراهيم: 32","question":"ما دلالة جمع ﴿الثَّمَرَاتِ﴾ وتعريفها؟","answer":"الجمع يستحضر كثرة الثمار وتنوعها في مقام الامتنان، والتعريف يشير إلى الثمار المعهودة التي يعرف المخاطبون نفعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص66، تحت «دلالة الجمع والتعريف الثمرات»","url":""}]},{"id":"s14-106","number":106,"surah":14,"verses":[32],"references":[{"surah":14,"verses":[32]}],"verseLabel":"إبراهيم: 32","question":"ما سرّ تقديم ﴿لَكُمُ﴾ على الفلك والأنهار؟","answer":"للاهتمام بأن تسخير الفلك والأنهار لنفع المخاطبين، وتعجيل تذكيرهم بالنعمة قبل ذكر ما سخر لهم؛ فيقوى الامتنان والتشويق.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص68، تحت «غرض تقديم لكم على الفلك»","url":""}]},{"id":"s14-107","number":107,"surah":14,"verses":[32],"references":[{"surah":14,"verses":[32]}],"verseLabel":"إبراهيم: 32","question":"ما سرّ جمع ﴿الْأَنْهَارَ﴾ وإفراد ﴿الْبَحْرِ﴾ في الآية؟","answer":"جُمعت الأنهار لاستحضار كثرتها وتفرقها في البلاد، وأفرد البحر لأن المراد جنسه؛ فالتسخير يشمل البحر الذي تجري فيه الفلك دون اختصاص ببحر معين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص71، تحت «علة الجمع الأنهار وإفراد البحر»","url":""}]},{"id":"s14-108","number":108,"surah":14,"verses":[33],"references":[{"surah":14,"verses":[33]}],"verseLabel":"إبراهيم: 33","question":"ما سرّ تقديم ﴿لَكُمُ﴾ قبل الشمس والقمر؟","answer":"للاهتمام بالمخاطبين بوصفهم المنتفعين بهذه النعمة، وتعجيل الامتنان عليهم؛ ثم يأتي ذكر الشمس والقمر بعد تشويق النفس إليهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص73، تحت «غرض تقديم لكم على الشمس»","url":""}]},{"id":"s14-109","number":109,"surah":14,"verses":[33],"references":[{"surah":14,"verses":[33]}],"verseLabel":"إبراهيم: 33","question":"ما دلالة الجمع بين الشمس والقمر والليل والنهار في تعداد النعم؟","answer":"يبين تكامل النعم مع اختلافها؛ فالشمس والقمر والليل والنهار تجتمع آثارها في الضوء والسكون والحركة وسائر مصالح الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص75، تحت «نكتة جمع الأضداد»","url":""}]},{"id":"s14-110","number":110,"surah":14,"verses":[33],"references":[{"surah":14,"verses":[33]},{"surah":16,"verses":[12]}],"verseLabel":"إبراهيم: 33؛ النحل: 12","question":"ما نكتة تقديم الليل على النهار في إبراهيم؟","answer":"يراعى سبقه في الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص75، تحت «نكتة الترتيب في الليل والنهار»","url":""}]},{"id":"s14-177","number":177,"surah":14,"verses":[33],"references":[{"surah":14,"verses":[33]},{"surah":16,"verses":[12]}],"verseLabel":"إبراهيم: 33؛ النحل: 12","question":"ما بلاغة ترتيب الليل والنهار والشمس والقمر في النحل؟","answer":"يراعي قرب النعم وظهور الانتفاع بها؛ فالليل للسكن والنهار للحركة ثم الشمس والقمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص156، تحت «بلاغة الترتيب بين النعم في الآية»","url":""}]},{"id":"s14-111","number":111,"surah":14,"verses":[34],"references":[{"surah":14,"verses":[34]}],"verseLabel":"إبراهيم: 34","question":"ما وجه الجمع بين ﴿من﴾ و﴿كل﴾ في ﴿من كل ما سألتموه﴾؟","answer":"تفيد ﴿من﴾ أنه آتاهم من مطلوباتهم ما تقتضيه حكمته، مع شمول ﴿كل﴾ لأجناسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص79، تحت «وجه الجمع بين من وكل»","url":""}]},{"id":"s14-178","number":178,"surah":14,"verses":[34],"references":[{"surah":14,"verses":[34]}],"verseLabel":"إبراهيم: 34","question":"ما دلالة ﴿ما﴾ وإضافة ﴿كل﴾ إليها؟","answer":"تشمل ما سألوه نطقا وما دل عليه احتياجهم مما تقوم به حياتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص80، تحت «دلالة ما وإضافة كل إليها»","url":""}]},{"id":"s14-112","number":112,"surah":14,"verses":[34],"references":[{"surah":14,"verses":[34]}],"verseLabel":"إبراهيم: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنْ تَعُدُّوا نِعْمَتَ اللَّهِ﴾ بالإفراد؟","answer":"النعمة في معنى المصدر، فيؤدي المفرد معنى الجنس دون حاجة إلى جمعه. وفي إفراده تنبيه إلى أن النعمة الواحدة قد تنطوي على نعم كثيرة لا تحصى.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص82، تحت «نكتة إفراد نعمت»","url":""}]},{"id":"s14-113","number":113,"surah":14,"verses":[34],"references":[{"surah":14,"verses":[34]}],"verseLabel":"إبراهيم: 34","question":"ما دلالة ختام تعداد النعم بـ﴿إِنَّ الْإِنْسَانَ لَظَلُومٌ كَفَّارٌ﴾؟","answer":"يكشف عن ظلم الإنسان لنفسه حين يغفل شكر المنعم، ومبالغته في كفران نعمه؛ فصيغة «ظلوم» و«كفار» تؤكدان شدة الجحود في مقابل كثرة الإنعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص85، تحت «دلالة صيغة كفار وسر مجيئها بعد لظلوم»","url":""}]},{"id":"s14-115","number":115,"surah":14,"verses":[35],"references":[{"surah":14,"verses":[35]}],"verseLabel":"إبراهيم: 35","question":"ما دلالة إيثار استعمال لفظ واجنبني في قوله تعالى: ﴿وَاجْنُبْنِي وَبَنِيَّ أَنْ نَعْبُدَ الْأَصْنَامَ﴾؟","answer":"طلب الإبعاد التام عن عبادة الأصنام وما يتصل بها؛ فلفظ الاجتناب يصور جعل الإنسان وعبادتها في جانبين متباعدين، تحقيقًا للإخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص92، تحت «إيثار استعمال لفظ واجنبني»","url":""}]},{"id":"s14-116","number":116,"surah":14,"verses":[36],"references":[{"surah":14,"verses":[36]}],"verseLabel":"إبراهيم: 36","question":"لماذا قيل: ﴿فمن تبعني﴾؟","answer":"الاتباع اقتداء بإبراهيم في التوحيد والسير على ملته.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص100، تحت «إيثار لفظ تبعني دون غيره»","url":""}]},{"id":"s14-179","number":179,"surah":14,"verses":[36],"references":[{"surah":14,"verses":[36]}],"verseLabel":"إبراهيم: 36","question":"ما دلالة ﴿فإنه مني﴾؟","answer":"تصور شدة اتصال التابع به في الدين وأن رابطة الإيمان هي المقصودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص100، تحت «سر الإخبار بالجار والمجرور مني»","url":""}]},{"id":"s14-117","number":117,"surah":14,"verses":[36],"references":[{"surah":14,"verses":[36]}],"verseLabel":"إبراهيم: 36","question":"ما دلالة قوله: ﴿وَمَنْ عَصَانِي فَإِنَّكَ غَفُورٌ رَحِيمٌ﴾ بدل الدعاء عليه بالعقوبة؟","answer":"يفوض أمر من عصاه إلى الله، ويتلطف في الدعاء بذكر مغفرته ورحمته؛ وفي ذلك أدب ورجاء من إبراهيم، مع ترك الحكم لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص102، تحت «بيان مناسبة فاصلة الآية لسياقها»","url":""}]},{"id":"s14-118","number":118,"surah":14,"verses":[37],"references":[{"surah":14,"verses":[37]}],"verseLabel":"إبراهيم: 37","question":"ما دلالة تكرار ﴿ربنا﴾؟","answer":"يجدد الالتجاء والتضرع عند كل مطلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص106، تحت «موقع إني أسكنت وسر افتتاحها بالنداء وتكرره»","url":""}]},{"id":"s14-180","number":180,"surah":14,"verses":[37],"references":[{"surah":14,"verses":[37]}],"verseLabel":"إبراهيم: 37","question":"ما بلاغة حذف حرف النداء؟","answer":"يصور قرب المدعو وعلمه بحال الداعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص107، تحت «بلاغة حذف حرف النداء»","url":""}]},{"id":"s14-119","number":119,"surah":14,"verses":[37],"references":[{"surah":14,"verses":[37]}],"verseLabel":"إبراهيم: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿بِوَادٍ﴾ لا بمكان؟","answer":"لأن اللفظ يحدد طبيعة الموضع الذي أسكن فيه ذريته: فضاء منخفض بين جبال تجري به السيول؛ فهو أدق تصويرًا من لفظ المكان العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص109، تحت «إيثار الوادي دون غيره من المرادفات»","url":""}]},{"id":"s14-120","number":120,"surah":14,"verses":[37],"references":[{"surah":14,"verses":[37]}],"verseLabel":"إبراهيم: 37","question":"لماذا وصف البيت بـ﴿الْمُحَرَّمِ﴾ لا الحرام؟","answer":"صيغة «المحرَّم» تدل على أن الله جعل للبيت حرمة ومنع التعرض له؛ فتبرز فعل التحريم وحماية البيت، مع ما يدل عليه السياق من عظمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص111، تحت «إيثار صيغة المفعول المحرم»","url":""}]},{"id":"s14-121","number":121,"surah":14,"verses":[37],"references":[{"surah":14,"verses":[37]}],"verseLabel":"إبراهيم: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿لِيُقِيمُوا الصَّلَاةَ﴾ فجعلها غاية الإسكان؟","answer":"اللام للتعليل؛ أي إن علة إسكانهم بهذا الوادي أن يقيموا الصلاة، فدلّ على أن العبادة هي مقصد الإسكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص112، تحت «البلاغة في قوله ليقيموا الصلاة»","url":""}]},{"id":"s14-122","number":122,"surah":14,"verses":[37],"references":[{"surah":14,"verses":[37]}],"verseLabel":"إبراهيم: 37","question":"لماذا استعمل لفظ ﴿أفئدة﴾؟","answer":"يستحضر القلوب المتقدة شوقا، فيناسب قوة الميل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص113، تحت «سر استعمال أفئدة»","url":""}]},{"id":"s14-181","number":181,"surah":14,"verses":[37],"references":[{"surah":14,"verses":[37]}],"verseLabel":"إبراهيم: 37","question":"ما بلاغة الاستعارة في ﴿تهوي إليهم﴾؟","answer":"تصور شدة اندفاع القلوب إليهم بالحب والرغبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص113، تحت «بلاغة الاستعارة التصريحية تهوي»","url":""}]},{"id":"s14-123","number":123,"surah":14,"verses":[38],"references":[{"surah":14,"verses":[38]}],"verseLabel":"إبراهيم: 38","question":"ما سرّ تقديم ﴿مَا نُخْفِي﴾ على ﴿وَمَا نُعْلِنُ﴾؟","answer":"لأن الخفي أدق وأغمض، فذكر العلم به يبرز إحاطة علم الله؛ وكثير مما يعلن يسبقه خفاء، والله يعلمه في الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص123، تحت «نكتة تقديم ما نخفي على وما نعلن»","url":""}]},{"id":"s14-124","number":124,"surah":14,"verses":[38],"references":[{"surah":14,"verses":[38]}],"verseLabel":"إبراهيم: 38","question":"لماذا استعمل المضارع ﴿تَعْلَمُ﴾؟","answer":"للدلالة على استمرار علم الله وإحاطته بكل شيء، فلا ينقطع علمه بما يخفيه الناس وما يعلنونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص122، تحت «إيثار صيغة المضارع تعلم»","url":""}]},{"id":"s14-125","number":125,"surah":14,"verses":[39],"references":[{"surah":14,"verses":[39]}],"verseLabel":"إبراهيم: 39","question":"لماذا قال: ﴿وهب لي﴾ لا أعطاني؟","answer":"الهبة عطاء بلا عوض فتبرز محض فضل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص131، تحت «إيثار استعمال لفظ وهب دون غيره»","url":""}]},{"id":"s14-182","number":182,"surah":14,"verses":[39],"references":[{"surah":14,"verses":[39]}],"verseLabel":"إبراهيم: 39","question":"ما نكتة ذكر الكبر؟","answer":"يعظم النعمة لأنها جاءت في سن لا تجري فيها عادة الولادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص133، تحت «نكتة ذكر حال الكبر»","url":""}]},{"id":"s14-126","number":126,"surah":14,"verses":[39],"references":[{"surah":14,"verses":[39]}],"verseLabel":"إبراهيم: 39","question":"ما دلالة الجمع بين إسماعيل وإسحاق في هذا الحمد؟","answer":"يجمع النعمتين اللتين وهبهما الله لإبراهيم على كبر، إظهارًا لامتنانه وسروره بما قرت به عينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص132، تحت «نكتة الجمع بين إسماعيل وإسحاق»","url":""}]},{"id":"s14-127","number":127,"surah":14,"verses":[40],"references":[{"surah":14,"verses":[40]}],"verseLabel":"إبراهيم: 40","question":"ما سرّ التعبير بـ﴿مُقِيمَ الصَّلَاةِ﴾ في دعاء إبراهيم؟","answer":"اسم الفاعل «مقيم» يطلب رسوخ الصفة ودوامها؛ فهو يسأل أن يكون محافظًا على الصلاة قائمًا بها على وجهها، لا أن يقع منه فعل عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص137–138، تحت «نكتة التعبير بمقيم دون الفعل»","url":""}]},{"id":"s14-128","number":128,"surah":14,"verses":[40],"references":[{"surah":14,"verses":[40]}],"verseLabel":"إبراهيم: 40","question":"ما دلالة الانتقال من ﴿رَبِّ﴾ إلى ﴿رَبَّنَا﴾؟","answer":"بدأ متكلمًا عن نفسه وهو يدعو له ولذريته، ثم جمع في ﴿ربنا﴾ مراعيًا من تبعه من ذريته؛ فكأنه يجمعهم معه في سؤال قبول الدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص138، تحت «سر العدول عن المفرد في ربنا»","url":""}]},{"id":"s14-129","number":129,"surah":14,"verses":[40],"references":[{"surah":14,"verses":[40]}],"verseLabel":"إبراهيم: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿وَتَقَبَّلْ دُعَاءِ﴾ لا اقبل؟","answer":"صيغة التفعّل تفيد المبالغة في سؤال القبول والعناية بالدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص139، تحت «لطيفة إيثار صيغة التفعل وتقبل»","url":""}]},{"id":"s14-130","number":130,"surah":14,"verses":[41],"references":[{"surah":14,"verses":[41]}],"verseLabel":"إبراهيم: 41","question":"ما دلالة جمع إبراهيم نفسه ووالديه والمؤمنين في دعاء المغفرة؟","answer":"بدأ بنفسه ثم والديه ثم عمم المؤمنين؛ فجمع بين العناية بالأقربين والحرص على شمول الدعاء لأهل الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص142–143، تحت «فائدة تخصيص القيود»","url":""}]},{"id":"s14-131","number":131,"surah":14,"verses":[42],"references":[{"surah":14,"verses":[42]}],"verseLabel":"إبراهيم: 42","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تَحْسَبَنَّ اللَّهَ غَافِلًا﴾ مع أن المؤمن لا يظن ذلك؟","answer":"النهي تثبيت للرسول ووعيد للظالمين؛ تأخر العقوبة ليس غفلة بل إمهال إلى يوم معلوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص146، تحت «بلاغة الكناية في النهي بلا تحسبن»","url":""}]},{"id":"s14-132","number":132,"surah":14,"verses":[42],"references":[{"surah":14,"verses":[42]}],"verseLabel":"إبراهيم: 42","question":"ما سرّ التعبير بقوله تعالى: ﴿عَمَّا يَعْمَلُ الظَّالِمُونَ﴾ بالمضارع؟","answer":"تصور صيغة المضارع تجدد ظلمهم واستمرارهم فيه؛ فيتوجه الوعيد إلى ما يواصلون ارتكابه من الكفر والاعتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص149، تحت «سر إيثار صيغة المضارع يعمل»","url":""}]},{"id":"s14-133","number":133,"surah":14,"verses":[42],"references":[{"surah":14,"verses":[42]}],"verseLabel":"إبراهيم: 42","question":"ما دلالة إيثار التعبير بتشخص في قوله تعالى: ﴿تَشْخَصُ فِيهِ الْأَبْصَارُ﴾؟","answer":"يصوّر اللفظ الأبصار مفتوحة ثابتة لا تطرف من شدة الفزع، فتجتمع فيه دلالة النظر المذهول والجمود أمام الهول.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص150–151، تحت «إيثار التعبير بتشخص»","url":""}]},{"id":"s14-134","number":134,"surah":14,"verses":[43],"references":[{"surah":14,"verses":[43]}],"verseLabel":"إبراهيم: 43","question":"ما دلالة وصفهم بـ﴿مهطعين﴾؟","answer":"يصور إسراعهم إلى الحساب في ذل وخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص157، تحت «إيثار لفظ مهطعين»","url":""}]},{"id":"s14-183","number":183,"surah":14,"verses":[43],"references":[{"surah":14,"verses":[43]}],"verseLabel":"إبراهيم: 43","question":"ما دلالة ﴿مقنعي رؤوسهم﴾؟","answer":"يصور رؤوسا مرفوعة وعيونا شاخصة من الفزع.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص158، تحت «إيثار الوصف الفريد مقنعي ودلالته»","url":""}]},{"id":"s14-135","number":135,"surah":14,"verses":[43],"references":[{"surah":14,"verses":[43]}],"verseLabel":"إبراهيم: 43","question":"ما سرّ إفراد ﴿طَرْفُهُمْ﴾ مع تعدد أصحابه؟","answer":"يشير الإفراد إلى تشابه حال أبصارهم في الجمود والشخوص، حتى كأنها طرف واحد؛ واسم الجنس المفرد يناسب هذا العموم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص160، تحت «نكتة إفراد طرفهم والعدول عن الجمع»","url":""}]},{"id":"s14-136","number":136,"surah":14,"verses":[43],"references":[{"surah":14,"verses":[43]}],"verseLabel":"إبراهيم: 43","question":"لماذا عبر بالفؤاد لا القلب؟","answer":"يستحضر موضع الشعور والتوقد فيبرز شدة الفزع.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص161، تحت «إيثار استعمال لفظ الفؤاد دون القلب»","url":""}]},{"id":"s14-184","number":184,"surah":14,"verses":[43],"references":[{"surah":14,"verses":[43]}],"verseLabel":"إبراهيم: 43","question":"ما سر التشبيه في ﴿وأفئدتهم هواء﴾؟","answer":"يصور القلوب فارغة حائرة قد ذهب إدراكها من شدة الفزع.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص162، تحت «سر التشبيه البليغ للقلوب بالهواء»","url":""}]},{"id":"s14-137","number":137,"surah":14,"verses":[44],"references":[{"surah":14,"verses":[44]}],"verseLabel":"إبراهيم: 44","question":"ما دلالة إسناد الإتيان إلى العذاب في قوله: ﴿يَوْمَ يَأْتِيهِمُ الْعَذَابُ﴾؟","answer":"أُسند الإتيان إلى العذاب مجازًا بمعنى وقوعه عليهم؛ تهويلًا له وتفظيعًا، حتى كأنه يتحرك نحوهم بنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص170–171، تحت «بلاغة المجاز العقلي في إسناد الإتيان إلى العذاب»","url":""}]},{"id":"s14-138","number":138,"surah":14,"verses":[44],"references":[{"surah":14,"verses":[44]}],"verseLabel":"إبراهيم: 44","question":"ما سرّ الاقتصار على ذكر العذاب دون الثواب في هذا الإنذار؟","answer":"لأن الخطاب إنذار للظالمين، فذكر ما يطابق المقام ويزلزل غفلتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص170، تحت «فائدة الاقتصار بذكر إتيان العذاب دون الثواب»","url":""}]},{"id":"s14-139","number":139,"surah":14,"verses":[44],"references":[{"surah":14,"verses":[44]}],"verseLabel":"إبراهيم: 44","question":"ما دلالة صيغة المضارع في ﴿فَيَقُولُ الَّذِينَ ظَلَمُوا﴾؟","answer":"تستحضر مشهد تضرعهم، وتصور تكرر قولهم وإلحاحهم في طلب الإمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص171، تحت «فائدة التعبير بالفعل المضارع في فيقول»","url":""}]},{"id":"s14-140","number":140,"surah":14,"verses":[44],"references":[{"surah":14,"verses":[44]}],"verseLabel":"إبراهيم: 44","question":"ما دلالة وصف الأجل بـ﴿قَرِيبٍ﴾ في طلبهم الإمهال؟","answer":"القريب هنا بمعنى القليل؛ شُبّه قِصر الزمن بقرب المسافة، فهم يسألون مهلة قليلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص174، تحت «دلالة الاستعارة في وصف الأجل بالقرب»","url":""}]},{"id":"s14-141","number":141,"surah":14,"verses":[44],"references":[{"surah":14,"verses":[44]}],"verseLabel":"إبراهيم: 44","question":"ما دلالة الجمع بين ﴿نُجِبْ دَعْوَتَكَ﴾ و﴿نَتَّبِعِ الرُّسُلَ﴾؟","answer":"إجابة الدعوة تشمل الإيمان والتوحيد، ثم خص اتباع الرسل بالذكر إظهارًا لكمال الانقياد واستدراكًا لتكذيبهم السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص174، تحت «فائدة العطف والتتميم في جملة ونتبع الرسل»","url":""}]},{"id":"s14-142","number":142,"surah":14,"verses":[44],"references":[{"surah":14,"verses":[44]}],"verseLabel":"إبراهيم: 44","question":"ما سرّ التعبير بقوله تعالى: ﴿أَوَلَمْ تَكُونُوا أَقْسَمْتُمْ مِنْ قَبْلُ﴾؟","answer":"الاستفهام يقرر قسمهم السابق ويوبخهم عليه، وذكر الكون يستحضر رسوخهم في الغرور والإنكار؛ فيرد طلبهم بالإمهال بما شهدوا به على أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص175، تحت «سر الجواب بالاستفهام»","url":""}]},{"id":"s14-143","number":143,"surah":14,"verses":[44],"references":[{"surah":14,"verses":[44]}],"verseLabel":"إبراهيم: 44","question":"ما دلالة التنكير في ﴿مَا لَكُمْ مِنْ زَوَالٍ﴾؟","answer":"ينفي الزوال على سبيل العموم؛ أي إنهم كانوا ينكرون الانتقال إلى دار الحساب. وجاء تذكيرهم بهذا الزعم تقريرًا لغرورهم وتوبيخًا لهم.","sources":[{"label":"[الموضع الصحيح: إبراهيم: 44] موسوعة التفسير البلاغي، ج25، ص178، تحت «معنى الزوال في هذا الموضع ونكتة تنكير لفظه»","url":""}]},{"id":"s14-144","number":144,"surah":14,"verses":[45],"references":[{"surah":14,"verses":[45]}],"verseLabel":"إبراهيم: 45","question":"ما سرّ تعدية الفعل سكن بحرف الظرفية في قوله تعالى: ﴿وَسَكَنْتُمْ فِي مَسَاكِنِ الَّذِينَ ظَلَمُوا أَنْفُسَهُمْ﴾؟","answer":"يجعل ديار الأمم الهالكة شاهدًا قريبًا على عاقبة الظلم؛ فقد عرفوا آثارهم ومروا بمساكنهم، ومع ذلك لم يعتبروا بما حل بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص182، تحت «سر تعدية الفعل سكن بحرف الظرفية»","url":""}]},{"id":"s14-145","number":145,"surah":14,"verses":[45],"references":[{"surah":14,"verses":[45]}],"verseLabel":"إبراهيم: 45","question":"ما سرّ التعبير في قوله تعالى: ﴿وَضَرَبْنَا لَكُمُ الْأَمْثَالَ﴾ وقدّم ﴿لكم﴾؟","answer":"للاهتمام بأن الأمثال سيقت لبيان الحجة لهم، ولتشويقهم إلى ما يذكر بعدها؛ وتكرار «لكم» يشدد التوبيخ على ترك الاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص184، تحت «فائدة تقديم الجار والمجرور لكم»","url":""}]},{"id":"s14-146","number":146,"surah":14,"verses":[46],"references":[{"surah":14,"verses":[46]}],"verseLabel":"إبراهيم: 46","question":"ما الموقع النحوي لمكرهم ونكتة الإسناد في قوله تعالى: ﴿وَقَدْ مَكَرُوا مَكْرَهُمْ﴾؟","answer":"إضافة المكر إليهم تستوعب أقصى ما دبروه، ثم تضعه كله في علم الله وسلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص189، تحت «الموقع النحوي لمكرهم ونكتة الإسناد»","url":""}]},{"id":"s14-147","number":147,"surah":14,"verses":[46],"references":[{"surah":14,"verses":[46]}],"verseLabel":"إبراهيم: 46","question":"ما دلالة إن واللام وأثر دخولهما في الجملة، وكيف يُوجَّه بلاغيًا القراءات في لتزول في قوله تعالى: ﴿وَإِنْ كَانَ مَكْرُهُمْ لِتَزُولَ مِنْهُ الْجِبَالُ﴾؟","answer":"يختلف التوجيه باختلاف القراءة والإعراب: فعلى النفي يصور عجز مكرهم عن إزالة ما ثبت من آيات الله، وعلى الإثبات يبالغ في تصوير شدته؛ وفي الحالين لا يعجز الله ولا يخرج عن سلطانه.","sources":[{"label":"[الموضع الصحيح: إبراهيم: 46] موسوعة التفسير البلاغي، ج25، ص191–192، تحت «دلالة إن واللام وأثر دخولهما في الجملة؛ توجيه القراءات في لتزول»","url":""}]},{"id":"s14-148","number":148,"surah":14,"verses":[47],"references":[{"surah":14,"verses":[47]}],"verseLabel":"إبراهيم: 47","question":"ما سرّ تقديم ﴿وَعْدِهِ﴾ على ﴿رُسُلَهُ﴾ في قوله: ﴿فَلَا تَحْسَبَنَّ اللَّهَ مُخْلِفَ وَعْدِهِ رُسُلَهُ﴾؟","answer":"قدم الوعد للاهتمام بأنه لا يتخلف، ثم ذكر الرسل زيادة في التثبيت؛ فإذا كان الله لا يخلف وعده أصلًا فكيف بوعده رسله بالنصر؟","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص196، تحت «سر تقديم المفعول الثاني على الأول»","url":""}]},{"id":"s14-149","number":149,"surah":14,"verses":[47],"references":[{"surah":14,"verses":[47]}],"verseLabel":"إبراهيم: 47","question":"ما دلالة ختام الآية بـ﴿عَزِيزٌ ذُو انْتِقَامٍ﴾؟","answer":"العزة تؤكد أن قدرته لا تغلب، والانتقام يلائم وعيد المكذبين الظالمين ونصرة المظلومين؛ فيطمئن الرسل إلى تحقق الوعد.","sources":[{"label":"[الموضع الصحيح: إبراهيم: 47] موسوعة التفسير البلاغي، ج25، ص198، تحت «إيثار صفة العزة والانتقام»","url":""}]},{"id":"s14-150","number":150,"surah":14,"verses":[48],"references":[{"surah":14,"verses":[48]}],"verseLabel":"إبراهيم: 48","question":"ما سرّ تقديم تبديل الأرض على تبديل السماوات؟","answer":"قُدّم تبديل الأرض لقربها منا، ولأن تبديلها أعظم أثرًا بالنسبة إلينا.","sources":[{"label":"[الموضع الصحيح: إبراهيم: 48] موسوعة التفسير البلاغي، ج25، ص204، تحت «نكتة تقديم تبديل الأرض على تبديل السماوات»","url":""}]},{"id":"s14-151","number":151,"surah":14,"verses":[48],"references":[{"surah":14,"verses":[48]}],"verseLabel":"إبراهيم: 48","question":"ما مناسبة صفتي الواحد القهار للسياق في قوله تعالى: ﴿وَبَرَزُوا لِلَّهِ الْوَاحِدِ الْقَهَّارِ﴾؟","answer":"«الواحد» يبطل تعلقهم بالشركاء الذين لا يملكون لهم شيئًا، و«القهار» يصور خضوعهم التام لسلطان الله؛ فيشتد التهديد ويظهر عجزهم عن دفع الحساب.","sources":[{"label":"[الموضع الصحيح: إبراهيم: 48] موسوعة التفسير البلاغي، ج25، ص207، تحت «مناسبة صفتي الواحد القهار للسياق»","url":""}]},{"id":"s14-152","number":152,"surah":14,"verses":[49],"references":[{"surah":14,"verses":[49]}],"verseLabel":"إبراهيم: 49","question":"ما سرّ التعبير في قوله تعالى: ﴿وَتَرَى الْمُجْرِمِينَ﴾ بالمضارع؟","answer":"لاستحضار المشهد حتى يراه المخاطب رأي العين.","sources":[{"label":"[الموضع الصحيح: إبراهيم: 49] موسوعة التفسير البلاغي، ج25، ص213–214، تحت «نكتة التعبير بالفعل المضارع وترى»","url":""}]},{"id":"s14-153","number":153,"surah":14,"verses":[49],"references":[{"surah":14,"verses":[49]}],"verseLabel":"إبراهيم: 49","question":"ما دلالة وصفهم بـ﴿الْمُجْرِمِينَ﴾ في هذا المشهد؟","answer":"يستحضر ما اكتسبوه من جرائم في الاعتقاد والعمل، فيربط مشهد العقوبة بسببها، ويبين أنهم عوقبوا على جناياتهم.","sources":[{"label":"[الموضع الصحيح: إبراهيم: 49] موسوعة التفسير البلاغي، ج25، ص214، تحت «إيثار وصف المجرمين دون الظالمين»","url":""}]},{"id":"s14-154","number":154,"surah":14,"verses":[49],"references":[{"surah":14,"verses":[49]}],"verseLabel":"إبراهيم: 49","question":"ما سرّ التعبير في قوله تعالى: ﴿مُقَرَّنِينَ﴾ لا مقرونين؟","answer":"تضعيف الراء يدل على شدة قرنهم وإحكام وثاقهم وكثرته؛ فيصور ربط بعضهم ببعض أو بقرنائهم مع تضييق القيود عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص215، تحت «علة العدول عن مقرونين إلى مقرنين»","url":""}]},{"id":"s14-155","number":155,"surah":14,"verses":[49],"references":[{"surah":14,"verses":[49]}],"verseLabel":"إبراهيم: 49","question":"ما فائدة قيد في الأصفاد في قوله تعالى: ﴿فِي الْأَصْفَادِ﴾؟","answer":"تصور الظرفية شدة إحاطة القيود بهم، كأن الأصفاد صارت ظرفًا يستغرق أجسادهم؛ فيبرز ضيق وثاقهم وقسوته.","sources":[{"label":"[الموضع الصحيح: إبراهيم: 49] موسوعة التفسير البلاغي، ج25، ص215، تحت «فائدة قيد في الأصفاد»","url":""}]},{"id":"s14-156","number":156,"surah":14,"verses":[50],"references":[{"surah":14,"verses":[50]}],"verseLabel":"إبراهيم: 50","question":"ما دلالة المضارع في ﴿تغشى وجوههم النار﴾؟","answer":"يستحضر المشهد ويدل على استمرار الغشيان وتجدده.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص217، تحت «فائدة استعمال صيغة المضارع وتغشى»","url":""}]},{"id":"s14-185","number":185,"surah":14,"verses":[50],"references":[{"surah":14,"verses":[50]}],"verseLabel":"إبراهيم: 50","question":"لماذا خصت الوجوه بالذكر؟","answer":"لإبراز إصابة أشرف مواضع الإنسان بالعذاب المهين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص217، تحت «علة اختصاص الوجوه بالذكر»","url":""}]},{"id":"s14-157","number":157,"surah":14,"verses":[50],"references":[{"surah":14,"verses":[50]}],"verseLabel":"إبراهيم: 50","question":"ما سرّ تقديم ﴿وُجُوهَهُمُ﴾ على ﴿النار﴾؟","answer":"لأن الوجه أشرف ما في الإنسان، فذُكر وقُدّم تعجيلًا بإهانة المجرمين؛ وإهانته إهانة عظيمة لصاحبه.","sources":[{"label":"[الموضع الصحيح: إبراهيم: 50] موسوعة التفسير البلاغي، ج25، ص218، تحت «سر تقديم المفعول وتغشى وجوههم النار»","url":""}]},{"id":"s14-158","number":158,"surah":14,"verses":[51],"references":[{"surah":14,"verses":[51]}],"verseLabel":"إبراهيم: 51","question":"ما دلالة إيثار استعمال الجزاء وإسناده إلى اسم الجلالة في قوله تعالى: ﴿لِيَجْزِيَ اللَّهُ كُلَّ نَفْسٍ مَا كَسَبَتْ﴾؟","answer":"عُبّر بأن الجزاء هو ما كسبته النفس، لا بأنه جزاء عملها؛ للإشارة إلى المساواة التامة بين العمل وجزائه، حتى كأن الجزاء هو العمل نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص224، تحت «إيثار استعمال الجزاء وإسناده إلى اسم الجلالة»","url":""}]},{"id":"s14-159","number":159,"surah":14,"verses":[52],"references":[{"surah":14,"verses":[52]}],"verseLabel":"إبراهيم: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿هَذَا بَلَاغٌ لِلنَّاسِ﴾ لا للمؤمنين؟","answer":"لأن القرآن حجة ورسالة عامة لكل الناس، وإن اختص أولو الألباب بكمال الاتعاظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص233، تحت «معنى لام التعريف ونوعها في الناس»","url":""}]},{"id":"s14-160","number":160,"surah":14,"verses":[52],"references":[{"surah":14,"verses":[52]}],"verseLabel":"إبراهيم: 52","question":"ما سرّ تقديم ﴿وَلِيُنْذَرُوا بِهِ﴾ قبل العلم بالوحدانية والتذكر؟","answer":"الإنذار يبعث على الخشية والنظر، ثم تهدي الدلائل إلى معرفة وحدانية الله، ويثمر التذكر اتعاظًا وعملًا؛ فالترتيب يبين تتابع آثار البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص236، تحت «سر ترتيب الصفات الواردة في الآية الكريمة»","url":""}]},{"id":"s14-161","number":161,"surah":14,"verses":[52],"references":[{"surah":14,"verses":[52]}],"verseLabel":"إبراهيم: 52","question":"ما وجه البلاغة في القصر وليعلموا أنما هو إله واحد في قوله تعالى: ﴿وَلِيَعْلَمُوا أَنَّمَا هُوَ إِلَهٌ وَاحِدٌ﴾؟","answer":"أسلوب القصر يقرر وحدانية الله وينفي الشريك؛ فالعلم بهذه الحقيقة من مقاصد البلاغ والإنذار ودلائل القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص235، تحت «بلاغة القصر وليعلموا أنما هو إله واحد»","url":""}]},{"id":"s14-162","number":162,"surah":14,"verses":[52],"references":[{"surah":14,"verses":[52]}],"verseLabel":"إبراهيم: 52","question":"لماذا خص أولو الألباب بالتذكر؟","answer":"لأنهم ينتفعون بالمواعظ والحجج فيثمر علمهم عملا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص235، تحت «علة اختصاص أولي الألباب بالذكر وختم الآية بها»","url":""}]},{"id":"s14-186","number":186,"surah":14,"verses":[52],"references":[{"surah":14,"verses":[52]}],"verseLabel":"إبراهيم: 52","question":"ما علاقة خاتمة إبراهيم بأولها؟","answer":"تعود إلى مقصد الكتاب في أولها: إخراج الناس من الظلمات إلى النور.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص236، تحت «علاقة خاتمة السورة بأولها»","url":""}]},{"id":"s14-187","number":187,"surah":14,"verses":[27],"references":[{"surah":14,"verses":[27]}],"verseLabel":"إبراهيم: 27","question":"ما دلالة التعبير بالفعل في قوله: ﴿ويُضلّ الله الظالمين﴾، ولم يُوصف سبحانه بـ«المُضِلّ»؟","answer":"أضاف الله الإضلال إلى نفسه بالصورة الفعلية فقط، للدلالة على أنه أمر طارئ يفعله مع من يستحقه مجازاةً، وليس من صفاته ونعوته، فلم يُسنده إليه بالصورة الاسمية. في حين وُصف الشيطان بالاسم: ﴿إنه عدوّ مضلّ مبين﴾.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص31–32.","url":""}]},{"id":"s14-188","number":188,"surah":14,"verses":[31],"references":[{"surah":14,"verses":[31]}],"verseLabel":"إبراهيم: 31","question":"ما سر ختم آية البقرة بـ﴿والكافرون هم الظالمون﴾، والاكتفاء في إبراهيم بذكر اليوم الذي لا بيع فيه ولا خلال؟","answer":"سبق آية البقرة الكلام على الكافرين: ﴿فمنهم من آمن ومنهم من كفر﴾، فناسب ذكرهم وأنهم هم الظالمون. أما آية إبراهيم فسبقها الكلام على جهنم والمصير إلى النار، فناسب الكلام على اليوم الآخر.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص193.","url":""}]},{"id":"s14-189","number":189,"surah":14,"verses":[34],"references":[{"surah":14,"verses":[34]}],"verseLabel":"إبراهيم: 34","question":"ما سر وصف الإنسان بـ«كفّار» هنا، وهو يُوصف في غيرها بـ«كفور»؟","answer":"وُصف الإنسان بـ«الكفور» كثيرًا كأنه مخلوق من هذا الوصف، ولم يُوصف بـ«الكفّار» إلا هنا، لأن الآية في سياق النعم المتعددة المتجددة التي لا تُحصى، فجاء بصيغة «فعّال» الدالة على التجدد والمزاولة وقتًا بعد وقت، أي أنه يكفر النعم بصورة مستمرة.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص38–39.","url":""}]},{"id":"s14-190","number":190,"surah":14,"verses":[52],"references":[{"surah":14,"verses":[52]}],"verseLabel":"إبراهيم: 52","question":"ما سر ذكر المبتدأ في قوله: ﴿هذا بلاغ للناس﴾، وحذفه في الأحقاف: ﴿بلاغٌ فهل يُهلك إلا القوم الفاسقون﴾؟","answer":"المقام في الأحقاف مقام إيجاز، إذ سبق البلاغ آيتان فقط. أما في إبراهيم فمقام تفصيل، فالبلاغ يبدأ من قوله: ﴿ولا تحسبنّ الله غافلًا﴾ في إحدى عشرة آية، وفُصّل في آية البلاغ نفسها ما لم يُفصّل في الأحقاف، فناسب ذكر المبتدأ.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص112–113.","url":""}]},{"id":"s14-191","number":191,"surah":14,"verses":[6],"references":[{"surah":14,"verses":[6]}],"verseLabel":"إبراهيم: 6","question":"ما سر ترك النداء بـ«يا قوم» في قول موسى: ﴿اذكروا نعمة الله عليكم﴾، وذكره في المائدة: ﴿يا قوم اذكروا نعمة الله عليكم﴾؟","answer":"في المائدة ناداهم بـ«يا قوم» عطفًا لقلوبهم لأنه سيحمّلهم أمرًا شاقًّا هو دخول الأرض المقدسة. أما آية إبراهيم فليس فيها طلب ولا تكليف، بل تذكير بما مرّ بهم من محن. ثم إن القصة في المائدة أطول فزاد النداء. وفي «البرهان» للكرماني توجيه آخر: أن نعم المائدة أعظم فصرّح بالمخاطَب تعظيمًا.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص120–121.","url":""}]},{"id":"s14-192","number":192,"surah":14,"verses":[8],"references":[{"surah":14,"verses":[8]}],"verseLabel":"إبراهيم: 8","question":"ما سر التوكيد بـ«إنّ» واللام في قوله: ﴿إن تكفروا أنتم ومن في الأرض جميعًا فإن الله لغنيّ حميد﴾، وفي لقمان: ﴿ومن كفر فإن الله غنيّ حميد﴾؟","answer":"آية لقمان جرت على التبعيض بـ﴿من كفر﴾ بالماضي، أما آية إبراهيم فافترضت كفر أهل الأرض جميعًا، وجاءت بالمضارع ﴿إن تكفروا﴾ الدال على تجدد الكفر واستمراره، وأكّدت ذلك بالحال ﴿جميعًا﴾، فاقتضى ذلك زيادة التوكيد باللام.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص307–308.","url":""}]},{"id":"s14-193","number":193,"surah":14,"verses":[31],"references":[{"surah":14,"verses":[31]}],"verseLabel":"إبراهيم: 31","question":"ما سر قوله: ﴿قل لعبادي الذين آمنوا يقيموا الصلاة وينفقوا مما رزقناهم سرًّا وعلانية﴾، وفي البقرة: ﴿يا أيها الذين آمنوا أنفقوا مما رزقناكم﴾؟","answer":"ليس في سورة إبراهيم نداء مباشر من الله لعباده، ويكثر فيها الأمر بـ«قل»، بخلاف البقرة. ولما زاد الصلاة على الإنفاق زاد ذكر «العباد»، وذكر الصلاة لقول إبراهيم بعدها: ﴿ربّ اجعلني مقيم الصلاة﴾، وذكر ﴿سرًّا وعلانية﴾ لقوله: ﴿ربنا إنك تعلم ما نُخفي وما نُعلن﴾. أما البقرة فالسياق فيها سياق إنفاق.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص188–191.","url":""}]},{"id":"s14-194","number":194,"surah":14,"verses":[31],"references":[{"surah":14,"verses":[31]}],"verseLabel":"إبراهيم: 31","question":"ما الفرق بين ﴿ولا خِلال﴾ هنا، و﴿ولا خُلّة ولا شفاعة﴾ في البقرة؟","answer":"الخُلّة الصداقة، و«الخِلال» تحتمل أن تكون جمعها أو مصدر «خالل» الدال على المشاركة، فهي أشمل. ولما زادت آية إبراهيم في العباد والصلاة والسرّ والعلانية زادت في معنى الخلّة، وجرى في السورة ذكر موالاة الأتباع والشيطان. وذُكرت الشفاعة في البقرة لقوله بعدها: ﴿من ذا الذي يشفع عنده إلا بإذنه﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص191–192.","url":""}]},{"id":"s14-195","number":195,"surah":14,"verses":[34],"references":[{"surah":14,"verses":[34]}],"verseLabel":"إبراهيم: 34","question":"ما سر الختم بـ﴿إن الإنسان لظلوم كفّار﴾ هنا، وبـ﴿إن الله لغفور رحيم﴾ في النحل، مع تشابه الآيتين؟","answer":"ليس ذلك مراعاةً للفاصلة وحدها؛ فآية إبراهيم في سياق وصف الإنسان وما جُبل عليه: ﴿الذين بدّلوا نعمة الله كفرًا﴾، فختمت بصفة المُنعَم عليه. وآية النحل في سياق صفات الله ونعمه فختمت بصفة المُنعِم. وهذا التوجيه في «البرهان» أيضًا.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص222 وص224–226.","url":""}]},{"id":"s15-1","number":1,"surah":15,"verses":[1],"references":[{"surah":15,"verses":[1]}],"verseLabel":"الحجر: 1","question":"ما النكتة البلاغية في تأخير وصف قرآن على وصف الكتاب في قوله تعالى: ﴿تِلْكَ آيَاتُ الْكِتَابِ وَقُرْآنٍ مُبِينٍ﴾؟","answer":"جمع الوصفان بين كونه كتابًا مشتملًا على كمالات الكتب الإلهية، وقرآنًا مقروءًا متميزًا عنها؛ وفي وصفه بالكتاب أيضًا إشارة إلى أنه سيكتب ويحفظ، مع كونه متلوًّا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص263، تحت «نكتة تأخير وصف قرآن على وصف الكتاب»","url":""}]},{"id":"s15-2","number":2,"surah":15,"verses":[1],"references":[{"surah":15,"verses":[1]}],"verseLabel":"الحجر: 1","question":"ما دلالة إضافة ﴿آيَاتُ﴾ إلى ﴿الْكِتَابِ﴾؟","answer":"تحتمل الإضافة أن تكون بمعنى «من»، أي آيات من الكتاب، فيكون القرآن بعضه شبيهًا ببعض في البيان. ويجوز أن يراد وصف الآيات بصفات الكتاب كله، تعظيمًا لشأنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص262، تحت «سر الإضافة في قوله آيات الكتاب»","url":""}]},{"id":"s15-3","number":3,"surah":15,"verses":[1],"references":[{"surah":15,"verses":[1]}],"verseLabel":"الحجر: 1","question":"ما سرّ تأخير وصف ﴿قُرْآنٍ﴾ عن وصف ﴿الْكِتَابِ﴾؟","answer":"أُخّر وصف القرآنية لأنه أدخل في المدح وأرسخ في التعريف بهذا الوحي، بعد التنبيه أولًا على اشتماله على كمالات الكتب الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص263، تحت «نكتة تأخير وصف قرآن على وصف الكتاب»","url":""}]},{"id":"s15-4","number":4,"surah":15,"verses":[1],"references":[{"surah":15,"verses":[1]}],"verseLabel":"الحجر: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿مُبِينٍ﴾ وحذف ما يبينه؟","answer":"على تفسير «مبين» بمعنى مُظهِر، حُذف متعلقه ليفيد العموم: فهو يبيّن الحق والهدى، وسبل الضلال ليُتجنّب، وكل ما يحتاج الناس إلى بيانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص264، تحت «فائدة حذف متعلق الوصف مبين»","url":""}]},{"id":"s15-5","number":5,"surah":15,"verses":[2],"references":[{"surah":15,"verses":[2]}],"verseLabel":"الحجر: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿رُبَمَا يَوَدُّ الَّذِينَ كَفَرُوا﴾ مع أن الندم محقق؟","answer":"ليس المراد الشك في الندم؛ ومن توجيهاته أن «ربما» للتقليل تهديدًا: لو وقع هذا التمني مرة واحدة لكفى باعثًا على الإيمان، فكيف وهو يتكرر؟ وقيل: هي هنا للتكثير.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص267، تحت «بلاغة التعبير بقوله ربما في السياق»","url":""}]},{"id":"s15-6","number":6,"surah":15,"verses":[2],"references":[{"surah":15,"verses":[2]}],"verseLabel":"الحجر: 2","question":"ما سرّ التعبير بالمضارع في ﴿يَوَدُّ﴾؟","answer":"يصور تجدد تمنيهم الإسلام كلما ظهرت لهم حقيقته، ويستحضر الأمر المستقبل كأنه واقع؛ تأكيدًا لتحققه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص268، تحت «فائدة التعبير بصيغة المضارع في قوله يود»","url":""}]},{"id":"s15-7","number":7,"surah":15,"verses":[2],"references":[{"surah":15,"verses":[2]}],"verseLabel":"الحجر: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿الَّذِينَ كَفَرُوا﴾ لا الكافرون؟","answer":"تُبيّن الصلة سبب ندامتهم؛ فكفرهم بالقرآن هو الذي أفضى إلى هذا التمني.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص268، تحت «بلاغة التعبير بالاسم الموصول الذين وصلته كفروا»","url":""}]},{"id":"s15-8","number":8,"surah":15,"verses":[2],"references":[{"surah":15,"verses":[2]}],"verseLabel":"الحجر: 2","question":"ما دلالة حذف متعلّق ﴿كَفَرُوا﴾؟","answer":"يُفهم من السياق كفرهم بالكتاب المنزل، وحذف المتعلق يجعل الكفر كالوصف اللازم لهم، وفيه تعظيم لشأن الإيمان وتهويل لعاقبة الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص269، تحت «نكتة حذف متعلق الفعل في قوله كفروا»","url":""}]},{"id":"s15-9","number":9,"surah":15,"verses":[2],"references":[{"surah":15,"verses":[2]}],"verseLabel":"الحجر: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿لَوْ كَانُوا مُسْلِمِينَ﴾ بصيغة الغيبة؟","answer":"حُكِي تمنيهم بضمير الغائب إظهارًا لحقارتهم وإهمال شأنهم، مع إبقاء السياق على نسق واحد في الإخبار عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص270، تحت «سبب إيثار التعبير بصيغة الغيبة لو كانوا»","url":""}]},{"id":"s15-10","number":10,"surah":15,"verses":[3],"references":[{"surah":15,"verses":[3]}],"verseLabel":"الحجر: 3","question":"ما دلالة الأمر في قوله تعالى: ﴿ذرهم﴾؟","answer":"الأمر للتهديد والوعيد؛ أي اتركهم فيما اختاروه حتى يلقوا عاقبة إعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص273، تحت «بلاغة المجاز بالأمر في قوله ذرهم»","url":""}]},{"id":"s15-164","number":164,"surah":15,"verses":[3],"references":[{"surah":15,"verses":[3]}],"verseLabel":"الحجر: 3","question":"ما بلاغة التعريض في قوله تعالى: ﴿يأكلوا ويتمتعوا﴾؟","answer":"في الاقتصار على الأكل والمتاع تعريض بانحصار همهم في الشهوات وإعراضهم عن الإيمان والعمل للآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص274، تحت «بلاغة التعريض في سياق الآية البليغ»","url":""}]},{"id":"s15-11","number":11,"surah":15,"verses":[3],"references":[{"surah":15,"verses":[3]}],"verseLabel":"الحجر: 3","question":"ما سرّ تقديم الضمير في ﴿وَيُلْهِهِمُ الْأَمَلُ﴾؟","answer":"تقدّم الضمير على الفاعل الظاهر لتأكيد استيلاء الأمل عليهم؛ وفيه قصر إضافي كأن الأمل لم يله أحدًا مثلهم، توبيخًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص276، تحت «فائدة تقديم المفعول الضمير على الفاعل الظاهر»","url":""}]},{"id":"s15-12","number":12,"surah":15,"verses":[3],"references":[{"surah":15,"verses":[3]}],"verseLabel":"الحجر: 3","question":"ما دلالة حذف ما يلهيهم عنه الأمل؟","answer":"يفيد الحذف عموم ما شغلهم عنه الأمل، من الإيمان والطاعة والخير؛ فلا ينحصر إلهاؤه في أمر واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص276، تحت «سبب إيثار حذف متعلق الفعل ويلههم»","url":""}]},{"id":"s15-13","number":13,"surah":15,"verses":[3],"references":[{"surah":15,"verses":[3]}],"verseLabel":"الحجر: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿فَسَوْفَ يَعْلَمُونَ﴾ ولم يذكر ما يعلمون؟","answer":"حُذف المفعول للتهويل؛ فيُترك ما سيعلمونه من وبال وعاقبة مفتوحًا، فيشتد وقع التهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص277، 278، تحت «مناسبة حذف متعلق الفعل يعلمون»","url":""}]},{"id":"s15-14","number":14,"surah":15,"verses":[4],"references":[{"surah":15,"verses":[4]}],"verseLabel":"الحجر: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا أَهْلَكْنَا مِنْ قَرْيَةٍ﴾ لا من أهل قرية؟","answer":"ذكر القرية يُشعر بأن الإهلاك يتناول الناس وموضع اجتماعهم، فيصور الاستئصال وعظم العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص282، تحت «نكتة التعبير بلفظ قرية في السياق»","url":""}]},{"id":"s15-15","number":15,"surah":15,"verses":[4],"references":[{"surah":15,"verses":[4]}],"verseLabel":"الحجر: 4","question":"ما دلالة ﴿مِنْ﴾ مع النكرة في ﴿مَا أَهْلَكْنَا مِنْ قَرْيَةٍ﴾؟","answer":"النكرة في سياق النفي تفيد العموم، وزيادة «من» تؤكد استغراقه: فما من قرية إلا ويجري إهلاكها وفق الأجل المعلوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص281، تحت «دلالة مجيء من في قوله من قرية»","url":""}]},{"id":"s15-16","number":16,"surah":15,"verses":[4],"references":[{"surah":15,"verses":[4]}],"verseLabel":"الحجر: 4","question":"ما بلاغة الاستعارة في وصف أجل الأمة بأنه ﴿كتاب﴾؟","answer":"شُبّه الأجل المحدود بكتاب مضبوط لا يقبل زيادة ولا نقصًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص282، تحت «بلاغة الاستعارة في قوله كتاب»","url":""}]},{"id":"s15-165","number":165,"surah":15,"verses":[4],"references":[{"surah":15,"verses":[4]}],"verseLabel":"الحجر: 4","question":"ما دلالة وصف كتاب الأجل بأنه ﴿معلوم﴾؟","answer":"يؤكد أنه ثابت معلوم عند الله، فلا يُنسى ولا يتقدم ولا يتأخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص283، تحت «دلالة صفة الأجل في قوله معلوم»","url":""}]},{"id":"s15-17","number":17,"surah":15,"verses":[5],"references":[{"surah":15,"verses":[5]}],"verseLabel":"الحجر: 5","question":"ما سرّ إسناد السبق والاستئخار إلى ﴿أُمَّةٍ﴾ بعد ذكر ﴿قَرْيَةٍ﴾؟","answer":"إسناده إلى الأمة يبين أن جماعة الناس، مهما بلغت قوتها واجتماعها، لا تستطيع تقديم أجلها أو تأخيره؛ أما ذكر القرية قبل ذلك فيناسب تصوير الاستئصال الشامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص288، 289، تحت «نكتة الإسناد إلى الأمة دون القرية»","url":""}]},{"id":"s15-18","number":18,"surah":15,"verses":[5],"references":[{"surah":15,"verses":[5]}],"verseLabel":"الحجر: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا تَسْبِقُ... وَمَا يَسْتَأْخِرُونَ﴾ بالمضارع؟","answer":"صيغة المضارع تدل على دوام هذا الحكم في الأمم الماضية والباقية: لا تتجاوز أمة أجلها المقدر بتقديم أو تأخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص289، 290، تحت «سر ورود صيغة المضارع تسبق ويستأخرون»","url":""}]},{"id":"s15-19","number":19,"surah":15,"verses":[5],"references":[{"surah":15,"verses":[5]}],"verseLabel":"الحجر: 5","question":"ما دلالة صيغة الاستفعال في ﴿يَسْتَأْخِرُونَ﴾؟","answer":"تصوّر الصيغة تعلق نفوسهم بطلب التأخير، ثم تنفي حصوله؛ فيشتد الزجر عما يوقعهم في العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص289، تحت «نكتة إيثار صيغة الاستفعال يستأخرون»","url":""}]},{"id":"s15-20","number":20,"surah":15,"verses":[6],"references":[{"surah":15,"verses":[6]}],"verseLabel":"الحجر: 6","question":"ما وجه قولهم ساخرين: ﴿يَا أَيُّهَا الَّذِي نُزِّلَ عَلَيْهِ الذِّكْرُ﴾؟","answer":"نادوه بالوصف الذي كانوا يجحدونه، ثم وصفوه بالجنون؛ فكان ذكر التنزيل حكاية لزعمه في اعتقادهم، على سبيل التهكم والاستهزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص295، تحت «بلاغة التهكم على خلاف مقتضى الظاهر»","url":""}]},{"id":"s15-21","number":21,"surah":15,"verses":[6],"references":[{"surah":15,"verses":[6]}],"verseLabel":"الحجر: 6","question":"ما سرّ اختيارهم البناء للمفعول في قولهم: ﴿نُزِّلَ عَلَيْهِ﴾؟","answer":"حكاية كلامهم بالبناء للمفعول تُظهر إنكارهم أن يكون الذكر من عند الله، مع تركهم ذكر المنزِّل طعنًا في الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص295، تحت «سر إيثار التعبير بصيغة المبني للمفعول نزل»","url":""}]},{"id":"s15-22","number":22,"surah":15,"verses":[6],"references":[{"surah":15,"verses":[6]}],"verseLabel":"الحجر: 6","question":"ما دلالة تسمية القرآن ﴿الذِّكْرَ﴾ هنا؟","answer":"اختير وصف «الذكر» الجامع لما يذكّر به القرآن من الحق، وهو أيضًا كتاب يُتلى فيبقى ذكره متجددًا؛ فدل الوصف على حقيقة القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص296، تحت «نكتة التعبير بلفظ الذكر»","url":""}]},{"id":"s15-23","number":23,"surah":15,"verses":[6],"references":[{"surah":15,"verses":[6]}],"verseLabel":"الحجر: 6","question":"ما سرّ توالي التأكيد في قولهم: ﴿إِنَّكَ لَمَجْنُونٌ﴾؟","answer":"بالغوا في تأكيد اتهامهم ليظهروا الجزم به، مع علمهم بصدق الرسول؛ فهو إصرار على الباطل، وقد يُراد به تثبيت هذا الزعم عند الحاضرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص297، 298، تحت «فائدة تتابع التأكيد في إنك لمجنون»","url":""}]},{"id":"s15-24","number":24,"surah":15,"verses":[7],"references":[{"surah":15,"verses":[7]}],"verseLabel":"الحجر: 7","question":"ما دلالة تخصيص الملائكة في طلبهم: ﴿لَوْ مَا تَأْتِينَا بِالْمَلَائِكَةِ﴾؟","answer":"طلبوا أن تأتي الملائكة لتشهد بنبوته وتصدق وعيده، أو لتعاقبهم إن كذبوه؛ وهو طلب عناد وتحدٍّ، لا طلب هداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص301، تحت «نكتة إيثار ذكر الملائكة»","url":""}]},{"id":"s15-25","number":25,"surah":15,"verses":[7],"references":[{"surah":15,"verses":[7]}],"verseLabel":"الحجر: 7","question":"ما وجه قولهم: ﴿إِنْ كُنْتَ مِنَ الصَّادِقِينَ﴾ مع حذف المتعلق؟","answer":"حذف المتعلق يعم ما أخبر به الرسول من نبوته ونزول القرآن ووعيد المكذبين؛ فكأنهم يطالبونه بالملائكة شاهدًا على صدقه في ذلك كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص301، 302، تحت «سر حذف متعلق الاسم المشتق الصادقين»","url":""}]},{"id":"s15-26","number":26,"surah":15,"verses":[8],"references":[{"surah":15,"verses":[8]}],"verseLabel":"الحجر: 8","question":"لماذا جاء الجواب: ﴿مَا نُنَزِّلُ الْمَلَائِكَةَ إِلَّا بِالْحَقِّ﴾؟","answer":"رد الجواب على أصل اقتراحهم: إنزال الملائكة من أمر الله، ولا يكون إلا بالحق والحكمة، وليس تابعًا لتعنتهم أو اختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص304، تحت «بلاغة الجواب في سياق الآية البليغ»","url":""}]},{"id":"s15-27","number":27,"surah":15,"verses":[8],"references":[{"surah":15,"verses":[8]}],"verseLabel":"الحجر: 8","question":"ما دلالة لفظ بالحق في السياق في قوله تعالى: ﴿بِالْحَقِّ﴾؟","answer":"الباء للملابسة: لا ينفك تنزيل الملائكة عن الحق والحكمة. ومن تفسير الحق هنا الأمر الفاصل بالعذاب، وعندئذ لا يبقى للمكذبين إمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص306، تحت «دلالة لفظ بالحق في السياق»","url":""}]},{"id":"s15-28","number":28,"surah":15,"verses":[8],"references":[{"surah":15,"verses":[8]}],"verseLabel":"الحجر: 8","question":"أين تتجلى براعة التعبير بحرف الجزاء إذا في السياق في قوله تعالى: ﴿وَمَا كَانُوا إِذًا مُنْظَرِينَ﴾؟","answer":"تفيد «إذًا» جواب شرط مقدر: لو نزلت الملائكة على الوجه الذي طلبوه، لما أُمهلوا؛ فصار مقترحهم نفسه سببًا للوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص308، تحت «براعة التعبير بحرف الجزاء إذا في السياق»","url":""}]},{"id":"s15-29","number":29,"surah":15,"verses":[9],"references":[{"surah":15,"verses":[9]}],"verseLabel":"الحجر: 9","question":"ما دلالة توالي التأكيد في ﴿إِنَّا نَحْنُ نَزَّلْنَا الذِّكْرَ﴾؟","answer":"لرد إنكارهم واستهزائهم بأقوى تقرير: المنزّل هو الله نفسه لا مدخل لبشر في مصدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص315، تحت «دلالة تتابع المؤكدات في آية الحفظ»","url":""}]},{"id":"s15-30","number":30,"surah":15,"verses":[9],"references":[{"surah":15,"verses":[9]}],"verseLabel":"الحجر: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿نَزَّلْنَا﴾ لا أنزلنا؟","answer":"صيغة التفعيل تفيد تكثير التنزيل وتعظيمه، وتناسب نزول القرآن متدرجًا مفرقًا على الرسول، مع بيان عناية الله به.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص313، تحت «دلالة صيغة فعل في قوله نزلنا»","url":""}]},{"id":"s15-31","number":31,"surah":15,"verses":[9],"references":[{"surah":15,"verses":[9]}],"verseLabel":"الحجر: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنَّا لَهُ لَحَافِظُونَ﴾ جملة اسمية؟","answer":"لإفادة الثبات والدوام، لا حفظًا مؤقتًا ينتهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص314، تحت «فائدة ورود الجملة الاسمية في السياق»","url":""}]},{"id":"s15-32","number":32,"surah":15,"verses":[9],"references":[{"surah":15,"verses":[9]}],"verseLabel":"الحجر: 9","question":"ما سرّ تقديم ﴿لَهُ﴾ على ﴿لَحَافِظُونَ﴾؟","answer":"يفيد تقديم «له» تخصيص الذكر بهذا الحفظ المضمون من الله، دون سائر الكتب التي وُكل حفظها إلى أهلها، مع تأكيد العناية به.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص315، تحت «دلالة تقديم له على لحافظون»","url":""}]},{"id":"s15-33","number":33,"surah":15,"verses":[9],"references":[{"surah":15,"verses":[9]}],"verseLabel":"الحجر: 9","question":"ما دلالة حذف متعلّق ﴿لَحَافِظُونَ﴾؟","answer":"يفيد الحذف شمول الحفظ من كل ما لا يليق بالقرآن، من طعن وزيادة ونقص وتبديل، مع استمرار حفظه في كل زمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص316، تحت «إيثار حذف متعلق اسم الفاعل لحافظون»","url":""}]},{"id":"s15-34","number":34,"surah":15,"verses":[10],"references":[{"surah":15,"verses":[10]}],"verseLabel":"الحجر: 10","question":"ما فائدة التأكيد بقوله ولقد؟","answer":"يؤكد القسم و«قد» سبق إرسال الرسل، وفي تذكير النبي بما لقوه من قومهم تسلية له وتثبيت أمام استهزاء المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص318، تحت «فائدة التأكيد بقوله ولقد»","url":""}]},{"id":"s15-35","number":35,"surah":15,"verses":[10],"references":[{"surah":15,"verses":[10]}],"verseLabel":"الحجر: 10","question":"ما دلالة التعبير بـ﴿في﴾ في قوله تعالى: ﴿في شيع الأولين﴾؟","answer":"تشعر ﴿في﴾ بتمكن الرسل في أقوامهم ومخالطتهم لهم مع قيام الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص319، تحت «نكتة إيثار التعبير بفي في السياق»","url":""}]},{"id":"s15-166","number":166,"surah":15,"verses":[10],"references":[{"surah":15,"verses":[10]}],"verseLabel":"الحجر: 10","question":"ما سرّ التعبير بلفظ ﴿شيع﴾؟","answer":"الشيع فرق يجتمع أفرادها على ما يتبعونه، وفي اللفظ تصوير لاتباع المكذبين بعضهم بعضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص320، تحت «سر التعبير بلفظ شيع في السياق»","url":""}]},{"id":"s15-36","number":36,"surah":15,"verses":[11],"references":[{"surah":15,"verses":[11]}],"verseLabel":"الحجر: 11","question":"ما فائدة مجيء من في قوله تعالى: ﴿مَا يَأْتِيهِمْ مِنْ رَسُولٍ﴾؟","answer":"«من» تؤكد الاستغراق: ما جاءهم رسول قط إلا قابلوه بالنمط نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص322، تحت «فائدة مجيء من»","url":""}]},{"id":"s15-38","number":38,"surah":15,"verses":[12],"references":[{"surah":15,"verses":[12]}],"verseLabel":"الحجر: 12","question":"ما نكتة التعبير بـ﴿نسلكه﴾؟","answer":"السلك إدخال دقيق كإدخال الخيط في الإبرة، فيصوّر تمكن ما أُدخل في قلوبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص329، تحت «نكتة التعبير بلفظ نسلكه»","url":""}]},{"id":"s15-167","number":167,"surah":15,"verses":[12],"references":[{"surah":15,"verses":[12]}],"verseLabel":"الحجر: 12","question":"إلى ماذا يعود الضمير في قوله تعالى: ﴿نسلكه﴾؟","answer":"يحتمل عوده إلى التكذيب فيتمكن في قلوبهم، أو إلى القرآن فيدخلها وهم يستقبلونه بالاستهزاء فلا ينتفعون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص329، تحت «دلالة عود الضمير في قوله نسلكه»","url":""}]},{"id":"s15-39","number":39,"surah":15,"verses":[12],"references":[{"surah":15,"verses":[12]}],"verseLabel":"الحجر: 12","question":"ما سرّ وصفهم بـ﴿الْمُجْرِمِينَ﴾ بدل الإضمار؟","answer":"عُدل عن الضمير إلى وصف «المجرمين» لبيان سبب رسوخ التكذيب في قلوبهم: إجرامهم واجتراحهم الذنوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص330، تحت «بلاغة الإظهار في موضع الإضمار»","url":""}]},{"id":"s15-40","number":40,"surah":15,"verses":[13],"references":[{"surah":15,"verses":[13]}],"verseLabel":"الحجر: 13","question":"ما دلالة النفي بـ﴿لَا﴾ في ﴿لَا يُؤْمِنُونَ بِهِ﴾؟","answer":"يناسب النفي بـ«لا» تمكّن الشك في قلوبهم، فيؤكد إصرارهم على عدم الإيمان رغم وصول الذكر إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص332، تحت «فائدة التعبير بلا النافية في السياق»","url":""}]},{"id":"s15-41","number":41,"surah":15,"verses":[14],"references":[{"surah":15,"verses":[14]}],"verseLabel":"الحجر: 14","question":"ما دلالة التعبير بأداة الشرط لو في قوله تعالى: ﴿وَلَوْ فَتَحْنَا عَلَيْهِمْ بَابًا مِنَ السَّمَاءِ﴾؟","answer":"يفرض لهم آية مشاهدة بالغة الوضوح، ثم يبين أنهم سيصرفونها إلى السحر؛ فالعائق عن الإيمان عنادهم، لا قلة الدليل. وتنكير الباب يعظّم شأنه ويُشعر بتعدد أبواب السماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص336، تحت «دلالة التعبير بأداة الشرط لو»","url":""}]},{"id":"s15-42","number":42,"surah":15,"verses":[14],"references":[{"surah":15,"verses":[14]}],"verseLabel":"الحجر: 14","question":"ما دلالة التعبير بـ﴿فظلوا﴾؟","answer":"يصور دوام المشاهدة ووضوحها كوضوح النهار، ويجوز حمله على استمرار العروج نهارًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص338، تحت «بلاغة الاستعارة في قوله فظلوا»","url":""}]},{"id":"s15-168","number":168,"surah":15,"verses":[14],"references":[{"surah":15,"verses":[14]}],"verseLabel":"الحجر: 14","question":"ما نكتة التعبير بـ﴿يعرجون﴾؟","answer":"ذكر العروج يغني عن ذكر النزول؛ لأن رجوع البشر إلى الأرض مفهوم من حالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص338، تحت «نكتة التعبير بلفظ يعرجون»","url":""}]},{"id":"s15-43","number":43,"surah":15,"verses":[15],"references":[{"surah":15,"verses":[15]}],"verseLabel":"الحجر: 15","question":"ما وجه قولهم: ﴿إِنَّمَا سُكِّرَتْ أَبْصَارُنَا﴾؟","answer":"حصروا ما شاهدوه في اختلال أبصارهم، زاعمين أنه تخيل لا حقيقة؛ وهو إمعان في المكابرة مع ظهور الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص339، تحت «بلاغة القصر في قوله إنما سكرت أبصارنا»","url":""}]},{"id":"s15-44","number":44,"surah":15,"verses":[15],"references":[{"surah":15,"verses":[15]}],"verseLabel":"الحجر: 15","question":"ما سرّ الانتقال بـ﴿بَلْ﴾ من ﴿سُكِّرَتْ أَبْصَارُنَا﴾ إلى ﴿قَوْمٌ مَسْحُورُونَ﴾؟","answer":"انتقلوا بـ«بل» إلى دعوى أشد: لم يختل البصر وحده، بل أصاب السحر العقول وسائر الحواس؛ فيظهر تصاعد عنادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص340، تحت «سر إيثار التعبير بالأداة بل»","url":""}]},{"id":"s15-45","number":45,"surah":15,"verses":[16],"references":[{"surah":15,"verses":[16]}],"verseLabel":"الحجر: 16","question":"ما النكتة البلاغية في التعبير بجعلنا في قوله تعالى: ﴿جَعَلْنَا فِي السَّمَاءِ بُرُوجًا﴾؟","answer":"«جعلنا» هنا بمعنى أوجدنا وأبدعنا؛ فالتعبير يبرز آية الخلق والإبداع الدالة على قدرة الله وتوحيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص345، تحت «نكتة التعبير بجعلنا»","url":""}]},{"id":"s15-46","number":46,"surah":15,"verses":[16],"references":[{"surah":15,"verses":[16]}],"verseLabel":"الحجر: 16","question":"ما سرّ تقديم ﴿فِي السَّمَاءِ﴾ على ﴿بُرُوجًا﴾؟","answer":"يفيد تخصيص جعل البروج بالسماء وتأكيد هذا الموضع، مع توجيه النظر إلى آيات ظاهرة أمام المخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص346، تحت «سر تقديم في السماء على بروجا»","url":""}]},{"id":"s15-47","number":47,"surah":15,"verses":[16],"references":[{"surah":15,"verses":[16]}],"verseLabel":"الحجر: 16","question":"ما دلالة حذف ما زُيّنت به السماء في ﴿وَزَيَّنَّاهَا﴾؟","answer":"حذف ما زُيّنت به السماء يفيد تنوع زينتها من أشكال وهيئات وتكثرها وعظمتها، فلا تنحصر في صورة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص348، تحت «سبب إيثار حذف متعلق الفعل وزيناها»","url":""}]},{"id":"s15-48","number":48,"surah":15,"verses":[18],"references":[{"surah":15,"verses":[18]}],"verseLabel":"الحجر: 18","question":"ما وجه البلاغة في الاستعارة استرق السمع في قوله تعالى: ﴿اسْتَرَقَ السَّمْعَ﴾؟","answer":"شُبّه اختلاس السمع بأخذ السارق شيئًا في خفاء؛ وتصوّر صيغة الافتعال ما يبذله الشيطان من تكلف واجتهاد في هذا الاختلاس.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص357، تحت «بلاغة الاستعارة استرق السمع»","url":""}]},{"id":"s15-49","number":49,"surah":15,"verses":[19],"references":[{"surah":15,"verses":[19]}],"verseLabel":"الحجر: 19","question":"ما دلالة وصل ﴿وَالْأَرْضَ مَدَدْنَاهَا﴾ بما قبلها بالواو؟","answer":"عطف دلائل الأرض على دلائل السماء يجمع المشهدين في الاستدلال على قدرة الله وتوحيده، مع المقابلة بين بديع صنعه في كل منهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص361، تحت «فائدة الوصل بالواو والأرض مددناها»","url":""}]},{"id":"s15-50","number":50,"surah":15,"verses":[19],"references":[{"surah":15,"verses":[19]}],"verseLabel":"الحجر: 19","question":"ما دلالة قوله تعالى: ﴿وألقينا﴾ في خلق الجبال؟","answer":"يصور الإلقاء سهولة خلق الجبال العظيمة على الله وكمال قدرته عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص364، تحت «دلالة قوله تعالى وألقينا»","url":""}]},{"id":"s15-169","number":169,"surah":15,"verses":[19],"references":[{"surah":15,"verses":[19]}],"verseLabel":"الحجر: 19","question":"ما نكتة التعبير بلفظ ﴿رواسي﴾؟","answer":"يبرز ثبات الجبال ورسوخها، فيعظم المخلوق ويبين قدرة خالقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص364، تحت «نكتة التعبير بلفظ رواسي»","url":""}]},{"id":"s15-51","number":51,"surah":15,"verses":[19],"references":[{"surah":15,"verses":[19]}],"verseLabel":"الحجر: 19","question":"ما سرّ تقديم ﴿فِيهَا﴾ في ﴿وَأَلْقَيْنَا فِيهَا رَوَاسِيَ﴾؟","answer":"التقديم يؤكد موضع إلقاء الرواسي، ويوجه النظر إلى عظم أثرها في الأرض، من غير أن يلزم منه الحصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص363، 364، تحت «فائدة تقديم فيها»","url":""}]},{"id":"s15-52","number":52,"surah":15,"verses":[20],"references":[{"surah":15,"verses":[20]}],"verseLabel":"الحجر: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿وَجَعَلْنَا لَكُمْ فِيهَا مَعَايِشَ﴾ وقدّم ﴿لكم﴾؟","answer":"يفيد التقديم تأكيد اختصاص المعايش بهم على سبيل القصر الإضافي، فيزيد تذكيرهم بفضل الله وامتنانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص368، تحت «فائدة تقديم لكم»","url":""}]},{"id":"s15-53","number":53,"surah":15,"verses":[20],"references":[{"surah":15,"verses":[20]}],"verseLabel":"الحجر: 20","question":"من المقصود بـ﴿وَمَنْ لَسْتُمْ لَهُ بِرَازِقِينَ﴾؟","answer":"يدخل فيه العيال والخدم والدواب ونحوهم؛ فرزقهم في الحقيقة من الله، والناس أسباب في إيصال الرزق إليهم. واستعمال «من» يغلب جانب العقلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص370، تحت «فائدة التعبير بمن»","url":""}]},{"id":"s15-54","number":54,"surah":15,"verses":[21],"references":[{"surah":15,"verses":[21]}],"verseLabel":"الحجر: 21","question":"ما بلاغة الحصر في قوله تعالى: ﴿وإن من شيء إلا عندنا خزائنه﴾؟","answer":"يقصر ملك أصول النعم والقدرة عليها على الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص376، تحت «بلاغة الحصر وإن من شيء إلا عندنا خزائنه»","url":""}]},{"id":"s15-170","number":170,"surah":15,"verses":[21],"references":[{"surah":15,"verses":[21]}],"verseLabel":"الحجر: 21","question":"ما نكتة التعبير بلفظ ﴿خزائنه﴾؟","answer":"يصوّر وفرة ما عند الله وسهولة إخراجه وإمداد الخلق به متى شاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص377، تحت «نكتة التعبير بلفظ خزائنه»","url":""}]},{"id":"s15-55","number":55,"surah":15,"verses":[21],"references":[{"surah":15,"verses":[21]}],"verseLabel":"الحجر: 21","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿وما ننزله﴾؟","answer":"صُوّر الإيجاد والإمداد بإنزال العطاء من خزائن الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص379، تحت «بلاغة الاستعارة في ننزله»","url":""}]},{"id":"s15-171","number":171,"surah":15,"verses":[21],"references":[{"surah":15,"verses":[21]}],"verseLabel":"الحجر: 21","question":"ما دلالة وصف القدر بأنه ﴿معلوم﴾؟","answer":"يبين أن العطاء مقدر بعلم الله وحكمته، لا عن عجز ولا جزاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص381، تحت «دلالة الصفة معلوم»","url":""}]},{"id":"s15-56","number":56,"surah":15,"verses":[22],"references":[{"surah":15,"verses":[22]}],"verseLabel":"الحجر: 22","question":"ما دلالة وصف الرياح بـ﴿لَوَاقِحَ﴾؟","answer":"تحتمل «لواقح» أنها حوامل للسحاب، تشبيهًا بالناقة الحامل، أو أنها تُلقح السحاب والشجر؛ فتجمع الصورة بين الحمل والإثمار وأسباب النماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص385، 386، تحت «بلاغة قوله وأرسلنا الرياح لواقح بين التشبيه والمجاز»","url":""}]},{"id":"s15-57","number":57,"surah":15,"verses":[22],"references":[{"surah":15,"verses":[22]}],"verseLabel":"الحجر: 22","question":"ما سرّ التعبير بـ﴿فَأَسْقَيْنَاكُمُوهُ﴾ بدل «فسقيناكم»؟","answer":"«أسقيناكم» تفيد أن الله جعل الماء مُعَدًّا لهم ومكّنهم من تناوله متى أرادوا؛ فهي أوسع من مجرد إعطائهم شربة ترويهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص387، 388، تحت «نكتة التعبير بلفظ فأسقيناكموه»","url":""}]},{"id":"s15-58","number":58,"surah":15,"verses":[23],"references":[{"surah":15,"verses":[23]}],"verseLabel":"الحجر: 23","question":"ما دلالة الحصر في وإنا لنحن نحيي ونميت في قوله تعالى: ﴿وَإِنَّا لَنَحْنُ نُحْيِي وَنُمِيتُ﴾؟","answer":"تأكيد الخبر وتقوية إسناده إلى الله يقرران اختصاصه بالإحياء والإماتة، ويردان إنكار البعث؛ فمن أوجد الحياة قادر على إعادتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص393، تحت «دلالة الحصر في وإنا لنحن نحيي ونميت»","url":""}]},{"id":"s15-59","number":59,"surah":15,"verses":[23],"references":[{"surah":15,"verses":[23]}],"verseLabel":"الحجر: 23","question":"ما سرّ حذف مفعولي ﴿نُحْيِي وَنُمِيتُ﴾؟","answer":"ترك المفعول يوجه العناية إلى أصل الفعلين واختصاص الله بهما، لا إلى إحياء أشخاص معينين أو إماتتهم؛ فالمقصود إثبات القدرة والتوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص394، تحت «سبب حذف المفعول في نحيي ونميت»","url":""}]},{"id":"s15-60","number":60,"surah":15,"verses":[24],"references":[{"surah":15,"verses":[24]}],"verseLabel":"الحجر: 24","question":"ما فائدة تكرار ﴿ولقد علمنا﴾ مع المستقدمين والمستأخرين؟","answer":"يؤكد التكرار إحاطة علم الله بكل من مضى ومن لم يأت بعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص400، تحت «فائدة التكرار في ولقد علمنا»","url":""}]},{"id":"s15-172","number":172,"surah":15,"verses":[24],"references":[{"surah":15,"verses":[24]}],"verseLabel":"الحجر: 24","question":"ما فائدة التعريف في ﴿المستقدمين﴾ و﴿المستأخرين﴾؟","answer":"يفيد استغراق جميع المتقدمين والمتأخرين في الوجود والأعمال، فلا يخرج أحد عن علم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص401، تحت «فائدة التعريف بال في الآية»","url":""}]},{"id":"s15-61","number":61,"surah":15,"verses":[25],"references":[{"surah":15,"verses":[25]}],"verseLabel":"الحجر: 25","question":"ما دلالة الحصر في قوله تعالى: ﴿إِنَّ رَبَّكَ هُوَ يَحْشُرُهُمْ﴾؟","answer":"«إنّ» تؤكد وقوع الحشر، وتقوية إسناده في ﴿هُوَ يَحْشُرُهُمْ﴾ تفيد اختصاص الله به؛ فهو وحده يجمعهم ويعيدهم، مهما كثروا وتفرقت أجزاؤهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص405، تحت «دلالة الحصر»","url":""}]},{"id":"s15-62","number":62,"surah":15,"verses":[25],"references":[{"surah":15,"verses":[25]}],"verseLabel":"الحجر: 25","question":"ما سرّ تقديم ﴿حَكِيمٌ﴾ على ﴿عَلِيمٌ﴾؟","answer":"قُدّمت الحكمة لأن الحشر والجزاء مما تقتضيه الحكمة؛ ثم جاء العلم لإفادة إحاطته بمن يحشرهم وأعمالهم، فيكون الجزاء على علم تام.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص407، تحت «نكتة الترتيب في حكيم عليم»","url":""}]},{"id":"s15-63","number":63,"surah":15,"verses":[26,27],"references":[{"surah":15,"verses":[26,27]}],"verseLabel":"الحجر: 26-27","question":"ما دلالة ذكر أصل الإنسان ثم أصل الجان في هذا السياق؟","answer":"يبين اختلاف أصلي الإنسان والجان كمال القدرة على تنويع الخلق مع وحدة الخالق، ويمهد لذكر ما جرى بين آدم وإبليس من عداوة؛ فلا يكون اختلاف المادة حجة للاستكبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص415، تحت «بلاغة العطف في الآية»","url":""}]},{"id":"s15-64","number":64,"surah":15,"verses":[29],"references":[{"surah":15,"verses":[29]}],"verseLabel":"الحجر: 29","question":"ما سرّ التعبير في قوله تعالى: ﴿فَقَعُوا لَهُ سَاجِدِينَ﴾ لا اسجدوا فقط؟","answer":"يصوّر الفعل مبادرتهم إلى السجود وسهولة انقيادهم للأمر، حتى كأنهم هووا إليه من غير تردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص427، تحت «نكتة التعبير بقوله فقعوا»","url":""}]},{"id":"s15-65","number":65,"surah":15,"verses":[30],"references":[{"surah":15,"verses":[30]}],"verseLabel":"الحجر: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿فَسَجَدَ الْمَلَائِكَةُ كُلُّهُمْ أَجْمَعُونَ﴾ وجمع مؤكدين؟","answer":"«كلهم» تؤكد شمول السجود لجميع الملائكة. و«أجمعون» تزيد التأكيد، وقيل: تفيد أيضًا اجتماعهم فيه دون تخلف؛ والفاء تُشعر بالمبادرة إلى الامتثال.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص431، تحت «سر اقتران أجمعون بكلهم»","url":""}]},{"id":"s15-66","number":66,"surah":15,"verses":[32],"references":[{"surah":15,"verses":[32]}],"verseLabel":"الحجر: 32","question":"لماذا جاء الاستفهام: ﴿مَا لَكَ أَلَّا تَكُونَ مَعَ السَّاجِدِينَ﴾؟","answer":"الاستفهام للإنكار والتوبيخ، لا لطلب علم؛ فينفي أن يكون له عذر في الامتناع، ويستخرج ما أضمره من استكبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص436، تحت «بلاغة الاستفهام المجازي في الآية»","url":""}]},{"id":"s15-67","number":67,"surah":15,"verses":[33],"references":[{"surah":15,"verses":[33]}],"verseLabel":"الحجر: 33","question":"ما سرّ التعبير في قول إبليس: ﴿لَمْ أَكُنْ لِأَسْجُدَ﴾؟","answer":"لام الجحود تؤكد نفي السجود؛ فكأنه يزعم أن السجود لآدم لا يليق به ولا يمكن أن يصدر منه، وفي ذلك كشف لاستكباره.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص441، 442، تحت «فائدة اللام في قوله لأسجد»","url":""}]},{"id":"s15-68","number":68,"surah":15,"verses":[34],"references":[{"surah":15,"verses":[34]}],"verseLabel":"الحجر: 34","question":"ما دلالة الفاء في ﴿فَاخْرُجْ مِنْهَا﴾؟","answer":"رتبت الفاء الأمر بالخروج على ما أظهره إبليس من عصيان واستكبار؛ فصار الطرد جزاءً لذلك القول والموقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص446، تحت «فائدة الفاء في قوله فاخرج منها»","url":""}]},{"id":"s15-69","number":69,"surah":15,"verses":[34],"references":[{"surah":15,"verses":[34]}],"verseLabel":"الحجر: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿رَجِيمٌ﴾ لا مطرود؟","answer":"«رجيم» بمعنى مرجوم، وهو كناية عن طرد مقرون بالتحقير والإهانة، فيبلغ في تصوير إبعاده مبلغًا لا يؤديه مجرد لفظ الطرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص448، تحت «بلاغة الكناية في قوله رجيم»","url":""}]},{"id":"s15-70","number":70,"surah":15,"verses":[35],"references":[{"surah":15,"verses":[35]}],"verseLabel":"الحجر: 35","question":"ما سرّ تقديم ﴿عَلَيْكَ﴾ في ﴿وَإِنَّ عَلَيْكَ اللَّعْنَةَ﴾؟","answer":"يفيد التقديم تخصيصه بهذه اللعنة وتأكيد وقوعها عليه؛ فيشتد بيان إبعاده جزاء عصيانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص451، تحت «بلاغة تقديم عليك»","url":""}]},{"id":"s15-71","number":71,"surah":15,"verses":[36],"references":[{"surah":15,"verses":[36]}],"verseLabel":"الحجر: 36","question":"ما مناسبة تحديد الإنظار في الآية في قوله تعالى: ﴿إِلَى يَوْمِ يُبْعَثُونَ﴾؟","answer":"طلب إبليس التأخير إلى يوم البعث طمعًا في أن يفلت من الموت، وأن يتسع له زمن إغواء بني آدم؛ فجاء تحديده كاشفًا لغرضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص458، تحت «مناسبة تحديد الإنظار في الآية»","url":""}]},{"id":"s15-72","number":72,"surah":15,"verses":[37,38],"references":[{"surah":15,"verses":[37,38]}],"verseLabel":"الحجر: 37-38","question":"ما سرّ التعبير بقوله تعالى: ﴿مِنَ الْمُنْظَرِينَ إِلَى يَوْمِ الْوَقْتِ الْمَعْلُومِ﴾؟","answer":"لم يترك إنظاره مطلقًا؛ بل قُيّد بأجل معلوم عند الله. ومن تفسيراته وقت النفخة الأولى، لا يوم البعث الذي طلبه، فلا يخرج إبليس عن الموت والقضاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص461، تحت «دلالة تقييد الإنظار في الآية»","url":""}]},{"id":"s15-73","number":73,"surah":15,"verses":[39],"references":[{"surah":15,"verses":[39]}],"verseLabel":"الحجر: 39","question":"ما سرّ التعبير في قول إبليس: ﴿بِمَا أَغْوَيْتَنِي﴾؟","answer":"التعبير بالإغواء يشعر بانغماس إبليس في الباطل وفساده فسادًا لا يُرجى معه صلاحه؛ وفيه تنبيه لبني آدم من وسوسته، إذ لا يرى سوى الباطل ولا يأمر إلا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص468، تحت «نكتة التعبير بلفظ أغويتني»","url":""}]},{"id":"s15-74","number":74,"surah":15,"verses":[39],"references":[{"surah":15,"verses":[39]}],"verseLabel":"الحجر: 39","question":"ما بلاغة حذف مفعول ﴿لأزينن﴾؟","answer":"يعم الحذف كل ما يزينه إبليس لبني آدم من الباطل والمعاصي.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص469، تحت «بلاغة حذف مفعول لأزينن»","url":""}]},{"id":"s15-173","number":173,"surah":15,"verses":[39],"references":[{"surah":15,"verses":[39]}],"verseLabel":"الحجر: 39","question":"ما دلالة الحال في قوله في الأرض؟","answer":"يقيد تزيين إبليس بزمن وجود بني آدم في الدنيا، دار متاعهم وابتلائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص469، تحت «دلالة الحال في قوله في الأرض»","url":""}]},{"id":"s15-75","number":75,"surah":15,"verses":[39],"references":[{"surah":15,"verses":[39]}],"verseLabel":"الحجر: 39","question":"ما سرّ إسناد الإغواء إلى إبليس في قوله: ﴿وَلَأُغْوِيَنَّهُمْ أَجْمَعِينَ﴾؟","answer":"الإسناد مجاز عقلي؛ أي لأحملنهم على الغواية وأتسبب فيها، وفيه تصوير شدة حرص إبليس واجتهاده في إضلال بني آدم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص470، تحت «بلاغة المجاز في قوله ولأغوينهم»","url":""}]},{"id":"s15-76","number":76,"surah":15,"verses":[40],"references":[{"surah":15,"verses":[40]},{"surah":38,"verses":[83]}],"verseLabel":"الحجر: 40؛ ص: 83","question":"ما دلالة استثناء ﴿عِبَادَكَ مِنْهُمُ الْمُخْلَصِينَ﴾ في الحجر وص؟","answer":"في الحجر: 40، استثنى من اختصهم الله بطاعته وحفظهم، إقرارًا بعجزه عن إغوائهم.\n\nوفي ص: 83، جاء الاستثناء احترازًا من كذب دعواه بإغواء الجميع؛ فالمخلَصون مصونون بعناية الله، وعلى قراءة كسر اللام هم الذين أخلصوا له دينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص474، تحت «نكتة التعبير بلفظ المخلصين»","url":""}]},{"id":"s15-77","number":77,"surah":15,"verses":[40],"references":[{"surah":15,"verses":[40]}],"verseLabel":"الحجر: 40","question":"ما سرّ تقديم ﴿مِنْهُمُ﴾ على ﴿الْمُخْلَصِينَ﴾؟","answer":"تقديم «منهم» يُبرز أن المخلصين من البشر الذين استهدفهم إبليس، وأن نجاتهم لخصوص إخلاصهم لله؛ وفي ذلك مزية لهم على سائر من يتبع إغواءه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص473، 474، تحت «بلاغة تقديم منهم في الآية»","url":""}]},{"id":"s15-78","number":78,"surah":15,"verses":[41],"references":[{"surah":15,"verses":[41]}],"verseLabel":"الحجر: 41","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿هذا صراط علي﴾؟","answer":"شُبّه الوعد بصيانة المخلصين بطريق ثابت، و﴿علي﴾ تفيد التزام هذا الوعد تفضلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص476، تحت «بلاغة الاستعارة في قوله هذا صراط علي»","url":""}]},{"id":"s15-174","number":174,"surah":15,"verses":[41],"references":[{"surah":15,"verses":[41]}],"verseLabel":"الحجر: 41","question":"ما فائدة وصف الصراط بأنه ﴿مستقيم﴾؟","answer":"يؤكد سلامته من الانحراف وثباته؛ فلا يستطيع إبليس صرف المخلصين عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص478، تحت «فائدة مجيء الصفة في قوله مستقيم»","url":""}]},{"id":"s15-79","number":79,"surah":15,"verses":[42],"references":[{"surah":15,"verses":[42]}],"verseLabel":"الحجر: 42","question":"ما فائدة إضافة العباد إلى الله في قوله: ﴿إن عبادي﴾؟","answer":"الإضافة تشريف لهم وإظهار لعناية الله وحفظه إياهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص483، تحت «فائدة الإضافة في قوله عبادي»","url":""}]},{"id":"s15-175","number":175,"surah":15,"verses":[42],"references":[{"surah":15,"verses":[42]}],"verseLabel":"الحجر: 42","question":"ما نكتة التعبير بلفظ ﴿سلطان﴾؟","answer":"ينفي عن إبليس الحجة والقهر؛ فلا يملك إجبارهم على العصيان وإنما يدعو ويزين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص484، تحت «نكتة التعبير بلفظ سلطان»","url":""}]},{"id":"s15-80","number":80,"surah":15,"verses":[42],"references":[{"surah":15,"verses":[42]}],"verseLabel":"الحجر: 42","question":"ما فائدة تقديم ﴿لك﴾ في قوله تعالى: ﴿ليس لك عليهم سلطان﴾؟","answer":"يؤكد نفي السلطان عن إبليس خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص483، تحت «فائدة تقديم لك»","url":""}]},{"id":"s15-176","number":176,"surah":15,"verses":[42],"references":[{"surah":15,"verses":[42]}],"verseLabel":"الحجر: 42","question":"ما فائدة تقديم ﴿عليهم﴾ على ﴿سلطان﴾؟","answer":"يخص عباد الله بهذا النفي، فتقوى دلالة الحماية والاختصاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص483، تحت «فائدة تقديم عليهم على سلطان»","url":""}]},{"id":"s15-81","number":81,"surah":15,"verses":[42],"references":[{"surah":15,"verses":[42]}],"verseLabel":"الحجر: 42","question":"ما سرّ التعبير في قوله تعالى: ﴿إِلَّا مَنِ اتَّبَعَكَ﴾ لا من أغويته؟","answer":"يظهر أن تسلطه عليهم ناشئ عن اتباعهم له باختيارهم، لا عن قهر يلجئهم إليه؛ فوسوسته لا تعفيهم من مسؤولية الاستجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص487، تحت «نكتة التعبير بلفظ اتبعك»","url":""}]},{"id":"s15-82","number":82,"surah":15,"verses":[43],"references":[{"surah":15,"verses":[43]}],"verseLabel":"الحجر: 43","question":"ما دلالة تسمية جهنم ﴿مَوْعِدَهُمْ﴾؟","answer":"سُمّيت جهنم موعدهم تهكمًا وتهديدًا، كأنهم بتتابعهم على الغواية قد تواعدوا على الاجتماع فيها؛ فصارت مكان لقائهم ومصيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص491، تحت «نكتة التعبير بلفظ لموعدهم»","url":""}]},{"id":"s15-83","number":83,"surah":15,"verses":[44],"references":[{"surah":15,"verses":[44]}],"verseLabel":"الحجر: 44","question":"ما سرّ التعبير بقوله لها سبعة أبواب؟","answer":"تعدد الأبواب يُشعر بكثرة الداخلين وتنوع مراتبهم في الغواية والعذاب؛ ولكل باب جماعة مخصوصة. وقيل: الأبواب كناية عن طبقاتها ودركاتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص495، تحت «سر التعبير بقوله لها سبعة أبواب»","url":""}]},{"id":"s15-84","number":84,"surah":15,"verses":[44],"references":[{"surah":15,"verses":[44]}],"verseLabel":"الحجر: 44","question":"ما النكتة البلاغية في التعبير بقوله جزء مقسوم؟","answer":"لكل باب جماعة متميزة من الغاوين، تجمعها حالها في الغواية وما تستحقه من العقاب؛ فالقسمة تُظهر اختلاف مراتب العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص497، 498، تحت «نكتة التعبير بقوله جزء مقسوم»","url":""}]},{"id":"s15-85","number":85,"surah":15,"verses":[45],"references":[{"surah":15,"verses":[45]}],"verseLabel":"الحجر: 45","question":"ما دلالة حذف متعلّق ﴿الْمُتَّقِينَ﴾؟","answer":"حذف المتعلق يعم ما ينبغي اتقاؤه من الشرك والفواحش وغواية الشيطان؛ فلا يحصر التقوى في اجتناب شيء واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص500، تحت «براعة حذف متعلق المتقين»","url":""}]},{"id":"s15-86","number":86,"surah":15,"verses":[45],"references":[{"surah":15,"verses":[45]}],"verseLabel":"الحجر: 45","question":"ما دلالة جمع ﴿جنات وعيون﴾؟","answer":"يشعر الجمع بكثرة الجنات والعيون وتنوع النعيم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص502، تحت «فائدة الجمع في قوله جنات وعيون»","url":""}]},{"id":"s15-177","number":177,"surah":15,"verses":[45],"references":[{"surah":15,"verses":[45]}],"verseLabel":"الحجر: 45","question":"ما دلالة تنكير ﴿جنات وعيون﴾؟","answer":"يعظم شأنها؛ فهي جنات وعيون لا يشبه نعيمها ما عرفه الناس في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص502، تحت «فائدة التنكير في قوله جنات وعيون»","url":""}]},{"id":"s15-87","number":87,"surah":15,"verses":[46],"references":[{"surah":15,"verses":[46]}],"verseLabel":"الحجر: 46","question":"ما دلالة الحال في قوله بسلام؟","answer":"يفيد الدخول مصحوبًا بالسلامة من الآفات والمنغصات.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص506، تحت «دلالة الحال في قوله بسلام»","url":""}]},{"id":"s15-178","number":178,"surah":15,"verses":[46],"references":[{"surah":15,"verses":[46]}],"verseLabel":"الحجر: 46","question":"ما بلاغة التعبير بلفظ ﴿آمنين﴾؟","answer":"يفيد الأمن من الخروج وزوال النعيم، فيطمئنون إلى دوام بقائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص506، تحت «براعة التعبير بلفظ آمنين»","url":""}]},{"id":"s15-88","number":88,"surah":15,"verses":[47],"references":[{"surah":15,"verses":[47]}],"verseLabel":"الحجر: 47","question":"ما النكتة البلاغية في التعبير بلفظ ونزعنا في قوله تعالى: ﴿وَنَزَعْنَا مَا فِي صُدُورِهِمْ مِنْ غِلٍّ﴾؟","answer":"نُسب النزع إلى الله لإفادة سهولته بقدرته؛ فيُزال الغل من صدور المؤمنين من غير مشقة عليهم، وتصفو نفوسهم من الضغائن.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص511، تحت «نكتة التعبير بلفظ ونزعنا»","url":""}]},{"id":"s15-89","number":89,"surah":15,"verses":[47],"references":[{"surah":15,"verses":[47]}],"verseLabel":"الحجر: 47","question":"ما سرّ زيادة ﴿إِخْوَانًا﴾ بعد نزع الغل في الحجر، دون نظيرها في الأعراف؟","answer":"في الحجر يُفصّل السياق أحوال اجتماع أهل الجنة ودوام صفائهم، فناسب ذكر أخوتهم بعد نزع الغل. أما الأعراف فيذكر نعيمهم وشكرهم عند دخول الجنة دون هذا التفصيل لأحوال اجتماعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص515، 516، تحت «توجيه المتشابه اللفظي في الآية»","url":""}]},{"id":"s15-90","number":90,"surah":15,"verses":[47],"references":[{"surah":15,"verses":[47]}],"verseLabel":"الحجر: 47","question":"ما النكتة البلاغية في التعبير بلفظ متقابلين في قوله تعالى: ﴿عَلَى سُرُرٍ مُتَقَابِلِينَ﴾؟","answer":"التقابل يصور صفاء اجتماعهم وأنس بعضهم ببعض؛ فلا استدبار ولا تقاطع، بل وجوه متواجهة وقلوب متصافية.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص515، تحت «نكتة التعبير بلفظ متقابلين»","url":""}]},{"id":"s15-91","number":91,"surah":15,"verses":[48],"references":[{"surah":15,"verses":[48]}],"verseLabel":"الحجر: 48","question":"ما وجه البلاغة في الكناية في قوله لا يمسهم؟","answer":"المس أدنى الإصابة، فنفيه يدل على انتفاء أقل تعب عنهم، فضلًا عما فوقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص520، تحت «بلاغة الكناية في قوله لا يمسهم»","url":""}]},{"id":"s15-92","number":92,"surah":15,"verses":[48],"references":[{"surah":15,"verses":[48]}],"verseLabel":"الحجر: 48","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا هُمْ مِنْهَا بِمُخْرَجِينَ﴾ لا «خالدون» فقط؟","answer":"نفي الإخراج ينفي كل احتمال لانقطاع النعيم، والبناء للمفعول يشعر بأن أحدًا لا يستطيع إخراجهم؛ فيتم أمنهم وخلودهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص522، تحت «نكتة الإخبار بقوله بمخرجين»","url":""}]},{"id":"s15-93","number":93,"surah":15,"verses":[49],"references":[{"surah":15,"verses":[49]}],"verseLabel":"الحجر: 49","question":"ما سرّ التعبير في قوله تعالى: ﴿نَبِّئْ عِبَادِي﴾ لا أخبرهم؟","answer":"النبأ خبر عظيم الفائدة والشأن، وصيغة التفعيل تزيد تأكيده وتقريره؛ فيُطلب تلقي خبر المغفرة والرحمة بعناية.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص526، تحت «سبب إيثار التعبير بلفظ نبئ»","url":""}]},{"id":"s15-94","number":94,"surah":15,"verses":[49],"references":[{"surah":15,"verses":[49]}],"verseLabel":"الحجر: 49","question":"ما دلالة إضافة العباد إلى الله في ﴿نَبِّئْ عِبَادِي﴾؟","answer":"إضافتهم إلى الله تشرفهم وترفع شأنهم، وتمهد لتلقي بشارة مغفرته ورحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص527، تحت «فائدة الإضافة في قوله عبادي»","url":""}]},{"id":"s15-95","number":95,"surah":15,"verses":[49],"references":[{"surah":15,"verses":[49]}],"verseLabel":"الحجر: 49","question":"ما دلالة الجمع بين ﴿الْغَفُورُ الرَّحِيمُ﴾؟","answer":"المغفرة ستر الذنب، والرحمة أوسع وتشمل العناية بعباده؛ والإنسان لا ينفك عن الحاجة إليهما، فجمع الوصفان البشارة بستر تقصيره وإحسان الله إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص529، تحت «بلاغة ذكر الوصفين الغفور الرحيم»","url":""}]},{"id":"s15-96","number":96,"surah":15,"verses":[50],"references":[{"surah":15,"verses":[50]}],"verseLabel":"الحجر: 50","question":"ما فائدة الضمير هو في قوله تعالى: ﴿وَأَنَّ عَذَابِي هُوَ الْعَذَابُ الْأَلِيمُ﴾؟","answer":"الضمير وتعريف «العذاب» يؤكدان اختصاص عذابه بكمال الإيلام؛ فيقترن الوعد بالمغفرة والرحمة بالتحذير من العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص531، تحت «فائدة الضمير هو»","url":""}]},{"id":"s15-97","number":97,"surah":15,"verses":[51],"references":[{"surah":15,"verses":[51]}],"verseLabel":"الحجر: 51","question":"ما فائدة الوصل بالواو في قوله ونبئهم؟","answer":"وصلت القصة بخبر المغفرة والعذاب لأنها تُري أثرهما: بشارة إبراهيم ونجاة لوط، ثم هلاك المكذبين؛ فيجتمع الاعتبار بالوعد والوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص535، تحت «فائدة الوصل بالواو في قوله ونبئهم»","url":""}]},{"id":"s15-98","number":98,"surah":15,"verses":[51],"references":[{"surah":15,"verses":[51]}],"verseLabel":"الحجر: 51","question":"ما سرّ إفراد ﴿ضَيْفِ﴾ مع أن ضيوف إبراهيم جماعة؟","answer":"«ضيف» اسم جنس يستوي فيه القليل والكثير، فجاء مفردًا مع أنهم جماعة؛ وحق الضيافة يثبت للجمع وللفرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص537، تحت «فائدة اسم الجنس الإفرادي الضيف»","url":""}]},{"id":"s15-99","number":99,"surah":15,"verses":[52],"references":[{"surah":15,"verses":[52]}],"verseLabel":"الحجر: 52","question":"ما سرّ التعبير في قول إبراهيم: ﴿إِنَّا مِنْكُمْ وَجِلُونَ﴾؟","answer":"الوجل خوف واضطراب في النفس من أمر تتوقعه؛ فاختير اللفظ لتصوير ما استشعره إبراهيم من ضيوفه حين لم يتناولوا الطعام، كما تفصله نظائر القصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص542، تحت «نكتة التعبير بلفظ وجلون»","url":""}]},{"id":"s15-100","number":100,"surah":15,"verses":[53],"references":[{"surah":15,"verses":[53]}],"verseLabel":"الحجر: 53","question":"ما سرّ التعبير في قول الملائكة: ﴿لَا تَوْجَلْ﴾ مع حذف سبب الوجل؟","answer":"حذف المتعلق يعم النهي عن الخوف من أي شيء، فيتم تسكين قلبه قبل البشارة؛ وليس المقصود نفي سبب واحد للوجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص549، تحت «سر حذف متعلق الفعل لا توجل»","url":""}]},{"id":"s15-101","number":101,"surah":15,"verses":[54],"references":[{"surah":15,"verses":[54]}],"verseLabel":"الحجر: 54","question":"ما سرّ التعبير في قول إبراهيم: ﴿مَسَّنِيَ الْكِبَرُ﴾؟","answer":"صوّر الكبر كأنه شيء يمس الإنسان بأذاه، دلالة على ظهور أثره في القوة والحركة. وذكره إبراهيم تعجبًا من مجيء الولد بعد انقطاع أسبابه المعتادة، لا شكًا في قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص559، تحت «نكتة التعبير بلفظ مسني»","url":""}]},{"id":"s15-102","number":102,"surah":15,"verses":[56],"references":[{"surah":15,"verses":[56]}],"verseLabel":"الحجر: 56","question":"ما بلاغة الاستفهام في قوله تعالى: ﴿ومن يقنط من رحمة ربه﴾؟","answer":"هو استفهام إنكاري ينفي القنوط عن العارف بربه ويحصره في الضالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص571، تحت «بلاغة الاستفهام المجازي في الآية الكريمة»","url":""}]},{"id":"s15-179","number":179,"surah":15,"verses":[56],"references":[{"surah":15,"verses":[56]}],"verseLabel":"الحجر: 56","question":"لماذا قيل: ﴿من رحمة ربه﴾ لا من رحمة الله؟","answer":"إضافة الرحمة إلى الرب تستحضر عنايته وتربيته وإحسانه، فتقوي الرجاء فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص572، تحت «سبب إيثار التعبير بلفظ ربه»","url":""}]},{"id":"s15-103","number":103,"surah":15,"verses":[57],"references":[{"surah":15,"verses":[57]}],"verseLabel":"الحجر: 57","question":"ما نكتة التعبير بلفظ ﴿خطبكم﴾؟","answer":"الخطب شأن عظيم، فدل على أن إبراهيم أدرك أن وراء البشارة مهمة أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص577، تحت «نكتة التعبير بلفظ خطبكم»","url":""}]},{"id":"s15-180","number":180,"surah":15,"verses":[57],"references":[{"surah":15,"verses":[57]}],"verseLabel":"الحجر: 57","question":"ما سرّ حذف حرف النداء في قوله: ﴿أيها المرسلون﴾؟","answer":"حذفت ﴿يا﴾ لقربهم وحضورهم، ولأن المقام مقام إيجاز ومباشرة في السؤال.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص578، تحت «سر حذف حرف النداء في السياق»","url":""}]},{"id":"s15-104","number":104,"surah":15,"verses":[59],"references":[{"surah":15,"verses":[59]}],"verseLabel":"الحجر: 59","question":"ما دلالة استثناء ﴿آل لوط﴾ من القوم المجرمين؟","answer":"أخرج الاستثناء آل لوط المؤمنين من حكم الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص584، تحت «دلالة الاستثناء في قوله إلا آل لوط»","url":""}]},{"id":"s15-181","number":181,"surah":15,"verses":[59],"references":[{"surah":15,"verses":[59]}],"verseLabel":"الحجر: 59","question":"ما وجه البلاغة في جملة الاستئناف في الآية في قوله تعالى: ﴿إنا لمنجوهم أجمعين﴾؟","answer":"أكدت الجملة شمول النجاة لجميع آل لوط بعد استثنائهم من القوم المجرمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص584، تحت «بلاغة جملة الاستئناف في الآية»","url":""}]},{"id":"s15-105","number":105,"surah":15,"verses":[60],"references":[{"surah":15,"verses":[60]}],"verseLabel":"الحجر: 60","question":"ما نكتة التعبير عن امرأة لوط بأنها ﴿من الغابرين﴾؟","answer":"الغابرون الباقون؛ فهي باقية مع المجرمين للهلاك لا للنجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص588، تحت «نكتة التعبير بقوله لمن الغابرين»","url":""}]},{"id":"s15-182","number":182,"surah":15,"verses":[60],"references":[{"surah":15,"verses":[60]}],"verseLabel":"الحجر: 60","question":"ما فائدة حذف متعلق ﴿الغابرين﴾؟","answer":"يجمع الحذف بقاءها مع المجرمين وتخلفها عن الخروج مع لوط.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص589، تحت «فائدة حذف متعلق الغابرين»","url":""}]},{"id":"s15-106","number":106,"surah":15,"verses":[61,62,63],"references":[{"surah":15,"verses":[61,62,63]}],"verseLabel":"الحجر: 61-63","question":"ما فائدة ﴿بل﴾ في قول الملائكة: ﴿بل جئناك﴾؟","answer":"أبطلت موجب خوف لوط ونقلت الكلام إلى حقيقة مجيئهم بالعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص600، تحت «فائدة التعبير ببل»","url":""}]},{"id":"s15-183","number":183,"surah":15,"verses":[61,62,63],"references":[{"surah":15,"verses":[61,62,63]}],"verseLabel":"الحجر: 61-63","question":"ما نكتة التعبير بـ﴿يمترون﴾؟","answer":"يشعر اللفظ بتكلف طلب الشك بعد ظهور الدليل، فيكشف عناد قوم لوط.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص603، تحت «نكتة التعبير بلفظ يمترون»","url":""}]},{"id":"s15-107","number":107,"surah":15,"verses":[63],"references":[{"surah":15,"verses":[63]}],"verseLabel":"الحجر: 63","question":"ما سرّ تقديم ﴿فِيهِ﴾ على ﴿يَمْتَرُونَ﴾؟","answer":"التقديم يؤكد تعلق امترائهم بالعذاب الموعود، ويبرز عظم ما شكوا فيه، مع مراعاة الفاصلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص602، تحت «بلاغة تقديم فيه على يمترون»","url":""}]},{"id":"s15-108","number":108,"surah":15,"verses":[65],"references":[{"surah":15,"verses":[65]}],"verseLabel":"الحجر: 65","question":"ما سرّ حذف متعلَّق ﴿تُؤْمَرُونَ﴾ في قوله تعالى: ﴿وَامْضُوا حَيْثُ تُؤْمَرُونَ﴾؟","answer":"التقدير: «حيث تؤمرون بالمضي إليه» أو «تؤمرون به»؛ وحذف المتعلَّق يفيد اتصافهم بالائتمار والامتثال لأي أمر يأتيهم من الله تعالى.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص615، 616، تحت «بلاغة الحذف في قوله تؤمرون»","url":""}]},{"id":"s15-109","number":109,"surah":15,"verses":[66],"references":[{"surah":15,"verses":[66]}],"verseLabel":"الحجر: 66","question":"ما سرّ تقديم ﴿إِلَيْهِ﴾ في قوله تعالى: ﴿وَقَضَيْنَا إِلَيْهِ ذَلِكَ الْأَمْرَ﴾؟","answer":"تقديم الجار والمجرور يفيد تخصيص لوط عليه السلام بإخباره باستئصال قومه، اهتمامًا بشأنه ورعايةً لحق الرسالة، وليتهيأ هو وأتباعه للخروج.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص621، تحت «بلاغة تقديم إليه على ذلك الأمر»","url":""}]},{"id":"s15-110","number":110,"surah":15,"verses":[66],"references":[{"surah":15,"verses":[66]}],"verseLabel":"الحجر: 66","question":"ما سرّ التعبير في قوله تعالى: ﴿مَقْطُوعٌ﴾ لا هالك؟","answer":"قطع الدابر كناية عن استئصال القوم حتى لا يبقى أحد يتبعهم؛ و«مقطوع» تعرض هذا الاستئصال كأمر محقق الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص623، تحت «نكتة التعبير بصيغة مقطوع»","url":""}]},{"id":"s15-111","number":111,"surah":15,"verses":[68],"references":[{"surah":15,"verses":[68]}],"verseLabel":"الحجر: 68","question":"ما سرّ التعبير في قول لوط: ﴿إِنَّ هَؤُلَاءِ ضَيْفِي﴾ باسم الإشارة؟","answer":"الإشارة إلى الضيوف القريبين تُظهر عناية لوط بهم، وتعرّفهم لقومه تعريفًا يستدعي إكرامهم وصيانتهم؛ فهم حاضرون في ضيافته وحمايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص629، تحت «دلالة التعبير باسم الإشارة هؤلاء»","url":""}]},{"id":"s15-112","number":112,"surah":15,"verses":[72],"references":[{"surah":15,"verses":[72]}],"verseLabel":"الحجر: 72","question":"ما دلالة القسم بـ﴿لَعَمْرُكَ﴾؟","answer":"على قول جمهور المفسرين إن الخطاب للنبي محمد ﷺ، ففي القسم بحياته تشريف عظيم له، وتأكيد لما أخبر به عن ضلال المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص646، تحت «بلاغة صيغة جملة القسم لعمرك»","url":""}]},{"id":"s15-113","number":113,"surah":15,"verses":[72],"references":[{"surah":15,"verses":[72]}],"verseLabel":"الحجر: 72","question":"ما سرّ فتح العين في ﴿لَعَمْرُكَ﴾ في القسم؟","answer":"اختير الفتح في القسم لأنه أخف، ولأن هذا التعبير كثير الدوران على الألسنة؛ فناسبت كثرة استعماله خفة لفظه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص647، تحت «وجه اختصاص لعمرك دون عمرك بالقسم»","url":""}]},{"id":"s15-114","number":114,"surah":15,"verses":[72],"references":[{"surah":15,"verses":[72]}],"verseLabel":"الحجر: 72","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿في سكرتهم﴾؟","answer":"شُبّه ضلالهم وغلبة شهواتهم بسكر يحجب العقل عن التمييز.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص648، تحت «بلاغة الاستعارة التصريحية في لفظ سكرتهم»","url":""}]},{"id":"s15-184","number":184,"surah":15,"verses":[72],"references":[{"surah":15,"verses":[72]}],"verseLabel":"الحجر: 72","question":"ما بلاغة التعبير بـ﴿يعمهون﴾؟","answer":"يصور حيرتهم وترددهم كمن عميت بصيرته فلم يعرف وجه الصواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص649، تحت «بلاغة المجاز في لفظ يعمهون»","url":""}]},{"id":"s15-115","number":115,"surah":15,"verses":[72],"references":[{"surah":15,"verses":[72]}],"verseLabel":"الحجر: 72","question":"ما دلالة إفراد ﴿سَكْرَتِهِمْ﴾ مع تعددهم؟","answer":"قوبل جمعهم بسكرة واحدة، للدلالة على اتحاد سبب ضلالهم واشتراكهم في حال تحجبهم عن الهدى، فكأن العقل الغائب واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص649، تحت «نكتة إفراد سكرتهم دون جمعها في السياق»","url":""}]},{"id":"s15-116","number":116,"surah":15,"verses":[73],"references":[{"surah":15,"verses":[73]}],"verseLabel":"الحجر: 73","question":"ما وجه البلاغة في الإخبار بالحال مشرقين دون الظرف في قوله تعالى: ﴿فَأَخَذَتْهُمُ الصَّيْحَةُ مُشْرِقِينَ﴾؟","answer":"جاءت «مشرقين» حالًا لتصور هيئتهم حين أدركهم العذاب في ضوء النهار، يشاهدون شدته؛ فزاد ذلك هول المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص654، تحت «بلاغة الإخبار بالحال مشرقين دون الظرف»","url":""}]},{"id":"s15-117","number":117,"surah":15,"verses":[74],"references":[{"surah":15,"verses":[74]}],"verseLabel":"الحجر: 74","question":"لماذا قيل: ﴿فجعلنا﴾ لا «فقلبنا»؟","answer":"يبرز ﴿جعلنا﴾ تحول هيئة المدينة إلى ضدها وتمام وقوع التغيير.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص656، تحت «سر اختيار لفظ فجعلنا دون قلبنا»","url":""}]},{"id":"s15-185","number":185,"surah":15,"verses":[74],"references":[{"surah":15,"verses":[74]}],"verseLabel":"الحجر: 74","question":"ما وجه البلاغة في التعبير بجعل العالي سافلا لا العكس في قوله تعالى: ﴿عاليها سافلها﴾؟","answer":"يصوّر قلب المدينة وإهلاك ما عليها، فيرى السامع أثر الانقلاب وهوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص657، تحت «بلاغة التعبير بجعل العالي سافلا لا العكس»","url":""}]},{"id":"s15-118","number":118,"surah":15,"verses":[74],"references":[{"surah":15,"verses":[74]}],"verseLabel":"الحجر: 74","question":"ما سرّ ﴿وَأَمْطَرْنَا عَلَيْهِمْ﴾ في الحجر، و﴿وَأَمْطَرْنَا عَلَيْهَا﴾ في هود؟","answer":"في الحجر عاد الضمير إلى القوم المجرمين، فالتصريح بإمطارهم أبلغ في زجرهم وبيان استئصالهم. وفي هود عاد الضمير في ﴿عَلَيْهَا﴾ إلى المدينة التي جرى ذكر قلبها، فناسب كل ضمير سياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص659، 660، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s15-119","number":119,"surah":15,"verses":[74],"references":[{"surah":15,"verses":[74]}],"verseLabel":"الحجر: 74","question":"ما سرّ تقديم ﴿عَلَيْهِمْ﴾ على ﴿حِجَارَةً﴾؟","answer":"يفيد التقديم تخصيصهم بإصابة الحجارة وتأكيده؛ فلا يصيب هذا العذاب لوطًا وأهله الناجين، ويبرز الاهتمام بعقوبة الهالكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص659، تحت «دلالة تقديم عليهم على حجارة»","url":""}]},{"id":"s15-120","number":120,"surah":15,"verses":[74],"references":[{"surah":15,"verses":[74]}],"verseLabel":"الحجر: 74","question":"ما معنى ﴿من﴾ في قوله تعالى: ﴿من سجيل﴾؟","answer":"تبين ﴿من﴾ جنس الحجارة التي أمطرت على القوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص661، تحت «معنى من في قوله من سجيل»","url":""}]},{"id":"s15-186","number":186,"surah":15,"verses":[74],"references":[{"surah":15,"verses":[74]}],"verseLabel":"الحجر: 74","question":"ما نكتة التعبير بلفظ ﴿سجيل﴾؟","answer":"السجيل طين اشتد وتصلب، فيصور قوة حجارة العذاب وصلابتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص661، تحت «نكتة التعبير بلفظ سجيل في البيان الجليل»","url":""}]},{"id":"s15-121","number":121,"surah":15,"verses":[75],"references":[{"surah":15,"verses":[75]}],"verseLabel":"الحجر: 75","question":"ما سرّ التعبير في قوله تعالى: ﴿لَآيَاتٍ لِلْمُتَوَسِّمِينَ﴾ بالجمع؟","answer":"جُمعت الآيات لتعدد وجوه العبرة في القصة: مجيء الضيف والبشارة وإنجاء المؤمنين وإهلاك المكذبين وقلب المدينة وإمطار الحجارة؛ فكل واحدة منها آية للناظر المتأمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص664، تحت «نكتة جمع الآيات دون إفرادها»","url":""}]},{"id":"s15-122","number":122,"surah":15,"verses":[75],"references":[{"surah":15,"verses":[75]}],"verseLabel":"الحجر: 75","question":"ما النكتة البلاغية في التعبير بلفظ للمتوسمين في قوله تعالى: ﴿لِلْمُتَوَسِّمِينَ﴾؟","answer":"المتوسمون يستدلون بالعلامات الظاهرة على حقائق الأمور؛ فلا يقفون عند مشاهدة الآثار، بل يعتبرون بسبب هلاك المكذبين ونجاة المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص665، تحت «نكتة التعبير بلفظ للمتوسمين»","url":""}]},{"id":"s15-123","number":123,"surah":15,"verses":[76],"references":[{"surah":15,"verses":[76]}],"verseLabel":"الحجر: 76","question":"ما دلالة اختيار مفردة مقيم في قوله تعالى: ﴿وَإِنَّهَا لَبِسَبِيلٍ مُقِيمٍ﴾؟","answer":"«مقيم» يصور الطريق ثابتًا معروفًا لا ينقطع سلوك الناس له؛ فآثار القرية في طريق يمرون به، والعبرة قريبة من أعينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص669، تحت «دلالة اختيار مفردة مقيم»","url":""}]},{"id":"s15-124","number":124,"surah":15,"verses":[78],"references":[{"surah":15,"verses":[78]}],"verseLabel":"الحجر: 78","question":"ما سرّ إيثار لفظ الظلم دون الكفر في قوله تعالى: ﴿وَإِنْ كَانَ أَصْحَابُ الْأَيْكَةِ لَظَالِمِينَ﴾؟","answer":"وصفهم بالظلم يكشف تجاوزهم الحق ووضعهم نعم الله في غير مواضعها؛ ويدخل فيه كفرهم وشركهم، وهو أعظم الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص679، تحت «سر إيثار لفظ الظلم دون الكفر»","url":""}]},{"id":"s15-126","number":126,"surah":15,"verses":[80],"references":[{"surah":15,"verses":[80]}],"verseLabel":"الحجر: 80","question":"ما سرّ تسميتهم ﴿أَصْحَابُ الْحِجْرِ﴾ هنا دون «ثمود»؟","answer":"نسبوا إلى موضعهم المحاط بالحجارة، وفي الاسم استحضار قوتهم وتحصنهم ونحتهم البيوت في الجبال؛ وهي أسباب لم تمنع عنهم العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص689، تحت «وجه تسمية القوم هنا بأصحاب الحجر دون ثمود»","url":""}]},{"id":"s15-127","number":127,"surah":15,"verses":[80],"references":[{"surah":15,"verses":[80]}],"verseLabel":"الحجر: 80","question":"ما سرّ التعبير في قوله تعالى: ﴿كَذَّبَتْ... الْمُرْسَلِينَ﴾ مع أن رسولهم واحد؟","answer":"لتوافق الرسل في أصل دعوتهم، كان تكذيب صالح تكذيبًا للجميع؛ ولفظ «المرسلين» يُشعر أيضًا بأن رد الرسول ردٌّ على من أرسله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص689، تحت «بلاغة التعبير في جمع المرسلين»","url":""}]},{"id":"s15-128","number":128,"surah":15,"verses":[81],"references":[{"surah":15,"verses":[81]}],"verseLabel":"الحجر: 81","question":"ما دلالة جمع ﴿آيَاتِنَا﴾ مع أن أشهر آيات ثمود الناقة؟","answer":"من توجيه الجمع أن الناقة الواحدة اشتملت على وجوه متعددة من الدلالة؛ فتنوع ما يشاهدونه من شأنها يجعلها آيات على قدرة الله وصدق رسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص693، تحت «نكتة جمع الآيات في قوله آياتنا»","url":""}]},{"id":"s15-129","number":129,"surah":15,"verses":[81],"references":[{"surah":15,"verses":[81]}],"verseLabel":"الحجر: 81","question":"ما النكتة البلاغية في التعبير بالإعراض عن الآيات في قوله تعالى: ﴿فَكَانُوا عَنْهَا مُعْرِضِينَ﴾؟","answer":"الإعراض يصور تولّيهم عن الآيات بعد وصولها إليهم، و«كانوا» مع وصف «معرضين» تدل على استمرار هذا الموقف ورسوخه حتى صار طبعًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص694، تحت «نكتة التعبير بالإعراض عن الآيات»","url":""}]},{"id":"s15-130","number":130,"surah":15,"verses":[82],"references":[{"surah":15,"verses":[82]}],"verseLabel":"الحجر: 82","question":"ما سرّ التعبير بتركيب وكانوا ينحتون في قوله تعالى: ﴿وَكَانُوا يَنْحِتُونَ﴾؟","answer":"«كانوا» مع المضارع تدل على استمرار النحت وعادتهم فيه؛ فتستحضر تمكنهم من هذه الصنعة واغترارهم بما أنشؤوه من بيوت قوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص697، تحت «سر التعبير بتركيب وكانوا ينحتون»","url":""}]},{"id":"s15-131","number":131,"surah":15,"verses":[82],"references":[{"surah":15,"verses":[82]}],"verseLabel":"الحجر: 82","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿يَنْحِتُونَ مِنَ الْجِبَالِ بُيُوتًا﴾، وفي الأعراف: ﴿تَنْحِتُونَ الْجِبَالَ بُيُوتًا﴾؟","answer":"في الحجر تحتمل «من» ابتداء النحت من الجبال أو التبعيض، والسياق يذكر تكذيبهم. أما الأعراف فسياق تعداد النعم، فناسبه العموم في ﴿تَنْحِتُونَ الْجِبَالَ﴾، وقد سبقه ﴿مِنْ سُهُولِهَا﴾ فاستُغني عن تكرار «من».","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص700، تحت «توجيه المتشابه»","url":""}]},{"id":"s15-132","number":132,"surah":15,"verses":[82],"references":[{"surah":15,"verses":[82]}],"verseLabel":"الحجر: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿آمِنِينَ﴾ وحذف ممَّ كانوا آمنين؟","answer":"حُذف متعلق الأمن ليتسع لما كانوا يتوهمونه من السلامة من الانهيار والعدو وسائر المخاوف؛ فقد اغتروا بحصانة بيوتهم، ولم تمنع عنهم عذاب الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص699، 700، تحت «دلالة حذف متعلق اسم الفاعل آمنين»","url":""}]},{"id":"s15-133","number":133,"surah":15,"verses":[84],"references":[{"surah":15,"verses":[84]}],"verseLabel":"الحجر: 84","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَا أَغْنَى عَنْهُمْ مَا كَانُوا يَكْسِبُونَ﴾ لا نفع؟","answer":"الإغناء هنا دفع الضرر؛ فنفت الآية أن تدفع مكاسبهم عنهم العذاب الذي ظنوا أنها تحميهم منه. أما النفع فأعم، إذ يشمل جلب الخير ودفع الضرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص706، تحت «سر التعبير بالإغناء دون النفع في الآية الكريمة»","url":""}]},{"id":"s15-134","number":134,"surah":15,"verses":[84],"references":[{"surah":15,"verses":[84]}],"verseLabel":"الحجر: 84","question":"ما سرّ التعبير بـ﴿يَكْسِبُونَ﴾ دون «يبنون» أو «ينحتون»؟","answer":"الكسب أوسع من البناء والنحت؛ فيشمل ما حصّلوه من الأموال وما عملوه واعتقدوه، فيعم النفي جميع ما ظنوه نافعًا لهم أو دافعًا للعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص708، تحت «سر التعبير بالكسب دون البناء أو النحت»","url":""}]},{"id":"s15-136","number":136,"surah":15,"verses":[85],"references":[{"surah":15,"verses":[85]}],"verseLabel":"الحجر: 85","question":"ما وجه البلاغة في الاستعارة في قوله الصفح الجميل؟","answer":"الصفح إعراض عن الذنب وترك مؤاخذة صاحبه، ووصفه بالجمال يطلب صفحًا يخلو من العتاب والتقريع والمنّ؛ فليس مجرد ترك العقوبة مع إبقاء الأذى بالقول.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص721، تحت «بلاغة الاستعارة في قوله الصفح الجميل»","url":""}]},{"id":"s15-137","number":137,"surah":15,"verses":[86],"references":[{"surah":15,"verses":[86]}],"verseLabel":"الحجر: 86","question":"ما دلالة ختام الآية بـ﴿إِنَّ رَبَّكَ هُوَ الْخَلَّاقُ الْعَلِيمُ﴾؟","answer":"يجمع الوصفان كمال القدرة على الخلق والإعادة وكمال العلم بأحوال الخلق وأعمالهم؛ فيطمئن النبي إلى أن ربه يتولى أمرهم ويجازيهم، ويناسب ذلك ذكر الساعة والأمر بالصفح.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص726، تحت «بلاغة اجتماع وصفي الخلاق العليم»","url":""}]},{"id":"s15-138","number":138,"surah":15,"verses":[87],"references":[{"surah":15,"verses":[87]}],"verseLabel":"الحجر: 87","question":"ما سرّ التعبير في قوله تعالى: ﴿آتَيْنَاكَ﴾ لا أعطيناك أو أوحينا؟","answer":"الإيتاء يتضمن وصول العطية إلى النبي، ويجمع معنى الإعطاء والتنزيل والإيحاء؛ وفيه إبراز للإكرام والإنعام بالقرآن، فوق مجرد الإخبار بوقوع الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص729، 730، تحت «نكتة التعبير بالفعل آتيناك دون أعطيناك»","url":""}]},{"id":"s15-139","number":139,"surah":15,"verses":[87],"references":[{"surah":15,"verses":[87]}],"verseLabel":"الحجر: 87","question":"ما دلالة تسمية الفاتحة ﴿سَبْعًا مِنَ الْمَثَانِي﴾؟","answer":"على تفسير السبع المثاني بالفاتحة، فهي سبع آيات تُثنّى قراءتها وتتكرر في الصلاة؛ فجمع التعبير عدد آياتها ووصف تكرار تلاوتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص731، تحت «دلالة لفظ المثاني»","url":""}]},{"id":"s15-140","number":140,"surah":15,"verses":[87],"references":[{"surah":15,"verses":[87]}],"verseLabel":"الحجر: 87","question":"ما سرّ عطف ﴿وَالْقُرْآنَ الْعَظِيمَ﴾ على السبع المثاني؟","answer":"على تفسير السبع المثاني بالفاتحة، فهذا عطف العام على الخاص؛ خُصّت الفاتحة بالذكر تشريفًا لها، ثم ذُكر القرآن كله تعظيمًا للنعمة التي أوتيها النبي.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص732، تحت «نوع عطف جملة والقرآن العظيم على السابق»","url":""}]},{"id":"s15-141","number":141,"surah":15,"verses":[88],"references":[{"surah":15,"verses":[88]}],"verseLabel":"الحجر: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا تَمُدَّنَّ عَيْنَيْكَ﴾ لا تنظر؟","answer":"مدّ العين يصور إطالة النظر مع شدة الرغبة والتطلع؛ فالنهي يتجه إلى الحرص على متاعهم والتعلق به، وهو أبلغ من النهي عن مجرد النظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص739، تحت «براعة التعبير بلا تمدن عينيك دون لا تنظر»","url":""}]},{"id":"s15-142","number":142,"surah":15,"verses":[88],"references":[{"surah":15,"verses":[88]}],"verseLabel":"الحجر: 88","question":"ما سرّ تثنية ﴿عَيْنَيْكَ﴾ في النهي عن مدّهما إلى متاع الآخرين؟","answer":"تثنية العينين تناسب كثرة المتاع الذي عندهم وتنوع أصنافه؛ فتشمل صورة النهي استغراق النظر والتطلع إلى ما بُسط لهم منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص739، تحت «نكتة التعبير بالعينين دون أن يقول عينك»","url":""}]},{"id":"s15-143","number":143,"surah":15,"verses":[88],"references":[{"surah":15,"verses":[88]}],"verseLabel":"الحجر: 88","question":"لماذا عبّر بالتمتيع في قوله: ﴿ما متعنا به﴾ دون الإنعام؟","answer":"يبرز التمتيع قصر مدة ما عندهم وزواله، فلا يستحق التعلق به.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص740، تحت «بلاغة ذكر التمتع دون الإنعام»","url":""}]},{"id":"s15-187","number":187,"surah":15,"verses":[88],"references":[{"surah":15,"verses":[88]}],"verseLabel":"الحجر: 88","question":"ما دلالة قوله أزواجا؟","answer":"تفسر الأزواج بأصناف من الناس؛ فمهما تنوع المتاع وتعدد أصحابه فهو زائل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص742، تحت «دلالة قوله أزواجا»","url":""}]},{"id":"s15-144","number":144,"surah":15,"verses":[88],"references":[{"surah":15,"verses":[88]}],"verseLabel":"الحجر: 88","question":"ما سرّ تقديم ﴿بِهِ﴾ في ﴿مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِنْهُمْ﴾؟","answer":"يبرز التقديم الاهتمام بالمتاع الذي تعلقوا به وشدة إقبالهم عليه، كما يُبقي «أزواجًا» متصلة بقيدها «منهم» من غير فصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص742، تحت «فائدة تقديم الجار والمجرور به»","url":""}]},{"id":"s15-145","number":145,"surah":15,"verses":[88],"references":[{"surah":15,"verses":[88]}],"verseLabel":"الحجر: 88","question":"ما وجه البلاغة في التعبير في قوله ولا تحزن عليهم بين الكناية والتصريح؟","answer":"فيه تسلية للنبي وتخفيف لحسرته على إعراضهم وما يصيرون إليه؛ وذكر «عليهم» يوجه النهي إلى الحزن على هؤلاء المكذبين، فلا يعم كل حزن.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص744، تحت «بلاغة التعبير في قوله ولا تحزن عليهم بين الكناية والتصريح»","url":""}]},{"id":"s15-146","number":146,"surah":15,"verses":[88],"references":[{"surah":15,"verses":[88]}],"verseLabel":"الحجر: 88","question":"ما وجه البلاغة في الاستعارة التمثيلية في السياق البليغ في قوله تعالى: ﴿وَاخْفِضْ جَنَاحَكَ لِلْمُؤْمِنِينَ﴾؟","answer":"صُوّر لين الجانب والتواضع للمؤمنين بطائر يخفض جناحه لفراخه فيضمهم ويرفق بهم؛ فتجمع الصورة القرب والرحمة وحسن الرعاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص746، تحت «بلاغة الاستعارة التمثيلية في السياق البليغ»","url":""}]},{"id":"s15-147","number":147,"surah":15,"verses":[89],"references":[{"surah":15,"verses":[89]}],"verseLabel":"الحجر: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنِّي أَنَا النَّذِيرُ الْمُبِينُ﴾ ولم يذكر البشير؟","answer":"المقام مقام وعيد للمكذبين وتخويف لهم من عاقبة التكذيب؛ فناسب إبراز الإنذار الواضح الذي يقيم الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص753، تحت «نكتة ذكر النذير دون البشير»","url":""}]},{"id":"s15-148","number":148,"surah":15,"verses":[90],"references":[{"surah":15,"verses":[90]}],"verseLabel":"الحجر: 90","question":"ما النكتة البلاغية في التشبيه بالكاف في سياق الآية الكريمة في قوله تعالى: ﴿كَمَا أَنْزَلْنَا عَلَى الْمُقْتَسِمِينَ﴾؟","answer":"من توجيه التشبيه أنه متصل بالإنذار السابق: أُنذركم بمثل ما أُنذر به المقتسمون، أو بما أُنزل عليهم من العذاب؛ ففيه تغليظ للوعيد. وقيل: يتصل بإيتاء الكتاب، تشبيهًا بما أُنزل على أهل الكتاب الذين فرّقوا فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص756، تحت «نكتة التشبيه بالكاف في سياق الآية الكريمة»","url":""}]},{"id":"s15-149","number":149,"surah":15,"verses":[91],"references":[{"surah":15,"verses":[91]}],"verseLabel":"الحجر: 91","question":"ما وجه البلاغة في الاستعارة في لفظ عضين في قوله تعالى: ﴿جَعَلُوا الْقُرْآنَ عِضِينَ﴾؟","answer":"«عضين» تصور القرآن كجسم مزّقوه أعضاء متفرقة؛ ومن توجيهها أنهم فرّقوا القول فيه بين سحر وشعر ونحوهما، أو آمنوا ببعض وكفروا ببعض. فالصورة تُظهر تشويههم لوحدته، لا مجرد تقسيم محايد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص763، تحت «بلاغة الاستعارة في لفظ عضين»","url":""}]},{"id":"s15-150","number":150,"surah":15,"verses":[92],"references":[{"surah":15,"verses":[92]}],"verseLabel":"الحجر: 92","question":"ما نكتة التوكيد بـ﴿أجمعين﴾ في قوله: ﴿لنسألنهم أجمعين﴾؟","answer":"ينفي أن يترك أحد منهم بلا سؤال أو حساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص768، تحت «نكتة التعبير بالتوكيد أجمعين»","url":""}]},{"id":"s15-188","number":188,"surah":15,"verses":[92],"references":[{"surah":15,"verses":[92]}],"verseLabel":"الحجر: 92","question":"لماذا قيل: ﴿عما كانوا يعملون﴾؟","answer":"يعم السؤال أعمالهم التي اقترفوها ويقرر مسؤوليتهم عنها في سياق الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص769، تحت «سبب إيثار السؤال عما سلف من عملهم»","url":""}]},{"id":"s15-151","number":151,"surah":15,"verses":[94],"references":[{"surah":15,"verses":[94]}],"verseLabel":"الحجر: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿فَاصْدَعْ بِمَا تُؤْمَرُ﴾ لا فبلّغ؟","answer":"الصدع يتضمن الجهر والإظهار بقوة وتأثير، وفي أصل معناه الشق؛ فيصور إعلان الحق الذي يفصل بينه وبين الباطل، ويزيد على مجرد إيصال البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص774، 775، تحت «سبب إيثار التعبير بفاصدع دون فبلغ»","url":""}]},{"id":"s15-152","number":152,"surah":15,"verses":[94],"references":[{"surah":15,"verses":[94]}],"verseLabel":"الحجر: 94","question":"ما دلالة بناء ﴿تُؤْمَرُ﴾ للمفعول؟","answer":"الآمر معلوم، والبناء للمفعول يبرز أن ما يجهر به النبي مأمور به من عند الله؛ فهو يبلّغ ما أُمر به، ولا ينشئ الدعوة من عند نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص776، تحت «دلالة التعبير بصيغة المبني للمفعول تؤمر»","url":""}]},{"id":"s15-153","number":153,"surah":15,"verses":[95],"references":[{"surah":15,"verses":[95]}],"verseLabel":"الحجر: 95","question":"ما دلالة إسناد الكفاية إلى ذات المستهزئين في قوله تعالى: ﴿إِنَّا كَفَيْنَاكَ الْمُسْتَهْزِئِينَ﴾؟","answer":"تعلقت الكفاية بالمستهزئين أنفسهم، فتشمل دفع أذاهم وأفعالهم، لا استهزاءهم وحده؛ وفي ذلك طمأنة للنبي تعينه على الجهر بما أُمر به.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص782، تحت «دلالة إسناد الكفاية إلى ذات المستهزئين»","url":""}]},{"id":"s15-154","number":154,"surah":15,"verses":[96],"references":[{"surah":15,"verses":[96]}],"verseLabel":"الحجر: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿يَجْعَلُونَ مَعَ اللَّهِ إِلَهًا آخَرَ﴾ لا ربًا؟","answer":"لأن موضع شركهم هو العبادة والتأله لغير الله، مع إقرارهم بربوبيته؛ فلفظ «إلهًا» يحدد الجريمة التي وقعوا فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص785، تحت «براعة ذكر لفظ إلها دون ربا»","url":""}]},{"id":"s15-155","number":155,"surah":15,"verses":[96],"references":[{"surah":15,"verses":[96]}],"verseLabel":"الحجر: 96","question":"ما دلالة تنكير ﴿إِلَهًا﴾ في ﴿إِلَهًا آخَرَ﴾؟","answer":"التنكير يعرض المعبود الباطل غير معين، أيًّا كان نوعه؛ فيكشف أن اتخاذهم الآلهة تابع لأهوائهم وأوهامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص786، تحت «نكتة تنكير لفظ إلها»","url":""}]},{"id":"s15-156","number":156,"surah":15,"verses":[96],"references":[{"surah":15,"verses":[96]}],"verseLabel":"الحجر: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿فَسَوْفَ يَعْلَمُونَ﴾ لا فسيعلمون؟","answer":"«سوف» تمد زمن الانتظار أكثر من السين، فيشتد وقع الوعيد وهم يترقبون ما سيعلمونه؛ وتأخر العقوبة لا يزيل تحققها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص786، تحت «نكتة ذكر سوف دون السين»","url":""}]},{"id":"s15-157","number":157,"surah":15,"verses":[97],"references":[{"surah":15,"verses":[97]}],"verseLabel":"الحجر: 97","question":"ما النكتة البلاغية في التعبير بالمضارع نعلم في قوله تعالى: ﴿نَعْلَمُ أَنَّكَ يَضِيقُ صَدْرُكَ﴾؟","answer":"الإخبار بعلم الله بحاله تسلية له وبيان للعناية به؛ والمضارع يستحضر استمرار هذا العلم، فلا يخفى على ربه ما يتجدد له من ضيق بسبب أقوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص791، تحت «نكتة التعبير بالمضارع نعلم»","url":""}]},{"id":"s15-158","number":158,"surah":15,"verses":[97],"references":[{"surah":15,"verses":[97]}],"verseLabel":"الحجر: 97","question":"ما سرّ إسناد الضيق إلى الصدر دون القلب؟","answer":"الصدر موضع يُتصوَّر فيه الاتساع والانقباض، فناسب تصوير أثر الأذى به؛ وإسناد الضيق إليه يصور التأذي بأقوالهم مع بقاء القلب مطمئنًا بالإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص794، تحت «بلاغة إسناد الضيق إلى الصدر دون القلب»","url":""}]},{"id":"s15-159","number":159,"surah":15,"verses":[98],"references":[{"surah":15,"verses":[98]}],"verseLabel":"الحجر: 98","question":"ما دلالة توجيه النبي إلى ﴿فَسَبِّحْ بِحَمْدِ رَبِّكَ﴾ بعد ذكر ضيق صدره؟","answer":"لأن التسبيح المصحوب بحمد الله والصلاة والعبادة مما يزيل ضيق الصدر والفزع؛ فجمع له بين تنزيه ربه والثناء عليه والتوجه إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص799، تحت «الغرض من الأمر بين التعيين والعموم»","url":""}]},{"id":"s15-160","number":160,"surah":15,"verses":[98],"references":[{"surah":15,"verses":[98]}],"verseLabel":"الحجر: 98","question":"ما فائدة الإضافة في قوله تعالى: ﴿بحمد ربك﴾؟","answer":"تفيد اختصاص الرب سبحانه بالحمد واجتماع التسبيح مع الثناء عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص800، تحت «فائدة الإضافة في قوله بحمد ربك»","url":""}]},{"id":"s15-189","number":189,"surah":15,"verses":[98],"references":[{"surah":15,"verses":[98]}],"verseLabel":"الحجر: 98","question":"لماذا اختير لفظ ﴿ربك﴾ في قوله: ﴿بحمد ربك﴾؟","answer":"في إضافة الرب إلى النبي لطف به؛ فهو مدبر أمره ومربيه والمحسن إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص800، تحت «سبب اختيار لفظ ربك»","url":""}]},{"id":"s15-161","number":161,"surah":15,"verses":[99],"references":[{"surah":15,"verses":[99]}],"verseLabel":"الحجر: 99","question":"ما وجه البلاغة في الكناية في قوله تعالى: ﴿وَاعْبُدْ رَبَّكَ حَتَّى يَأْتِيَكَ الْيَقِينُ﴾؟","answer":"تحديد الغاية بالموت يدل على استغراق العبادة زمن الحياة، فلا تكون مرة أو مدة ثم تنقطع؛ بل يثبت العبد عليها حتى أجله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص805، تحت «بلاغة الكناية»","url":""}]},{"id":"s15-162","number":162,"surah":15,"verses":[99],"references":[{"surah":15,"verses":[99]}],"verseLabel":"الحجر: 99","question":"ما سرّ تسمية الموت ﴿الْيَقِينَ﴾؟","answer":"لتحقق وقوعه ويقين الناس بمجيئه؛ فسُمّي باسم ما يلازمه من اليقين، تذكيرًا بنهاية لا شك فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص805، تحت «مجاز التعبير في تسمية الموت باليقين»","url":""}]},{"id":"s15-163","number":163,"surah":15,"verses":[99],"references":[{"surah":15,"verses":[99]}],"verseLabel":"الحجر: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿يَأْتِيَكَ﴾ لا يجيئك؟","answer":"اختير الإتيان دون المجيء للإشعار بأن إتيان الموت سهل يسير، وأنه ليس بينه وبين العبد إلا انقضاء الوقت وحلول الأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص804، تحت «بلاغة اختيار لفظ الإتيان دون المجيء»","url":""}]},{"id":"s15-190","number":190,"surah":15,"verses":[27],"references":[{"surah":15,"verses":[27]}],"verseLabel":"الحجر: 27","question":"ما دلالة قوله: ﴿والجانّ خلقناه من قبل من نار السموم﴾ في تقديم الجن على الإنس في مواضع من القرآن؟","answer":"قد يرتّب القرآن الألفاظ بحسب القدم والأولية في الوجود، كقوله: ﴿وما خلقت الجنّ والإنس إلا ليعبدون﴾، فقدّم الجن لأن خلقهم سابق لخلق الإنس، بدليل آية الحجر هذه: ﴿خلقناه من قبل﴾.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص53.","url":""}]},{"id":"s15-191","number":191,"surah":15,"verses":[28],"references":[{"surah":15,"verses":[28]}],"verseLabel":"الحجر: 28","question":"ما سر قوله: ﴿إني خالق بشرًا من صلصال من حمأ مسنون﴾، وفي ص: ﴿إني خالق بشرًا من طين﴾؟","answer":"القصة في الحجر جاءت بعد قوله: ﴿ولقد خلقنا الإنسان من صلصال من حمأ مسنون﴾، فناسب أن ترد اللفظة في صلب القصة. ومن لطائفه أن «صلصال» مؤلفة من الصاد والألف واللام، وقد تكررت فيها الألف واللام أكثر من الصاد، فوضعها في السورة المبدوءة بـ﴿الر﴾ أنسب.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص310–311.","url":""}]},{"id":"s15-192","number":192,"surah":15,"verses":[31],"references":[{"surah":15,"verses":[31]}],"verseLabel":"الحجر: 31","question":"ما الفرق بين ﴿أبى أن يكون مع الساجدين﴾ هنا، و﴿استكبر وكان من الكافرين﴾ في ص؟","answer":"«أبى» رفض وامتنع، و«استكبر» رأى نفسه خيرًا من غيره، والرفض قد يكون لغير استكبار. وقد بُنيت قصة الحجر على الإباء، وقصة ص على الاستكبار، ولذلك سُئل في ص: ﴿أستكبرت أم كنت من العالين﴾ وأجاب: ﴿أنا خير منه﴾، وليس مثل ذلك في الحجر.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص312–313.","url":""}]},{"id":"s15-193","number":193,"surah":15,"verses":[31],"references":[{"surah":15,"verses":[31]}],"verseLabel":"الحجر: 31","question":"ما سر ذكر السجود في قوله: ﴿أبى أن يكون مع الساجدين﴾، وتركه في ص؟","answer":"جوّ السجود شائع في قصة الحجر وسورتها، فقد ورد السجود في القصة ست مرات، وخُتمت به السورة: ﴿وكن من الساجدين﴾. أما في ص فورد ثلاث مرات، حتى إن داود لمّا تاب قيل فيه: ﴿وخرّ راكعًا﴾.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص314.","url":""}]},{"id":"s15-194","number":194,"surah":15,"verses":[42],"references":[{"surah":15,"verses":[42]}],"verseLabel":"الحجر: 42","question":"ما سر التشديد في قوله: ﴿إلا من اتّبعك من الغاوين﴾، والتخفيف في ص: ﴿وممّن تبِعك منهم أجمعين﴾؟","answer":"جاء بعد القصة في الحجر: ﴿نبّئ عبادي أني أنا الغفور الرحيم﴾، فناسب أن يخفّف على عباده فلا يدخل النار إلا من بالغ في اتباع إبليس. ولم يرد مثل ذلك في ص فكان التحذير أشد. ثم إن قصة الحجر جاءت بعد ذكر نعم الله على البشر، وفي ص بعد ذكر العقوبات.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص317.","url":""}]},{"id":"s15-195","number":195,"surah":15,"verses":[52],"references":[{"surah":15,"verses":[52]}],"verseLabel":"الحجر: 52","question":"ما سر ترك ردّ إبراهيم التحية في قوله: ﴿إذ دخلوا عليه فقالوا سلامًا﴾، وذكره في الذاريات: ﴿قال سلامٌ﴾؟","answer":"وُصف الضيف في الذاريات بأنهم ﴿المكرَمين﴾، وردّ التحية من الإكرام، فذُكر، وردّها بخير منها بالجملة الاسمية الدالة على الثبوت. أما في الحجر فلم يصفهم بالإكرام ولم يذكر أنه ردّ عليهم.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص84.","url":""}]},{"id":"s15-196","number":196,"surah":15,"verses":[52,53],"references":[{"surah":15,"verses":[52,53]}],"verseLabel":"الحجر: 52، 53","question":"ما دلالة الجملة الاسمية في قوله: ﴿إنا منكم وجِلون﴾ و﴿إنا نبشّرك﴾، والفعلية في الذاريات: ﴿فأوجس منهم خيفة﴾ و﴿وبشّروه﴾؟","answer":"الوجل في الحجر أكبر؛ فقد واجههم به بجملة اسمية مؤكدة بـ«إنّ»، وبالصفة المشبهة «وجِلون» الدالة على شدة الخوف، وبصيغة الجمع لأهل البيت. فلما واجههم بالاسمية واجهوه بالبشرى اسميةً. أما في الذاريات فجاء الخوف فعليًّا غير مؤكد بصيغة الغيبة، فجاءت البشرى فعلية بصيغة الغيبة أيضًا.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص86–87.","url":""}]},{"id":"s15-197","number":197,"surah":15,"verses":[11],"references":[{"surah":15,"verses":[11]}],"verseLabel":"الحجر: 11","question":"ما سر التعبير بـ«رسول» في قوله: ﴿وما يأتيهم من رسول إلا كانوا به يستهزئون﴾، وبـ«نبي» في الزخرف؟","answer":"تقدّم في آية الزخرف «كم» الخبرية الدالة على التكثير: ﴿وكم أرسلنا من نبي﴾، فناسب ذكر النبي الذي يعمّ المرسل وغير المرسل. أما آية الحجر فلم يرد فيها ولا قبلها ما يطلب التكثير، فجاء بـ«رسول».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص185.","url":""}]},{"id":"s15-198","number":198,"surah":15,"verses":[16],"references":[{"surah":15,"verses":[16]}],"verseLabel":"الحجر: 16","question":"ما دلالة إسناد التزيين إلى ضميره سبحانه في قوله: ﴿ولقد جعلنا في السماء بروجًا وزيّنّاها للناظرين﴾؟","answer":"ينسب الله تزيين الخير والحسن إلى ذاته، كتزيين السماء هنا، أما تزيين السوء فيبني فيه الفعل للمجهول غالبًا، كقوله: ﴿زُيّن للذين كفروا الحياة الدنيا﴾ و﴿زُيّن لهم سوء أعمالهم﴾.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص322.","url":""}]},{"id":"s15-199","number":199,"surah":15,"verses":[17,18],"references":[{"surah":15,"verses":[17,18]}],"verseLabel":"الحجر: 17–18","question":"ما سر وصف الشهاب بـ﴿مبين﴾ في قوله: ﴿إلا من استرق السمع فأتبعه شهاب مبين﴾، وبـ﴿ثاقب﴾ في الصافات؟","answer":"«مبين» ظاهر للمبصرين، و«ثاقب» نافذ بضوئه وهو أشد. والمقام في الصافات أشدّ: ففيها الشيطان «المارد» وهو أقوى من «الرجيم»، وفيها «الخطف» وهو استلاب بسرعة، أما الاستراق فأخذ بخفية قد يكون بالتنصّت دون حركة، فناسب كلًّا وصفُه.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص74–75.","url":""}]},{"id":"s15-200","number":200,"surah":15,"verses":[35],"references":[{"surah":15,"verses":[35]}],"verseLabel":"الحجر: 35","question":"ما سر التعريف في قوله: ﴿وإن عليك اللعنة﴾، والإضافة في ص: ﴿وإن عليك لعنتي﴾؟","answer":"ذكر الله نفسه في قصة ص أكثر مما في الحجر، ست مرات مقابل ثلاث، ومنها ﴿لما خلقت بيديّ﴾، فأضاف اللعنة إلى نفسه، ولما لم يكن كذلك في الحجر قال «اللعنة». وفي «درة التنزيل» أن قصة الحجر ابتُدئت باسم الجنس المعرّف ﴿الإنسان﴾ فجرت على التعريف.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص315–316.","url":""}]},{"id":"s15-201","number":201,"surah":15,"verses":[39],"references":[{"surah":15,"verses":[39]}],"verseLabel":"الحجر: 39","question":"ما سر إقسام إبليس بالإغواء هنا: ﴿ربّ بما أغويتني﴾، وبالعزة في ص: ﴿فبعزّتك﴾؟","answer":"تقدّم في ص ذكر اسمه «العزيز»: ﴿العزيز الوهاب﴾ و﴿العزيز الغفار﴾، وبُدئت السورة بالعزة: ﴿بل الذين كفروا في عزّة وشقاق﴾، فناسب القسم بالعزة. وتردّد في الحجر ذكر الإغواء: ﴿ولأغوينّهم أجمعين﴾ و﴿من الغاوين﴾، فأقسم بالإغواء.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص316.","url":""}]},{"id":"s15-202","number":202,"surah":15,"verses":[39],"references":[{"surah":15,"verses":[39]}],"verseLabel":"الحجر: 39","question":"ما سر ذكر التزيين في قوله: ﴿لأزيّننّ لهم في الأرض ولأغوينّهم أجمعين﴾، وتركه في ص؟","answer":"ورد ذكر الزينة في سورة الحجر ولم يرد في ص، كقوله: ﴿ولقد جعلنا في السماء بروجًا وزيّنّاها للناظرين﴾، وذكر ما في الأرض من الرواسي والمعايش وما أُنبت فيها من كل شيء موزون، وهذا من التزيين في الأرض، فناسب ذكره في الحجر.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص316–317.","url":""}]},{"id":"s15-203","number":203,"surah":15,"verses":[60],"references":[{"surah":15,"verses":[60]}],"verseLabel":"الحجر: 60","question":"ما سر التوكيد في قوله: ﴿إلا امرأته قدّرنا إنها لمن الغابرين﴾، وتركه في النمل: ﴿قدّرناها من الغابرين﴾؟","answer":"القصة في الحجر أطول (عشرون آية مقابل خمس في النمل)، فناسب طولُ الآية طولَ القصة. وسبقها توكيد: ﴿إنا لمنجّوهم أجمعين﴾ بـ«إنّ» واللام والاسم، والمؤكدات في قصة الحجر أكثر. أما النمل فلم يسبقها توكيد، ووُصف القوم في الحجر بالإجرام وفي النمل بالجهل.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص85–87.","url":""}]},{"id":"s16-1","number":1,"surah":16,"verses":[1],"references":[{"surah":16,"verses":[1]}],"verseLabel":"النحل: 1","question":"ما سرّ افتتاح السورة بالماضي ﴿أَتَى أَمْرُ اللَّهِ﴾ مع أن الموعود لم يقع بعد؟","answer":"لتحقيق الوقوع؛ ما وعد الله به محقق حتى صح التعبير عنه كأنه أتى وانتهى.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص26، تحت «براعة الاستهلال ودلالة الفعل الماضي أتى»","url":""}]},{"id":"s16-2","number":2,"surah":16,"verses":[1],"references":[{"surah":16,"verses":[1]}],"verseLabel":"النحل: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿أَمْرُ اللَّهِ﴾ لا عذاب الله؟","answer":"عُبّر بـ﴿أمر الله﴾ تهويلًا وتعظيمًا للموعود؛ فهو ما قدّره الله وأراد وقوعه في أجله، وإضافته إلى اسم الجلالة تزيده عظمةً وهيبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص26، تحت «فائدة إضافة أمر إلى اسم الجلالة»","url":""}]},{"id":"s16-3","number":3,"surah":16,"verses":[1],"references":[{"surah":16,"verses":[1]}],"verseLabel":"النحل: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَا تَسْتَعْجِلُوهُ﴾ بعد ﴿أتى﴾؟","answer":"الماضي يقرر تحقق الموعود، ثم يتفرع عليه النهي عن استعجاله استهزاءً؛ فما هو واقع لا محالة لا يجدي استبطاؤه ولا طلب تعجيله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص27، تحت «نوع الفاء في فلا تستعجلوه وفائدتها»","url":""}]},{"id":"s16-4","number":4,"surah":16,"verses":[1],"references":[{"surah":16,"verses":[1]}],"verseLabel":"النحل: 1","question":"ما سرّ ختام الآية بـ﴿سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ﴾؟","answer":"زعم المشركون أن شركاءهم يدفعون عنهم العذاب، فجاء التسبيح والتعالي تنزيهًا لله عن هذا الزعم وإبطالًا لقدرة تلك المعبودات على منع أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص30، تحت «دلالة الجمع بين سبحانه وتعالى»","url":""}]},{"id":"s16-5","number":5,"surah":16,"verses":[2],"references":[{"surah":16,"verses":[2]}],"verseLabel":"النحل: 2","question":"ما وجه البلاغة في الاستعارة في إطلاق الروح على الوحي في قوله تعالى: ﴿يُنَزِّلُ الْمَلَائِكَةَ بِالرُّوحِ﴾؟","answer":"سمي الوحي روحًا لأنه يحيي القلوب كما تحيي الروح الأجساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص40، 41، تحت «بلاغة الاستعارة في إطلاق الروح على الوحي»","url":""}]},{"id":"s16-6","number":6,"surah":16,"verses":[2],"references":[{"surah":16,"verses":[2]}],"verseLabel":"النحل: 2","question":"ما دلالة تعريف ﴿الملائكة﴾ في قوله تعالى: ﴿ينزل الملائكة بالروح من أمره﴾؟","answer":"تفيد ﴿أل﴾ الجنس، فتتناول جنس الملائكة الذين يبلغون رسالات الله وينزلون بأمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص39، تحت «دلالة أل على الجنس في لفظ الملائكة»","url":""}]},{"id":"s16-208","number":208,"surah":16,"verses":[2],"references":[{"surah":16,"verses":[2]}],"verseLabel":"النحل: 2","question":"ما دلالة جمع لفظ ﴿الملائكة﴾ في سياق تنزيل الوحي؟","answer":"يشمل الجمع الملائكة الموكلين بالتبليغ، وقيل أريد به جبريل وعبر عنه بالجمع لأنه رئيسهم والمقتدى به في هذا الشأن.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص39، تحت «دلالة الجمع في لفظ الملائكة»","url":""}]},{"id":"s16-7","number":7,"surah":16,"verses":[2],"references":[{"surah":16,"verses":[2]}],"verseLabel":"النحل: 2","question":"ما دلالة حرف الجر من أمره ومعنى الإضافة في قوله تعالى: ﴿مِنْ أَمْرِهِ﴾؟","answer":"من توجيه العبارة أن التنزيل يقع بأمر الله وإذنه؛ فلا تتصرف الملائكة في الوحي من عند نفسها. وتحتمل «من» أيضًا بيان أن الوحي من جنس أموره وشؤونه التي استأثر بتقديرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص41، تحت «دلالة حرف الجر من أمره ومعنى الإضافة»","url":""}]},{"id":"s16-8","number":8,"surah":16,"verses":[2],"references":[{"surah":16,"verses":[2]}],"verseLabel":"النحل: 2","question":"ما دلالة تلخيص الوحي في ﴿أَنْ أَنْذِرُوا أَنَّهُ لَا إِلَهَ إِلَّا أَنَا﴾؟","answer":"التوحيد أصل الدعوة وأول واجب، فجمع الوحي في إفراد الله بالألوهية. وناسب الإنذار حال من اتخذوا مع الله آلهة أخرى، لتحذيرهم من عاقبة الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص48، تحت «بلاغة كلمة التوحيد لا إله إلا أنا»","url":""}]},{"id":"s16-9","number":9,"surah":16,"verses":[3],"references":[{"surah":16,"verses":[3]}],"verseLabel":"النحل: 3","question":"ما دلالة الباء في شبه الجملة بالحق في قوله تعالى: ﴿خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ بِالْحَقِّ﴾؟","answer":"«بالحق» تجعل الخلق ملتبسًا بالحكمة ومقرونًا بها، لا عبثًا؛ ومن ذلك أن يجازى كل عامل بما يناسب عمله، فالخلق قائم على غاية وحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص58، تحت «دلالة الباء في شبه الجملة بالحق»","url":""}]},{"id":"s16-10","number":10,"surah":16,"verses":[4],"references":[{"surah":16,"verses":[4]}],"verseLabel":"النحل: 4","question":"ما سرّ التعبير في قوله تعالى عن الإنسان: ﴿فَإِذَا هُوَ خَصِيمٌ مُبِينٌ﴾؟","answer":"«إذا» للمفاجأة والفاء للتفريع؛ فيبرز التركيب المفارقة بين أصله الضعيف نطفةً وصيرورته شديد الخصومة، حتى يجادل في قدرة من خلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص71، تحت «دلالة التركيب فإذا وأثرها في السياق»","url":""}]},{"id":"s16-11","number":11,"surah":16,"verses":[4],"references":[{"surah":16,"verses":[4]}],"verseLabel":"النحل: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿خَصِيمٌ﴾ لا مجادل؟","answer":"«خصيم» على وزن فعيل للمبالغة، فتدل على شدة الخصومة وكثرتها. والجدال قد يكون محمودًا أو مذمومًا، أما الخصومة هنا فتبرز منازعته وجحوده لخالقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص76، تحت «الخصيم والمجادل»","url":""}]},{"id":"s16-12","number":12,"surah":16,"verses":[5],"references":[{"surah":16,"verses":[5]}],"verseLabel":"النحل: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿وَالْأَنْعَامَ خَلَقَهَا لَكُمْ﴾ وقدّمها؟","answer":"تقديم الأنعام يبرز العناية بما فيها من فوائد للإنسان، وإعادة الضمير في «خلقها» تقوي تقرير خلقها؛ تمهيدًا لتفصيل نعم الدفء والمنافع والأكل.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص81، تحت «سر تقديم المفعول به وبلاغته»","url":""}]},{"id":"s16-13","number":13,"surah":16,"verses":[5],"references":[{"surah":16,"verses":[5]}],"verseLabel":"النحل: 5","question":"ما دلالة تعريف ﴿الْأَنْعَامَ﴾؟","answer":"لاستحضار الجنس المعروف كله، لا أفرادًا مخصوصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص81، تحت «دلالة أل في لفظ الأنعام وفائدتها»","url":""}]},{"id":"s16-14","number":14,"surah":16,"verses":[5],"references":[{"surah":16,"verses":[5]}],"verseLabel":"النحل: 5","question":"ما سرّ تخصيص ﴿دِفْءٌ﴾ بالذكر ثم عطف ﴿وَمَنَافِعُ﴾ عليه؟","answer":"خُصّ الدفء بالذكر للعناية بشأنه، ثم عُطفت عليه «منافع» لتشمل سائر ما ينتفع به من الأنعام؛ فهو عطف العام على الخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص85، تحت «دلالة عطف العام على الخاص»","url":""}]},{"id":"s16-15","number":15,"surah":16,"verses":[6],"references":[{"surah":16,"verses":[6]}],"verseLabel":"النحل: 6","question":"ما دلالة تنكير لفظ جمال في قوله تعالى: ﴿لَكُمْ فِيهَا جَمَالٌ﴾؟","answer":"بعد المنافع الضرورية ذُكرت نعمة الجمال التي تسر النفوس؛ وتنكيره يعظم ما في منظر الأنعام عند رواحها وسراحها من بهجة لأصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص94، تحت «دلالة تنكير لفظ جمال»","url":""}]},{"id":"s16-16","number":16,"surah":16,"verses":[6],"references":[{"surah":16,"verses":[6]}],"verseLabel":"النحل: 6","question":"ما سرّ تقديم الرواح على السراح؟","answer":"لأن جمالها عند الرواح أظهر؛ تعود ممتلئة البطون حافلة الضروع، ثم تجتمع في الحظائر، فيكون منظرها أوقع في نفوس أصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص95، تحت «السر في تقديم تريحون على تسرحون»","url":""}]},{"id":"s16-17","number":17,"surah":16,"verses":[7],"references":[{"surah":16,"verses":[7]}],"verseLabel":"النحل: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿تَحْمِلُ أَثْقَالَكُمْ﴾ بالمضارع؟","answer":"لتصوير المنفعة متجددة في كل سفر وحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص101، تحت «نكتة التعبير بالمضارع تحمل»","url":""}]},{"id":"s16-18","number":18,"surah":16,"verses":[7],"references":[{"surah":16,"verses":[7]}],"verseLabel":"النحل: 7","question":"ما فائدة القيد إلا بشق الأنفس في قوله تعالى: ﴿إِلَى بَلَدٍ لَمْ تَكُونُوا بَالِغِيهِ إِلَّا بِشِقِّ الْأَنْفُسِ﴾؟","answer":"استحضر المشقة التي رفعتها الأنعام ليُرى قدر النعمة بالمقارنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص103، تحت «فائدة القيد إلا بشق الأنفس»","url":""}]},{"id":"s16-19","number":19,"surah":16,"verses":[7],"references":[{"surah":16,"verses":[7]}],"verseLabel":"النحل: 7","question":"ما سرّ ختام الآية بـ﴿رَءُوفٌ رَحِيمٌ﴾؟","answer":"حمل الأثقال وتيسير بلوغ البلاد أثر من رأفة الله ورحمته بعباده؛ وقدمت الرأفة، وهي أخص وأرق، ثم ذُكرت الرحمة لتتم دلالة الإنعام ورفع المشقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص107، تحت «نكتة الترتيب في رؤوف رحيم»","url":""}]},{"id":"s16-20","number":20,"surah":16,"verses":[8],"references":[{"surah":16,"verses":[8]}],"verseLabel":"النحل: 8","question":"ما سرّ ذكر الخيل والبغال والحمير منفصلة عن الأنعام؟","answer":"لأن السياق انتقل من الدفء والأكل إلى الركوب والزينة، وهي منافعها الأظهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص114، تحت «نكتة العدول عن حملها للأثقال إلى ركوبها واتخاذها زينة»","url":""}]},{"id":"s16-21","number":21,"surah":16,"verses":[8],"references":[{"surah":16,"verses":[8]}],"verseLabel":"النحل: 8","question":"ما النكتة البلاغية في العدول عن لام التعليل وزينة في قوله تعالى: ﴿لِتَرْكَبُوهَا وَزِينَةً﴾؟","answer":"نُصّ على الركوب بوصفه الغرض الأصلي من خلقها للإنسان، ثم ذُكرت الزينة منفعة تابعة؛ فجمع التعبير الحاجة والبهجة مع بيان مرتبتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص115، تحت «نكتة العدول عن لام التعليل وزينة»","url":""}]},{"id":"s16-22","number":22,"surah":16,"verses":[8],"references":[{"surah":16,"verses":[8]}],"verseLabel":"النحل: 8","question":"ما دلالة ختام الآية بـ﴿وَيَخْلُقُ مَا لَا تَعْلَمُونَ﴾؟","answer":"فتح أفق النعم لما يستحدث ويخفى، فلا يحصر الخلق في وسائل النقل المعروفة زمن التنزيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص117، تحت «فائدة الخبر في خلقه ما لا يعلمون»","url":""}]},{"id":"s16-23","number":23,"surah":16,"verses":[9],"references":[{"surah":16,"verses":[9]}],"verseLabel":"النحل: 9","question":"ما فائدة تقديم شبه الجملة على المسند إليه في قوله تعالى: ﴿وَعَلَى اللَّهِ قَصْدُ السَّبِيلِ﴾؟","answer":"تقديم الجار يفيد أن بيان الطريق المستقيم وهدايته تفضل تكفل الله به.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص123، تحت «فائدة تقديم شبه الجملة على المسند إليه»","url":""}]},{"id":"s16-24","number":24,"surah":16,"verses":[9],"references":[{"surah":16,"verses":[9]}],"verseLabel":"النحل: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿قَصْدُ السَّبِيلِ﴾ لا السبيل القاصد؟","answer":"من توجيه الإضافة أنها إضافة الصفة إلى الموصوف، أي السبيل القاصد المستقيم الذي لا عوج فيه؛ وعلى هذا يكون المعنى: على الله بيان ذلك الطريق بالأدلة والرسل والكتب.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص125، تحت «فائدة الإضافة في قصد السبيل»","url":""}]},{"id":"s16-25","number":25,"surah":16,"verses":[9],"references":[{"surah":16,"verses":[9]}],"verseLabel":"النحل: 9","question":"ما سرّ العدول في ومنها جائر في قوله تعالى: ﴿وَمِنْهَا جَائِرٌ﴾؟","answer":"وُصف بعض السبل بالجور، أي الميل عن الاستقامة، كناية عن طرق الضلال. والعدول عن نحو «وعليه جائرها» يميز طريق الحق الذي بيّنه الله لهداية الناس من طرق الانحراف عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص126، تحت «سر العدول في ومنها جائر»","url":""}]},{"id":"s16-26","number":26,"surah":16,"verses":[10],"references":[{"surah":16,"verses":[10]}],"verseLabel":"النحل: 10","question":"ما النكتة البلاغية في القصر بتعريف طرفي الإسناد في قوله تعالى: ﴿هُوَ الَّذِي أَنْزَلَ مِنَ السَّمَاءِ مَاءً﴾؟","answer":"تعريف طرفي الإسناد في ﴿هُوَ الَّذِي أَنْزَلَ﴾ يفيد قصر الإنزال على الله وحده، وفي الموصول وصلته تعظيم للمنعم بذكر نعمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص134، تحت «نكتة القصر بتعريف طرفي الإسناد»","url":""}]},{"id":"s16-27","number":27,"surah":16,"verses":[10],"references":[{"surah":16,"verses":[10]}],"verseLabel":"النحل: 10","question":"ما دلالة جملة ومنه شجر بين الفصل والوصل في قوله تعالى: ﴿مِنْهُ شَرَابٌ وَمِنْهُ شَجَرٌ﴾؟","answer":"قسم الماء بحسب نفعه المباشر للإنسان ونفعه في النبات الذي ترعى فيه الأنعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص138، تحت «دلالة جملة ومنه شجر بين الفصل والوصل»","url":""}]},{"id":"s16-28","number":28,"surah":16,"verses":[11],"references":[{"surah":16,"verses":[11]}],"verseLabel":"النحل: 11","question":"ما سرّ تفصيل الزرع والزيتون والنخيل والأعناب قبل ﴿وَمِنْ كُلِّ الثَّمَرَاتِ﴾؟","answer":"لجمع القوت والزيت والثمر، ثم عمم بقوله ﴿ومن كل الثمرات﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص147، تحت «فائدة الترتيب بين الزرع وما عطف عليه»","url":""}]},{"id":"s16-29","number":29,"surah":16,"verses":[11],"references":[{"surah":16,"verses":[11]}],"verseLabel":"النحل: 11","question":"ما سرّ ختام الآية بـ﴿لِقَوْمٍ يَتَفَكَّرُونَ﴾؟","answer":"لأن إدراك ما في إنبات هذه الأصناف من دلالة على وجود الله وكمال قدرته ووحدانيته يحتاج إلى التفكر والاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص150، تحت «سر تذييل الآية بالتفكر»","url":""}]},{"id":"s16-30","number":30,"surah":16,"verses":[11],"references":[{"surah":16,"verses":[11]}],"verseLabel":"النحل: 11","question":"ما دلالة إفراد ﴿آيَةً﴾ بعد ذكر أصناف النبات؟","answer":"من توجيه الإفراد أن المدلول واحد، وهو وحدانية الله، وقيل: لوحدة المنشأ الذي تتفرع عنه هذه النعم، وهو الماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص149، تحت «دلالة إفراد الآية»","url":""}]},{"id":"s16-31","number":31,"surah":16,"verses":[12],"references":[{"surah":16,"verses":[12]}],"verseLabel":"النحل: 12","question":"ما سرّ جمع ﴿لَآيَاتٍ﴾ بعد تسخير الليل والنهار والشمس والقمر والنجوم؟","answer":"الجمع يراعي تعدد الأدلة؛ فالليل والنهار والشمس والقمر والنجوم، وما لكل منها من أحوال ومنافع، دلائل متنوعة على وحدانية الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص159، تحت «نكتة جمع آيات في لآيات لقوم يعقلون»","url":""}]},{"id":"s16-34","number":34,"surah":16,"verses":[13],"references":[{"surah":16,"verses":[13]}],"verseLabel":"النحل: 13","question":"ما الموقع النحوي لجملة مختلفا ألوانه في قوله تعالى: ﴿مُخْتَلِفًا أَلْوَانُهُ﴾؟","answer":"المراد بالألوان ما يشمل اختلاف الأصناف والخصائص؛ فتنوع ما خلقه الله في الأرض يلفت إلى سعة قدرته وتعدد نعمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص169، تحت «الموقع النحوي لجملة مختلفا ألوانه»","url":""}]},{"id":"s16-35","number":35,"surah":16,"verses":[14],"references":[{"surah":16,"verses":[14]}],"verseLabel":"النحل: 14","question":"ما وجه البلاغة في القصر في تعريف طرفي الإسناد في قوله تعالى: ﴿وَهُوَ الَّذِي سَخَّرَ الْبَحْرَ﴾؟","answer":"«هو» مبتدأ، والموصول خبر؛ وتعريف الطرفين يفيد قصر تسخير البحر على الله. وتذكر الصلة نعمته بتذليل هذا المخلوق لمنافع الناس، فتدل على قدرته واستحقاقه العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص178، تحت «بلاغة القصر في تعريف طرفي الإسناد»","url":""}]},{"id":"s16-36","number":36,"surah":16,"verses":[14],"references":[{"surah":16,"verses":[14]}],"verseLabel":"النحل: 14","question":"ما فائدة وصف اللحم بالوصف طريا في قوله تعالى: ﴿لَحْمًا طَرِيًّا﴾؟","answer":"في الطراوة تذكير بلذة السمك ولطافته، وبنعمة خلق لحم عذب طري في ماء مالح؛ وفيها أيضًا تنبيه إلى المبادرة بأكله قبل أن يسرع إليه الفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص180، تحت «فائدة وصف اللحم بالوصف طريا»","url":""}]},{"id":"s16-37","number":37,"surah":16,"verses":[15],"references":[{"surah":16,"verses":[15]}],"verseLabel":"النحل: 15","question":"ما وجه البلاغة في الإيجاز في أسلوب التعليل في قوله تعالى: ﴿أَنْ تَمِيدَ بِكُمْ﴾؟","answer":"بيّن غاية إلقاء الرواسي: كراهة أن تضطرب الأرض بأهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص195، تحت «بلاغة الإيجاز في أسلوب التعليل»","url":""}]},{"id":"s16-38","number":38,"surah":16,"verses":[15],"references":[{"surah":16,"verses":[15]}],"verseLabel":"النحل: 15","question":"كيف يُوجَّه بلاغيًا الاهتداء بين الحسي والمعنوي في قوله تعالى: ﴿وَأَنْهَارًا وَسُبُلًا لَعَلَّكُمْ تَهْتَدُونَ﴾؟","answer":"جُمعت الأنهار والسبل في تعداد النعم، وخُتمت بالاهتداء الذي يحتمل بلوغ مقاصد السفر، ويشمل الاستدلال بهذه المخلوقات على التوحيد؛ فتجتمع منفعة الطريق ودلالة الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص198، تحت «توجيه الاهتداء بين الحسي والمعنوي»","url":""}]},{"id":"s16-39","number":39,"surah":16,"verses":[16],"references":[{"surah":16,"verses":[16]}],"verseLabel":"النحل: 16","question":"ما فائدة الفصل بين المعطوفات في قوله تعالى: ﴿وَعَلَامَاتٍ وَبِالنَّجْمِ هُمْ يَهْتَدُونَ﴾؟","answer":"عمم العلامات الأرضية ثم خص النجم بالذكر لعظم دوره في ظلمات البر والبحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص200، تحت «فائدة الفصل بين المعطوفات»","url":""}]},{"id":"s16-40","number":40,"surah":16,"verses":[17],"references":[{"surah":16,"verses":[17]}],"verseLabel":"النحل: 17","question":"ما وجه البلاغة في الاستفهام ودلالته في قوله تعالى: ﴿أَفَمَنْ يَخْلُقُ كَمَنْ لَا يَخْلُقُ﴾؟","answer":"استفهام يحول براهين النعم إلى نتيجة بدهيّة: لا يستوي الخالق والعاجز المخلوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص206، تحت «بلاغة الاستفهام ودلالته»","url":""}]},{"id":"s16-41","number":41,"surah":16,"verses":[18],"references":[{"surah":16,"verses":[18]}],"verseLabel":"النحل: 18","question":"ما سرّ إفراد ﴿نِعْمَةَ اللَّهِ﴾ مع ذكر العد؟","answer":"اسم جنس؛ بل النعمة الواحدة تتشعب إلى نعم لا يحصيها الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص212، 213، تحت «سر إفراد النعمة مع ذكر العد ولا يعد إلا الجمع»","url":""}]},{"id":"s16-42","number":42,"surah":16,"verses":[18],"references":[{"surah":16,"verses":[18]}],"verseLabel":"النحل: 18","question":"ما سرّ ختام آية النعم بـ﴿غَفُورٌ رَحِيمٌ﴾؟","answer":"من عجز عن إحصاء النعم عجز عن الوفاء بحق شكرها؛ فجاءت المغفرة والرحمة تسليةً، وبيانًا أن الله يتجاوز عن تقصير عباده ويواصل إنعامه عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص214، تحت «علة الفصل ودلالته»","url":""}]},{"id":"s16-43","number":43,"surah":16,"verses":[19],"references":[{"surah":16,"verses":[19]}],"verseLabel":"النحل: 19","question":"ما دلالة الجمع بين ﴿مَا تُسِرُّونَ وَمَا تُعْلِنُونَ﴾؟","answer":"الجمع بين الضدين يدل على شمول علم الله للظاهر والباطن؛ فلا يحجب الإسرار شيئًا عنه، وفي ذلك بعث على إصلاح العمل والنية.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص221، تحت «بديع فن الطباق»","url":""}]},{"id":"s16-44","number":44,"surah":16,"verses":[20],"references":[{"surah":16,"verses":[20]}],"verseLabel":"النحل: 20","question":"ما سرّ التعبير في قوله تعالى عن المعبودات: ﴿أَمْوَاتٌ غَيْرُ أَحْيَاءٍ﴾؟","answer":"وصف الأصنام بأنها «غير أحياء» يؤكد نفي الحياة عنها، ويدفع توهم أنها كانت حية ثم ماتت أو ستحيا؛ فهي جمادات لا تملك شعورًا ولا قدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص227، تحت «بلاغة الاحتراس»","url":""}]},{"id":"s16-45","number":45,"surah":16,"verses":[21],"references":[{"surah":16,"verses":[21]}],"verseLabel":"النحل: 21","question":"ما نكتة قوله عن المعبودات: ﴿وما يشعرون﴾؟","answer":"ينفي عنها أدنى إدراك؛ فهي لا تشعر حتى بوقت بعث عابديها، فكيف تصلح للعبادة أو دفع الضرر؟","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص229، تحت «نكتة التعبير بمفردة الشعور»","url":""}]},{"id":"s16-209","number":209,"surah":16,"verses":[21],"references":[{"surah":16,"verses":[21]}],"verseLabel":"النحل: 21","question":"لماذا قيل: ﴿أيان يبعثون﴾ دون «متى يبعثون»؟","answer":"تستعمل ﴿أيان﴾ في السؤال عن الزمن العظيم الشأن، فتلائم تهويل وقت البعث وما يقع فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص230، تحت «سر استعمال أيان دون متى»","url":""}]},{"id":"s16-46","number":46,"surah":16,"verses":[22],"references":[{"surah":16,"verses":[22]}],"verseLabel":"النحل: 22","question":"ما وجه البلاغة في إقامة الموصوف خبرا دون صفته في قوله تعالى: ﴿إِلَهُكُمْ إِلَهٌ وَاحِدٌ﴾؟","answer":"أُعيد لفظ «إله» في الخبر ليتجه نفي التعدد إلى الألوهية نفسها: المعبود الحق واحد لا يتعدد. فلو قيل «إلهكم واحد» وحدها لكان احتمال حمل الوحدة على غير هذا المعنى أوسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص234، تحت «بلاغة إقامة الموصوف خبرا دون صفته»","url":""}]},{"id":"s16-47","number":47,"surah":16,"verses":[22],"references":[{"surah":16,"verses":[22]}],"verseLabel":"النحل: 22","question":"ما سرّ إسناد الإنكار إلى القلوب؟","answer":"لأن القلب موضع القبول والإنكار؛ فتخصيصه يكشف أن رفضهم ناشئ من فساد التلقي الباطن، مع قيام أدلة الوحدانية، لا من خفاء الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص238، تحت «بلاغة المقابلة في تخصيص الإنكار بالقلوب وتعميم الاستكبار»","url":""}]},{"id":"s16-48","number":48,"surah":16,"verses":[22],"references":[{"surah":16,"verses":[22]}],"verseLabel":"النحل: 22","question":"ما دلالة ختام الآية بـ﴿وَهُمْ مُسْتَكْبِرُونَ﴾؟","answer":"يقرن الختام إنكار القلوب باستكبار يشمل حالهم كلها؛ والجملة الاسمية تدل على تمكن هذا الوصف ورسوخه، لا صدوره عارضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص239، تحت «فائدة التعبير بالاسمية»","url":""}]},{"id":"s16-49","number":49,"surah":16,"verses":[23],"references":[{"surah":16,"verses":[23]}],"verseLabel":"النحل: 23","question":"أين تتجلى براعة تركيب لا جرم في سياقه في قوله تعالى: ﴿لَا جَرَمَ﴾؟","answer":"تركيب تحقيق وقطع، يقرر علم الله بالسر والعلن وجزاء المستكبرين بلا تردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص240، تحت «براعة تركيب لا جرم في سياقه»","url":""}]},{"id":"s16-50","number":50,"surah":16,"verses":[24],"references":[{"surah":16,"verses":[24]},{"surah":83,"verses":[13]}],"verseLabel":"النحل: 24؛ المطففين: 13","question":"ما نكتة رفع ﴿أساطير الأولين﴾ في سورة النحل؟","answer":"جاء الرفع على تقدير: هو أساطير الأولين؛ فحكوا حكمهم الباطل على الوحي معرضين عن الإقرار بأنه تنزيل من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص248، تحت «نكتة رفع لفظ أساطير»","url":""}]},{"id":"s16-210","number":210,"surah":16,"verses":[24],"references":[{"surah":16,"verses":[24]},{"surah":83,"verses":[13]}],"verseLabel":"النحل: 24؛ المطففين: 13","question":"ما دلالة قول المكذب في سورة المطففين: ﴿أساطير الأولين﴾؟","answer":"يصور اعتياده رد آيات الله بأنها خرافات قديمة، ليعرض عن حججها ومواعظها من غير نظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج66، ص482، تحت «دلالة استعمال لفظ أساطير»","url":""}]},{"id":"s16-51","number":51,"surah":16,"verses":[25],"references":[{"surah":16,"verses":[25]}],"verseLabel":"النحل: 25","question":"ما وجه البلاغة في الاستعارة التمثيلية في حمل الأوزار في قوله تعالى: ﴿ليحملوا أوزارهم﴾؟","answer":"صورت الذنوب أحمالًا ثقيلة تلازم أصحابها يوم القيامة، تجسيدًا لعظم تبعتها ومشقة جزائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص250، تحت «بلاغة الاستعارة التمثيلية في حمل الأوزار»","url":""}]},{"id":"s16-211","number":211,"surah":16,"verses":[25],"references":[{"surah":16,"verses":[25]}],"verseLabel":"النحل: 25","question":"ما دلالة تقييد الأوزار بقوله: ﴿كاملة﴾؟","answer":"يؤكد أنهم يتحملون تبعة ذنوبهم غير منقوصة، فلا يفلت شيء منها ولا تسقط عنهم كما يتوهمون.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص251، تحت «بلاغة التقييد بالحال»","url":""}]},{"id":"s16-52","number":52,"surah":16,"verses":[25],"references":[{"surah":16,"verses":[25]}],"verseLabel":"النحل: 25","question":"ما معنى من ودلالتها في قوله تعالى: ﴿وَمِنْ أَوْزَارِ الَّذِينَ يُضِلُّونَهُمْ﴾؟","answer":"يُضاف إلى وزرهم وزر إضلال غيرهم. ومن توجيه «من» التبعيض: يحملون من أوزار الأتباع ما تسببوا فيه بإضلالهم، فلا تختلط مسؤولية المضل بمطلق أعمال من تبعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص252، تحت «معنى من ودلالتها»","url":""}]},{"id":"s16-53","number":53,"surah":16,"verses":[27],"references":[{"surah":16,"verses":[27]}],"verseLabel":"النحل: 27","question":"ما وجه البلاغة في الاستعارة التمثيلية في قوله تعالى: ﴿فَأَتَى اللَّهُ بُنْيَانَهُمْ مِنَ الْقَوَاعِدِ﴾؟","answer":"تُصوّر الاستعارة مكرهم كبنيان أحكموا قواعده، ثم صار انهياره سبب هلاكهم؛ وإتيانه من القواعد يصور إبطال المكر من أصوله واستئصاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص261، تحت «بلاغة الاستعارة التمثيلية»","url":""}]},{"id":"s16-54","number":54,"surah":16,"verses":[27],"references":[{"surah":16,"verses":[27]}],"verseLabel":"النحل: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿فَخَرَّ عَلَيْهِمُ السَّقْفُ مِنْ فَوْقِهِمْ﴾ مع أن السقف فوق؟","answer":"القيد يؤكد أن السقف وقع عليهم وهم تحته، ويدفع احتمال سقوط سقف آخر أو وقوعه بعيدًا عنهم. ومع ذكر القواعد تكتمل صورة الهلاك المحيط بالبنيان وأهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص264، تحت «فائدة التقييد باللازم المعلوم»","url":""}]},{"id":"s16-55","number":55,"surah":16,"verses":[28],"references":[{"surah":16,"verses":[28]}],"verseLabel":"النحل: 28","question":"ما دلالة ﴿من﴾ في قولهم: ﴿ما كنا نعمل من سوء﴾؟","answer":"جاءت لتوكيد الاستغراق في سياق النفي، فبالغوا في ادعاء أنهم لم يعملوا أدنى سوء.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص293، تحت «دلالة من في قوله من سوء»","url":""}]},{"id":"s16-212","number":212,"surah":16,"verses":[28],"references":[{"surah":16,"verses":[28]}],"verseLabel":"النحل: 28","question":"ما دلالة الرد على إنكارهم بقوله تعالى: ﴿بلى﴾؟","answer":"أبطلت ﴿بلى﴾ نفيهم وأثبتت وقوع ما أنكروه، ثم قررت أن الله عليم بأعمالهم فلا ينفعهم الجحود.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص294، تحت «توجيه التعبير ببلى»","url":""}]},{"id":"s16-56","number":56,"surah":16,"verses":[29],"references":[{"surah":16,"verses":[29]}],"verseLabel":"النحل: 29","question":"ما سرّ التعبير في قوله تعالى: ﴿فَادْخُلُوا أَبْوَابَ جَهَنَّمَ﴾ بالجمع؟","answer":"الجمع يوافق تعدد أبواب جهنم؛ فهي سبعة أبواب كما بُيّن في سورة الحجر. وفي ذكر الدخول من أبوابها إظهار لما يستقبلهم من مراتب العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص301، 302، تحت «نكتة جمع الأبواب جمع قلة»","url":""}]},{"id":"s16-57","number":57,"surah":16,"verses":[30],"references":[{"surah":16,"verses":[30]}],"verseLabel":"النحل: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَدَارُ الْآخِرَةِ خَيْرٌ﴾ لا الجنة فقط؟","answer":"«دار الآخرة» تناسب مقابلة نعيم الآخرة بالحسنة في الدنيا؛ فالحديث عن مقام الجزاء وخيريته. وإسناد الخير إلى الدار يشمل ما فيها من خير لأهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص320، تحت «إيثار تركيب دار الآخرة دون القيامة أو غيره»","url":""}]},{"id":"s16-59","number":59,"surah":16,"verses":[32],"references":[{"surah":16,"verses":[32]}],"verseLabel":"النحل: 32","question":"ما بلاغة قول الملائكة للمتقين: ﴿سلام عليكم﴾؟","answer":"الجملة الاسمية تثبت لهم السلام والأمان، وتسبق بشارة الجنة بتحية تطمئنهم عند الوفاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص340، تحت «براعة التعبير عن سلامهم بالجملة الاسمية»","url":""}]},{"id":"s16-213","number":213,"surah":16,"verses":[32],"references":[{"surah":16,"verses":[32]}],"verseLabel":"النحل: 32","question":"ما دلالة قول الملائكة للمتقين: ﴿ادخلوا الجنة﴾؟","answer":"الأمر بشارة وإكرام بما أعد لهم من الجنة جزاء أعمالهم، ولا يلزم منه أن يكون الدخول فور الوفاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص340، تحت «دلالة الأمر في ادخلوا»","url":""}]},{"id":"s16-60","number":60,"surah":16,"verses":[33],"references":[{"surah":16,"verses":[33]}],"verseLabel":"النحل: 33","question":"ما وجه البلاغة في الاستعارة التهكمية في ينظرون في قوله تعالى: ﴿هَلْ يَنْظُرُونَ إِلَّا أَنْ تَأْتِيَهُمُ الْمَلَائِكَةُ﴾؟","answer":"ينفي السياق أن يبقى بعد إعراضهم إلا حلول ما وُعدوا به؛ وصُوّر بقاؤهم قبل الموت أو العذاب بصورة المنتظر له، على سبيل التهكم والتهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص346، تحت «بلاغة الاستعارة التهكمية في ينظرون»","url":""}]},{"id":"s16-61","number":61,"surah":16,"verses":[34],"references":[{"surah":16,"verses":[34]}],"verseLabel":"النحل: 34","question":"ما سرّ التعبير بـ﴿مَا عَمِلُوا﴾ هنا، بعد ﴿كَذَلِكَ فَعَلَ الَّذِينَ مِنْ قَبْلِهِمْ﴾؟","answer":"المقام مقام جزاء وحساب على فعل مقصود؛ فناسبه «عملوا»، لأن العمل أخص بالقصد، أما الفعل فأعم وقد يقع من غير قصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص361، تحت «علة العدول من فعلوا إلى عملوا»","url":""}]},{"id":"s16-62","number":62,"surah":16,"verses":[35],"references":[{"surah":16,"verses":[35]}],"verseLabel":"النحل: 35","question":"ما دلالة حكاية احتجاج المشركين بـ﴿لَوْ شَاءَ اللَّهُ مَا عَبَدْنَا﴾؟","answer":"جعلوا تمكين الله لهم وإمهاله إياهم دليلًا على رضاه عن شركهم، مع أنه نهاهم عنه وأرسل الرسل بالبيان؛ فخلطوا بين وقوع الفعل بمشيئته وبين محبته له ورضاه عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص371، تحت «سر حكاية احتجاجهم في قوله لو شاء الله»","url":""}]},{"id":"s16-63","number":63,"surah":16,"verses":[36],"references":[{"surah":16,"verses":[36]}],"verseLabel":"النحل: 36","question":"ما الغرض البلاغي من تقديم في كل أمة في قوله تعالى: ﴿فِي كُلِّ أُمَّةٍ رَسُولًا﴾؟","answer":"ليثبت عموم الحجة عبر التاريخ؛ لا أمة تُركت بلا بيان أصل التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص391، تحت «الغرض من تقديم في كل أمة»","url":""}]},{"id":"s16-64","number":64,"surah":16,"verses":[36],"references":[{"surah":16,"verses":[36]}],"verseLabel":"النحل: 36","question":"ما دلالة الجمع بين ﴿اعْبُدُوا اللَّهَ﴾ و﴿اجْتَنِبُوا الطَّاغُوتَ﴾؟","answer":"التوحيد يجمع إثبات العبادة لله واجتناب عبادة غيره؛ فالأمران متكاملان. و«اجتنبوا» أبلغ من مجرد الترك، لأنها تصور البعد عن الطاغوت وجعل العبد في جانب غير جانبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص393، تحت «نكتة عطف الجملتين المتقابلتين بالواو»","url":""}]},{"id":"s16-65","number":65,"surah":16,"verses":[36],"references":[{"surah":16,"verses":[36]}],"verseLabel":"النحل: 36","question":"ما دلالة اختيار لفظ ﴿الطَّاغُوتَ﴾؟","answer":"أصل اللفظ من الطغيان، وهو مجاوزة الحد؛ ويُطلق هنا على ما عُبد من دون الله، من صنم أو شيطان ونحوهما، فيجمع صور العبادة الباطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص401، تحت «الطاغوت والشيطان»","url":""}]},{"id":"s16-66","number":66,"surah":16,"verses":[37],"references":[{"surah":16,"verses":[37]}],"verseLabel":"النحل: 37","question":"ما دلالة التعريض في سياق الشرط في قوله تعالى: ﴿إِنْ تَحْرِصْ عَلَى هُدَاهُمْ﴾؟","answer":"في الشرط بيان شدة حرص النبي ورأفته بقومه، مع تقرير أن حرصه لا يستقل بتحقيق الهداية؛ فالتوفيق إلى الهدى بيد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص406، تحت «دلالة التعريض في سياق الشرط»","url":""}]},{"id":"s16-67","number":67,"surah":16,"verses":[38],"references":[{"surah":16,"verses":[38]}],"verseLabel":"النحل: 38","question":"ما دلالة ﴿جَهْدَ أَيْمَانِهِمْ﴾ في قسمهم على نفي البعث؟","answer":"جمعوا القسم وبذل غاية الجهد في توكيد إنكار البعث؛ فتظهر المفارقة في قسمهم بالله على نفي قدرته على الإعادة. ثم تنقض «بلى» نفيهم وتثبت البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص418، تحت «دلالة الجمع بين أقسموا وجهد أيمانهم»","url":""}]},{"id":"s16-68","number":68,"surah":16,"verses":[38],"references":[{"surah":16,"verses":[38]}],"verseLabel":"النحل: 38","question":"ما موقع وعدا ودلالته في الآية الكريمة في قوله تعالى: ﴿وَعْدًا عَلَيْهِ حَقًّا﴾؟","answer":"جعل البعث وعدًا تفضل بإيجابه على نفسه، ثم أكده بالحق ليقطع الشك.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص421، تحت «موقع وعدا ودلالته في الآية الكريمة»","url":""}]},{"id":"s16-69","number":69,"surah":16,"verses":[40],"references":[{"surah":16,"verses":[40]}],"verseLabel":"النحل: 40","question":"ما دلالة القدرة المطلقة في قوله كن فيكون؟","answer":"يصور التعبير كمال القدرة وسهولة الإيجاد؛ فما أراده الله لا يعجزه ولا يحتاج في إيجاده إلى معالجة أو معين. والمقصود تقرير نفاذ إرادته وقدرته على البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص438، تحت «دلالة القدرة المطلقة في قوله كن فيكون»","url":""}]},{"id":"s16-70","number":70,"surah":16,"verses":[41,42],"references":[{"surah":16,"verses":[41,42]}],"verseLabel":"النحل: 41-42","question":"ما دلالة الجمع بين الهجرة والصبر والتوكل؟","answer":"وُصف المهاجرون بالصبر على أذى المشركين ومفارقة الوطن، وبالتوكل على الله في جميع أمورهم. فجمعوا احتمال المشقة وبذل السبب مع اعتماد القلب على ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص453، تحت «دلالة الجمع بين الصبر والتوكل»","url":""}]},{"id":"s16-71","number":71,"surah":16,"verses":[43],"references":[{"surah":16,"verses":[43]},{"surah":21,"verses":[7]}],"verseLabel":"النحل: 43؛ الأنبياء: 7","question":"ما سرّ الأمر بقوله تعالى في النحل: ﴿فاسألوا أهل الذكر﴾؟","answer":"أحال المنكرين لبشرية الرسل إلى أهل العلم بالكتب السابقة، إلزامًا لهم بما تثبته أخبار الرسل من أنهم بشر يوحى إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص470، تحت «سر الأمر بسؤال أهل الذكر»","url":""}]},{"id":"s16-214","number":214,"surah":16,"verses":[43],"references":[{"surah":16,"verses":[43]},{"surah":21,"verses":[7]}],"verseLabel":"النحل: 43؛ الأنبياء: 7","question":"ما براعة التعبير بـ﴿أهل الذكر﴾ في سورة الأنبياء دون «أهل الكتاب»؟","answer":"اللفظ أعم في وصف أهل العلم بالوحي، فيرشد إلى سؤال العارفين ويوبخ من اتخذ الجهل حجة لإنكار حقيقة معلومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص116، تحت «براعة استعمال أهل الذكر دون أهل الكتاب»","url":""}]},{"id":"s16-72","number":72,"surah":16,"verses":[44],"references":[{"surah":16,"verses":[44]}],"verseLabel":"النحل: 44","question":"ما دلالة إسناد مهمة التبيين للرسول في قوله تعالى: ﴿لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ﴾؟","answer":"جُعل بيان المنزل للناس غايةً من إنزال الذكر على الرسول؛ فمهمته تبليغ ألفاظه وإيضاح معانيه وما يحتاج إليه الناس للعمل به والاهتداء به.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص483، تحت «دلالة إسناد مهمة التبيين للرسول»","url":""}]},{"id":"s16-73","number":73,"surah":16,"verses":[44],"references":[{"surah":16,"verses":[44]}],"verseLabel":"النحل: 44","question":"ما دلالة ختام الآية بـ﴿لَعَلَّهُمْ يَتَفَكَّرُونَ﴾؟","answer":"البيان يرفع الغموض، ثم يبقى على الناس أن يعملوا الفكر حتى يبلغوا المراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص487، تحت «غرض استعمال أداة الرجاء لعل»","url":""}]},{"id":"s16-74","number":74,"surah":16,"verses":[45],"references":[{"surah":16,"verses":[45]}],"verseLabel":"النحل: 45","question":"ما سرّ التنصيص على الخسف في قوله تعالى: ﴿أَنْ يَخْسِفَ اللَّهُ بِهِمُ الْأَرْضَ﴾؟","answer":"الخسف نوع من العذاب يصير به موضع الاستقرار سببًا للهلاك؛ وفي تخصيصه تهديد لمن اغتروا بالأمن، وتصوير لقدرة الله على أن يذهب بهم في الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص496، تحت «سر التنصيص على الخسف»","url":""}]},{"id":"s16-75","number":75,"surah":16,"verses":[46],"references":[{"surah":16,"verses":[46]}],"verseLabel":"النحل: 46","question":"ما سرّ استعمال المصدر الصريح تقلبهم في قوله تعالى: ﴿أَوْ يَأْخُذَهُمْ فِي تَقَلُّبِهِمْ﴾؟","answer":"أي أثناء حركتهم في المعاش والسفر؛ العذاب لا يحتاج انتظار سكونهم أو استعدادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص504، تحت «سر استعمال المصدر الصريح تقلبهم»","url":""}]},{"id":"s16-76","number":76,"surah":16,"verses":[47],"references":[{"surah":16,"verses":[47]}],"verseLabel":"النحل: 47","question":"ما وجه البلاغة في التعبير بالمصدر تخوف في قوله تعالى: ﴿أَوْ يَأْخُذَهُمْ عَلَى تَخَوُّفٍ﴾؟","answer":"أي على تنقص تدريجي أو حال خوف؛ فالعقوبة قد تفجأ وقد تتدرج أمام العين.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص511، تحت «بلاغة التعبير بالمصدر تخوف»","url":""}]},{"id":"s16-77","number":77,"surah":16,"verses":[47],"references":[{"surah":16,"verses":[47]}],"verseLabel":"النحل: 47","question":"ما سرّ ختام صور الأخذ بـ﴿رَءُوفٌ رَحِيمٌ﴾؟","answer":"لأن الإمهال والتحذير قبل المؤاخذة رأفة ورحمة، لا عجزًا عن الأخذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص514، تحت «دلالة ذكر الرأفة والرحمة بعد ذكر أنواع العذاب»","url":""}]}]);
